window.LAW_DATA = {"id": "madani", "title": "القانون المدني", "title_en": "CIVIL CODE", "cat": "مدني", "icon": "⚖️", "desc": "القانون رقم 131 لسنة 1948 — الالتزامات، العقود، الملكية، والحقوق العينية والشخصية.", "article_count": 924, "articles": [{"number": "1", "chapter": "", "text": "يلغى القانون المدنى المعمول به أمام المحاكم الوطنية والصادر فى 28 أكتوبر سنة 1883 والقانون المدنى المعمول به أمام المحاكم المختلطة والصادر فى 28 يونية سنة 1875 ويستعاض عنهما بالقانون المدنى المرافق لهذا القانون."}, {"number": "2", "chapter": "", "text": "على وزير العدل تنفيذ هذا القانون ويعمل به ابتداء من 15 اكتوبر سنة 1949. نأمر بأن يبصم هذا القانون بخاتم الدولة وان ينشر فى الجريدة الرسمية وينفذ كقانون من قوانين الدولة. صدر بقصر القبة فى 9 رمضان سنة 1367 هـ ( 16 يوليو سنة 1948 م )."}, {"number": "1", "chapter": "الفصل الأول", "text": "( 1 ) تسرى النصوص التشريعية على جميع المسائل التى تتناولها هذه النصوص فى لفظها أو فى فحواها. ( 2 ) فإذا لم يوجد نص تشريعى يمكن تطبيقه ، حكم القاضى بمقتضى العرف ، فإذا لم يوجد ، فبمقتضى مبادئ الشريعة الإسلامية ، فإذا لم توجد ، فبمقتضى مبادئ القانون الطبيعى وقواعد العدالة."}, {"number": "2", "chapter": "الفصل الأول", "text": "لا يجوز إلغاء نص تشريعى الا بتشريع لاحق ينص صراحة على هذا الإلغاء ، أو يشتمل على نص يتعارض مع نص التشريع القديم ، أو ينظم من جديد الموضوع الذى سبق أن قرر قواعده ذلك التشريع."}, {"number": "3", "chapter": "الفصل الأول", "text": "تحسب المواعيد بالتقويم الميلادى ، ما لم ينص القانون على غير ذلك."}, {"number": "4", "chapter": "الفصل الأول", "text": "من استعمل حقه استعمالا مشروعا لا يكون مسئولا عما ينشأ عن ذلك من ضرر."}, {"number": "5", "chapter": "الفصل الأول", "text": "يكون استعمال الحق غير المشروع فى الأحوال الآتية : أ - إذا لم يقصد به سوى الإضرار بالغير. ب - إذا كانت المصالح التى يرمى تحقيقها قليلة الأهمية بحيث لا تتناسب البتة مع ما يصيب الغير من ضرر بسببها. جـ – إذا كانت المصالح التى يرمى إلى تحقيقها غير مشروعه. 2 - تطبيق القانون تنازع القوانين من حيث الزمان"}, {"number": "6", "chapter": "الفصل الأول", "text": "( 1 ) النصوص المتعلقة بالأهلية تسرى على جميع الأشخاص الذين تنطبق عليهم الشروط المقررة فى هذه النصوص. ( 2 ) وإذا عاد شخص توافرت فيه الأهلية. بحسب نصوص قديمة. ناقص الأهلية بحسب نصوص جديدة. فإن ذلك لا يؤثر فى تصرفاته السابقة."}, {"number": "7", "chapter": "الفصل الأول", "text": "تسرى النصوص الجديدة المتعلقة بالتقادم من وقت العمل بها على كل تقادم لم يكتمل. على أن النصوص القديمة هى التى تسرى على المسائل الخاصة ببدء التقادم ووقفة وانقطاعه. وذلك عن المدة السابقة على العمل بالنصوص الجديدة"}, {"number": "8", "chapter": "الفصل الأول", "text": "إذا قرر النص الجديد مدة للتقادم أقصر مما قرر النص القديم سرت المدة الجديدة من وقت العمل بالنص الجديد ، ولو كانت المدة القديمة قد بدأت قبل ذلك. ( 2 ) اما إذا كان الباقى من المدة التى نص عليها القانون القديم أقصر من المدة التى قررها النص الجديد ، فإن التقادم يتم بانقضاء هذا الباقى."}, {"number": "9", "chapter": "الفصل الأول", "text": "تسرى فى شأن الأدلة التى تعد مقدما النصوص المعمول بها فى الوقت الذى اعد فيه الدليل. أو فى الوقت الذى كان ينبغى فيه إعداده. 3 - تنازع القوانين من حيث المكان"}, {"number": "10", "chapter": "الفصل الأول", "text": "القانون المصرى مر المرجع فى تكييف العلاقات عندما يطلب تحديد نوع هذه العلاقات فى قضية تتنازع فيها القوانين ، لمعرفة القانون الواجب تطبيقه من بينها."}, {"number": "11", "chapter": "الفصل الأول", "text": "( 1 ) الحالة المدنية للأشخاص وأهليتهم يسرى عليها قانون الدولة التى ينتمون إليها بجنسيتهم. ومع ذلك ففى التصرفات المالية التى تعقد فى مصر وتترتب آثارها فيها ، إذا كان أحد الطرفين أجنبيا ناقص الأهلية وكان نقص الأهلية يرجع إلى سبب فيه خفاء لا يسهل على الطرف الآخر تبينه ، فإن هذا السبب لا يؤثر فى أهليته. ( 2 ) اما النظام القانونى للأشخاص الإعتبارية الأجنبية ، من شركات وجمعيات ومؤسسات وغيرها ، فيسرى عليه قانون الدولة التى اتخذت فيها هذه الأشخاص مركز إدارتها الرئيسى الفعلى. ومع ذلك فإذا باشرت نشاطها الرئيس فى مصر ، فإن القانون المصرى هو الذى يسرى."}, {"number": "12", "chapter": "الفصل الأول", "text": "يرجع فى الشروط الموضوعية لصحة الزواج إلى قانون كل من الزوجين."}, {"number": "13", "chapter": "الفصل الأول", "text": "( 1 ) يسرى قانون الدولة التى ينتمى إليها الزوج وقت انعقاد الزواج على الآثار التى يرتبها عقد الزواج ، بما فى ذلك من أثر بالنسبة إلى المال. ( 2 ) اما فى الطلاق فيسرى عليه قانون الدولة التى ينتمى إليها الزوج وقت الطلاق. ويسرى على التطليق والانفصال قانون الدولة التى ينتمى إليها الزوج وقت رفع الدعوى."}, {"number": "14", "chapter": "الفصل الأول", "text": "فى الأحوال المنصوص عليها فى المادتين السابقتين إذا كان أحد الزوجين مصريا وقت انعقاد الزواج ، يسرى القانون المصرى وحده ، فيما عدا شرط الأهلية للزواج."}, {"number": "15", "chapter": "الفصل الأول", "text": "يسرى على الإلتزام بالنفقة فيما بين الأقارب ، قانون المدين بها."}, {"number": "16", "chapter": "الفصل الأول", "text": "يسرى على المسائل الموضوعية الخاصة بالولاية والوصاية والقوامة وغيرها من النظم الموضوعية لحماية المحجورين والغائبين ، قانون الشخص الذى تجب حمايته."}, {"number": "17", "chapter": "الفصل الأول", "text": "( 1 ) يسرى على الميراث والوصية وسائر التصرفات المضافة إلى ما بعد الموت. قانون المورث أو الموصى أو من صدر منه التصرف وقت موته. ( 2 ) ومع ذلك تسرى على شكل الوصية ، قانون الموصى وقت الايصاء أو قانون البلد الذى تمت فيه الوصية ، وكذلك الحكم فى شكل سائر التصرفات المضافة إلى ما بعد الموت."}, {"number": "18", "chapter": "الفصل الأول", "text": "يسرى على الحيازة والملكية والحقوق العينية الأخرى ، قانون الموقع فيما يختص بالعقار ، ويسرى بالنسبة إلى المنقول قانون الجهة التى يوجد فيها هذا المنقول وقت تحقق السبب الذى ترتب عليه كسب الحيازة أو الملكية أو الحقوق العينية الأخرى أو فقدها."}, {"number": "19", "chapter": "الفصل الأول", "text": "( 1 ) يسرى على الإلتزامات التعاقدية قانون الدولة التى يوجد فيها الموطن المشترك للمتعاقدين إذا اتحدا موطنا ، فإن اختلفا موطنا سرى قانون الدولة التى تم قيها العقد. هذا ما لم يتفق المتعاقدان أو يتبين من الظروف أن قانونا آخر هو الذى يراد تطبيقه. ( 2 ) على أن قانون موقع العقار هو الذى يسرى على العقود التى أبرمت فى شأن هذا العقار."}, {"number": "20", "chapter": "الفصل الأول", "text": "العقود ما بين الأحياء تخضع فى شكلها لقانون البلد الدعوى تمت فيه ، ويجوز أيضا أن تخضع للقانون الذى يسرى على أحكامها الموضوعية ، كما يجوز أن تخضع لقانون موطن المتعاقدين وقانونهما الوطنى المشترك."}, {"number": "21", "chapter": "الفصل الأول", "text": "( 1 ) يسرى على الإلتزامات غير التعاقدية قانون البلد الذى وقع فيه الفعل المنشئ للإلتزام. ( 2 ) على انه فيما يتعلق بالإلتزامات الناشئة عن الفعل الضار ، لا تسرى أحكام الفقرة السابقة على الوقائع التى تحدث فى الخارج وتكون مشروعة فى مصر وان كانت تعد غير مشروعة فى البلد الدعوى وقعت فيه."}, {"number": "22", "chapter": "الفصل الأول", "text": "يسرى على تواعد الاختصاص وجميع المسائل الخاصة بالإجراءات قانون البلد الذى تقام فيه الدعوى أو تباشر فيه الإجراءات."}, {"number": "23", "chapter": "الفصل الأول", "text": "لا تسرى أحكام المواد السابقة الا حيث لا يوجد نص على خلاف ذلك فى قانون خاص أو فى معاهدة دولية نافذة فى مصر."}, {"number": "24", "chapter": "الفصل الأول", "text": "تتبع فيما لم يرد فى شأنه نص فى المواد السابقة من أحوال تنازع القوانين مبادئ القانون الدولى الخاص."}, {"number": "25", "chapter": "الفصل الأول", "text": "( 1 ) يعين القاضى القانون الذى يجب تطبيقه فى حالة الأشخاص الذين لا تعرف لهم جنسية ، أو الذين تثبت لهم جنسيات متعددة فى وقت واحد. ( 2 ) على أن الأشخاص الذين تثبت لهم وقت واحد بالنسبة إلى مصر الجنسية المصرية ، وبالنسبة إلى دولة أجنبية أو عدة دول أجنبية جنسية تلك الدول ، فالقانون المصرى هو الذى يجب تطبيقه."}, {"number": "26", "chapter": "الفصل الأول", "text": "متى ظهر من الأحكام الواردة فى المواد المتقدمة أن القانون الواجب التطبيق هو قانون دولة معينة تتعدد فيها الشرائع ، فإن القانون الداخلى لتلك الدولة هو الذى يقرر أية شريعة من هذه يجب تطبيقها."}, {"number": "27", "chapter": "الفصل الأول", "text": "إذا تقرر أن قانونا أجنبيا هو الواجب التطبيق ، فلا يطبق منه الا أحكامه الداخلية ، دون التى تتعلق بالقانون الدولى الخاص."}, {"number": "28", "chapter": "الفصل الأول", "text": "لا يجوز تطبيق أحكام قانون أجنبى عينته النصوص السابقة . إذا كانت هذه الأحكام مخالفة للنظام العام أو للآداب فى مصر."}, {"number": "29", "chapter": "الفصل الثانى", "text": "( 1 ) تبدأ شخصية الانسان بتمام ولادته حيا. وتنتهى بموته. ( 2 ) ومع ذلك فحقوق الحمل المستكن يبينها القانون."}, {"number": "30", "chapter": "الفصل الثانى", "text": "( 1 ) تثبت الولادة والوفاة بالسجلات الرسمية المعدة لذلك. ( 2 ) فإذا لم يوجد هذا الدليل ، أو تبين عدم صحة ما ادرج بالسجلات ، جاز الإثبات بأية طريقة اخرى."}, {"number": "31", "chapter": "الفصل الثانى", "text": "دفاتر المواليد والوفيات والتبليغات المتعلقة بها ، ينظمها قانون خاص."}, {"number": "32", "chapter": "الفصل الثانى", "text": "يسرى فى شأن المفقود والغائب الأحكام المقررة فى قوانين خاصة ، فإن لم توجد فأحكام الشريعة الإسلامية."}, {"number": "33", "chapter": "الفصل الثانى", "text": "الجنسية المصرية ينظمها قانون خاص."}, {"number": "34", "chapter": "الفصل الثانى", "text": "( 1 ) تتكون أسرة الشخص من ذوى قرباه. ( 2 ) وتعتبر من ذوى القربى كل من يجمعهم أصل مشترك."}, {"number": "35", "chapter": "الفصل الثانى", "text": "( 1 ) القرابة المباشرة هى الصلة ما بين الأصول والفروع. ( 2 ) وقرابة الحواشى هى الرابطة ما بين أشخاص يجمعهم أصل مشترك ، دون أن يكون أحدهم فرعا للآخر."}, {"number": "36", "chapter": "الفصل الثانى", "text": "يراعى فى حساب درجة القرابة المباشرة ، إعتبار كل فرع درجة عند الصعود للأصل بخروج هذا الأصل ، وعند حساب درجة الحواشى تعد الدرجات صعودا من الفرع للأصل المشترك ، ثم نزولا منه إلى الفرع الآخر ، وكل فرع فيما عدا الأصل المشترك يعتبر درجة."}, {"number": "37", "chapter": "الفصل الثانى", "text": "أقارب أحد الزوجين يعتبرون فى نفس القرابة والدرجة بالنسبة إلى الزوج الآخر."}, {"number": "38", "chapter": "الفصل الثانى", "text": "يكون لكل شخص أسم ولقب ، ولقب الشخص يلحق أولاده."}, {"number": "39", "chapter": "الفصل الثانى", "text": "ينظم بتشريع خاص كيفية اكتساب الألقاب وتغييرها."}, {"number": "40", "chapter": "الفصل الثانى", "text": "( 1 ) الموطن هو المكان الذى يقيم فيه الشخص عادة. ( 2 ) ويجوزان يكون للشخص فى وقت واحد أكثر من موطن ، كما يجوز الا يكون له موطن ما."}, {"number": "41", "chapter": "الفصل الثانى", "text": "يعتبر المكان الذى يباشر فيه الشخص تجارة أو حرفة موطنا بالنسبة إلى إدارة الأعمال المتعلقة بهذه التجارة أو الحرفة."}, {"number": "42", "chapter": "الفصل الثانى", "text": "( 1 ) موطن القاصر والمحجور عليه والمفقود والغائب هو موطن من ينوب عن هؤلاء قانونا. ( 2 ) ومع ذلك يكون للقاصر الدعوى بلغ ثمانى عشرة سنة ومن فى حكمه موطن خاص ، بالنسبة إلى الأعمال والتصرفات التى يعتبره القانون أهلا لمباشرتها."}, {"number": "43", "chapter": "الفصل الثانى", "text": "( 1 ) يجوز أتخاذ موطن مختار لتنفيذ عمل قانونى معين. ( 2 ) ولا يجوز إثبات وجود الموطن المختار الا بالكتابة. ( 3 ) والموطن المختار لتنفيذ عمل قانونى يكون هو الموطن بالنسبة إلى كل ما يتعلق بهذا العمل ، بما فى ذلك إجراءات التنفيذ الجبرى ، الا إذا اشتر صراحة قصر هذا الموطن على أعمال دون اخرى."}, {"number": "44", "chapter": "الفصل الثانى", "text": "( 1 ) كل شخص بلغ سن الرشد متمتعا بقواه العقلية ، ولم يحجر عليه ، يكون كامل الأهلية لمباشرة حقوقه المدنية. ( 2 ) وسن الرشد هى احدى وعشرون سنة ميلادية كاملة."}, {"number": "45", "chapter": "الفصل الثانى", "text": "( 1 ) لا يكون أهلا لمباشرة حقوقه المدنية من كان فاقد التمييز لصغر فى السن أو عته أو جنون. ( 2 ) وكل من لم يبلغ السابعة يعتبر فاقدا للتمييز."}, {"number": "46", "chapter": "الفصل الثانى", "text": "كل من بلغ سن التمييز ولم يبلغ سن الرشد ، وكل من بلغ سن الرشد وكان سفيها أو ذا غفلة ، يكون ناقص الأهلية وفقا لما يقرره القانون."}, {"number": "47", "chapter": "الفصل الثانى", "text": "يخضع فاقدوا الأهلية وناقصوها بحسب الأحوال لأحكام الولاية والوصاية أو القوامة بالشروط ووفقا للقواعد المقررة فى القانون."}, {"number": "48", "chapter": "الفصل الثانى", "text": "ليس لأحد النزول عن أهليته ولا التعديل فى أحكامها."}, {"number": "49", "chapter": "الفصل الثانى", "text": "ليس لأحد النزول عن حريته الشخصية."}, {"number": "50", "chapter": "الفصل الثانى", "text": "لكل من وقع عليه اعتداء غير مشروع فى حق من الحقوق الملازمة لشخصيته ، أن يطلب وقف هذا الاعتداء مع التعويض عما يكون قد لحقه من ضرر."}, {"number": "51", "chapter": "الفصل الثانى", "text": "لكل من نازعه الغير فى استعمال اسمه بلا مبرر. ومن انتحل الغير اسمه دون حق ، أن يطلب وقف هذا الاعتداء مع التعويض عما يكون قد لحقه من ضرر. 2 - الشخص الاعتبارى"}, {"number": "52", "chapter": "الفصل الثانى", "text": "الأشخاص الإعتبارية هى : 1 - الدولة وكذلك المديريات والمدن والقرى بالشروط التى يحددها القانون والإدارات والمصالح وغيرها من المنشآت العامة التى يمنحها القانون شخصية إعتبارية. 2 - الهيئات والطوائف الدينية التى تعترف لها الدولة شخصية إعتبارية. 3 - الأوقاف. 4 - الشركات التجارية والمدنية. 5 - الجمعيات والمؤسسات المنشاة وفقا للأحكام التق ستأتى فيما بعد. 6 - كل مجموعة من الأشخاص أو الأموال تثبت لها الشخصية الإعتبارية بمقتضى نص فى القانون."}, {"number": "53", "chapter": "الفصل الثانى", "text": "( 1 ) الشخص الاعتبارى يتمتع بجميع الحقوق الا ما كان منها ملازما لصفة الإنسان الطبيعية ، وذلك فى الحدود التى قررها القانون. ( 2 ) فيكون له : أ - ذمة مالية مستقلة. ب - أهلية فى الحدود التى يعينها سند انشائه ، أو التى يقررها القانون. ج - حق التقاضى. د - موطن مستقل. ويعتبر موطنه المكان الذى يوجد فيه مركز إدارته. والشركات التى يكون مركزها الرئيس فى الخارج ولها نشاط فى مصر يعتبر مركز إدارتها ، بالنسبة إلى القانون الداخلى 5 المكان الذى توجد فيه الإدارة المحلية. ( 3 ) ويكون له نائب يعبر عن إرادته. الجمعيات المواد من 54 إلى 80 .…………… ملغاة"}, {"number": "81", "chapter": "الفصل الثالث", "text": "( 1 ) كل شئ غير خارج عن التعامل بطبيعته أو حكم القانون يصح أن يكون محلا للحقوق المالية. ( 2 ) والأشياء التى تخرج عن التعامل بطبيعتها هى التى لا يستطيع أحد أن يستأثر بحيازتها ، واما الخارجة بحكم القانون فهى التى لا يجيز القانون أن تكون محلا للحقوق المالية."}, {"number": "82", "chapter": "الفصل الثالث", "text": "( 1 ) كل شئ مستقر بحيزه ثابت فيه لا يمكن نقله منه دون تلف ، فهو عقار وكل ما عدا ذلك من شى فهو منقول. ( 2 ) ومع ذلك يعتبر عقارا بالتخصيص ، المنقول الذى يضعه صاحبه فى عقار يملكه ، رصدا على خدمة هذا العقار أو استغلاله."}, {"number": "83", "chapter": "الفصل الثالث", "text": "( 1 ) يعتبر مالا عقاريا كل حق عينى يقع على عقار ، بما فى ذلك حق الملكية ، وكذلك كل دعوى تتعلق بحق عينى على عقار. ( 2 ) ويعتبر مالا منقولا ما عدا ذلك من الحقوق المالية."}, {"number": "84", "chapter": "الفصل الثالث", "text": "( 1 ) الأشياء القابلة للاستهلاك هى التى ينحصر استعمالها بحسب ما أعدت له ، فى استهلاكها أو إنفاقها. ( 2 ) فيعتبر قابلا للاستهلاك كل ما اعد فى المتاجر للبيع."}, {"number": "85", "chapter": "الفصل الثالث", "text": "الأشياء المثلية هى التى يقوم بعضها مقام بعض عند الوفاء ، والتى تقدر عادة فى التعامل بين الناس بالعد أو المقاس أو الكيل أو الوزن."}, {"number": "86", "chapter": "الفصل الثالث", "text": "الحقوق التى ترد على شئ غير مادى تنظمها قوانين خاصة."}, {"number": "87", "chapter": "الفصل الثالث", "text": "( 1 ) تعتبر أموالا عامة ، العقارات والمنقولات التى للدولة أو للأشخاص الإعتبارية العامة ، والتى تكون مخصصة لمنفعة عامة بالفعل أو بمقتضى قانون أو مرسوم أو قرار من الوزير المختص. ( 2 ) وهذه الأموال لا يجوز التصرف فيها أو الحجز عليها أو تملكها بالتقادم."}, {"number": "88", "chapter": "الفصل الثالث", "text": "تفقد الأموال العامة صفتها العامة بانتهاء تخصيصهما للمنفعة العامة. وينتهى التخصيص بمقتضى قانون أو مرسوم أو قرار من الوزير المختص أو بالفعل ، أو بانتهاء الغرض الذى من اجله خصصت تلك الأموال للمنفعة العامة."}, {"number": "89", "chapter": "الفصل الأول", "text": "يتم العقد بمجرد أن يتبادل طرفان التعبير عن إرادتين متطابقتين ، مع مراعاة ما يقرره القانون فوق ذلك من أوضاع معينة لانعقاد العقد."}, {"number": "90", "chapter": "الفصل الأول", "text": "( 1 ) التعبير عن الإرادة يكون باللفظ وبالكتابة وبالإشارة المتداولة عرفا ، كما يكون بأتخاذ موقف لا تدع ظروف الحال شكا فى دلالته على حقيقة المقصود. ( 2 ) ويجوز أن يكون التعبير عن الإرادة ضمنيا ، إذا لم ينص القانون أو يتفق الطرفان على أن ككون صريحا."}, {"number": "91", "chapter": "الفصل الأول", "text": "ينتج التعبير عن الإرادة أثره فى الوقت الذى يتصل فيه بعلم من وجه إليه. ويعتبر وصول التعبير قرينة على العلم به ما لم يقم الدليل على عكس ذلك."}, {"number": "92", "chapter": "الفصل الأول", "text": "إذا مات من صدر منه التعبير عن الإرادة أو فقد أهليته قبل أن ينتج التعبير أثره فإن ذلك لا يمنع من ترتب هذا الأثر عند اتصال التعبير بعلم من وجه إليه ، هذا ما لم يتبين العكس من التعبير أو من طبيعة التعامل."}, {"number": "93", "chapter": "الفصل الأول", "text": "( 1 ) إذا عين ميعاد للقبول التزم الموجب بالبقاء على إيجابه إلى أن ينقضى هذا الميعاد. ( 2 ) وقد يستخلص الميعاد من ظروف الحال أو من طبيعة المعاملة."}, {"number": "94", "chapter": "الفصل الأول", "text": "( 1 ) إذا صدر الإيجاب فى مجلس العقد. دون أن يعين ميعاد للقبول. فإن الموجب يتحلل من إيجابه إذا لم يصدر القبول فورا ، كذلك الحال إذا صدر الإيجاب من شخص إلى آخر بطريق التليفون أو بأى طريق مماثل. ( 2 ) ومع ذلك يتم العقد ، ولو لم يصدر القبول فورا ، إذا لم يوجد ما يدل على أن الموجب قد عدل عن إيجابه فى الفترة ما بين الإيجاب والقبول ، وكان القبول قد صدر قبل أن ينفض مجلس العقد."}, {"number": "95", "chapter": "الفصل الأول", "text": "إذا اتفق الطرفان على جميع المسائل الجوهرية فى العقد. واحتفظا بمسائل تفصيلية يتفقان عليها فيما بعد ولم يشترطا أن العقد لا يتم عند عدم الاتفاق عليها ، اعتبر العقد قد تم. وإذا قام خلاف على المسائل التى لم يتم الاتفاق عليها ، فإن المحكمة تقضى فيها طبقا لطبيعة المعاملة ولأحكام القانون والعرف والعدالة."}, {"number": "96", "chapter": "الفصل الأول", "text": "إذا اقترن القبول بما يزيد فى الإيجاب أو يقيد منه أو يعدل فيه ، اعتبر رفضا يتضمن إيجابا جديدا."}, {"number": "97", "chapter": "الفصل الأول", "text": "( 1 ) يعتبر التعاقد ما بين الغائبين قد تم فى المكان وفى الزمان اللذين يعلم فيهما الموجب بالقبول ، ما لم يوجد اتفاق أو نص قانونى يقضى بغير ذلك. ( 2 ) ويفترض أن الموجب قد علم بالقبول فى المكان وفى الزمان اللذين وصل إليه فيهما هذا القبول."}, {"number": "98", "chapter": "الفصل الأول", "text": "( 1 ) إذا كانت طبيعة المعاملة أو العرف التجارى أو غير ذلك من الظروف تدل على أن الموجب لم يكن لينتظر تصريحا بالقبول ، فإن العقد يعتبر قد تم ، إذا لم يرفض الإيجاب فى وقت مناسب. ( 2 ) ويعتبر السكوت عن الرد قبولا ، إذا كان هناك تعامل سابق بين المتعاقدين واتصل الإيجاب بهذا التعامل ، أو إذا تمحض الإيجاب لمنفعة من وجه إليه."}, {"number": "99", "chapter": "الفصل الأول", "text": "لا يتم العقد فى المزايدات الا برسو المزاد ، ويسقط العطاء بعطاء يزيد عليه ولو كان باطلا."}, {"number": "100", "chapter": "الفصل الأول", "text": "القبول فى عقود الإذعان يقتصر على مجرد التسليم بشروط مقررة يضعها الموجب ولا يقبل مناقشة فيها."}, {"number": "101", "chapter": "الفصل الأول", "text": "( 1 ) الاتفاق الذى يعد بموجبه كلا المتعاقدين أو أحدهما بإبرام عقد معين فى المستقبل لا ينعقد الا إذا عينت جميع المسائل الجوهرية للعقد المراد إبرامه ، والمدة التى يجب إبرامه فيها. ( 2 ) وإذا اشترط قانون لتمام العقد استيفاء شكل معين ، فهذا الشكل تجب مراعاته أيضا فى الاتفاق الدعوى يتضمن الوعد بإبرام هذا العقد."}, {"number": "102", "chapter": "الفصل الأول", "text": "إذا وعد شخص بإبرام عقد ثم فكل وقاضاه المتعاقد الآخر طالبا تنفيذ الوعد ، وكانت الشروط اللازمة لتمام العقد وبخاصة ما يتعلق منها بالشكل متوافرة ، قام الحكم متى حاز قوة الشئ المقضى به مقام العقد."}, {"number": "103", "chapter": "الفصل الأول", "text": "( 1 ) دفع العربون وقت إبرام العقد يفيد أن لكل من المتعاقدين الحق فى العدول عنه. الا إذا قضى الاتفاق بغير ذلك. ( 2 ) فإذا عدل من دفع العربون ، فقده. وإذا عدل من قبضه ، رد ضعفه. هذا ولو لم يترتب على العدول أى ضرر."}, {"number": "104", "chapter": "الفصل الأول", "text": "( 1 ) إذا تم العقد بطريق النيابة كان شخص النائب لا شخص الأصيل هو محل الإعتبار عند النظر فى عيوب الإرادة أو فى أثر العلم ببعض الظروف الخاصة ، أو افتراض العلم بها حتما. ( 2 ) ومع ذلك إذا كان النائب وكيلا ويتصرف وفقا لتعليمات معينة صدرت له من موكله ، فليس للموكل أن يتمسك بجهل النائب لظروف كان يعلمها هو ، أو كان من المفروض حتما أن يعلمها."}, {"number": "105", "chapter": "الفصل الأول", "text": "إذا ابرم النائب فى حدود نيابته عقدا باسم الأصيل فإن ما ينشأ عن هذا العقد من حقوق وإلتزامات يضاف إلى الأصيل."}, {"number": "106", "chapter": "الفصل الأول", "text": "إذا لم يعلن العاقد وقت إبرام العقد انه يتعاقد بصفته نائبا ، فإن أثر العقد لا يضاف إلى الأصيل دائنا أو مدينا ، الا إذا كان من المفروض حتما أن من تعاقد معه النائب يعلم بوجود النيابة ، أو كان يستوى عنده أن يتعامل مع الأصيل أو النائب."}, {"number": "107", "chapter": "الفصل الأول", "text": "إذا كان النائب ومن تعاقد معه يجهلان معا وقت العقد انقضاء النيابة ، فإن أثر العقد الذى يبرمه ، حقا كان أو إلتزاما ، يضاف إلى الأصيل أو خلفائه."}, {"number": "108", "chapter": "الفصل الأول", "text": "لا يجوز لشخص أن يتعاقد مع نفسه باسم من ينوب عنه ، سواء أكان التعاقد لحسابه هو أم لحساب شخص آخر دون ترخيص من الأصيل. على انه يجوز للأصيل فى هذه الحالة أن يجيز التعاقد. كل هذا مع مراعاة ما يخالفه ، مما يقضى به القانون أو قواعد التجارة."}, {"number": "109", "chapter": "الفصل الأول", "text": "كل شخص أهل للتعاقد ما لم تسلب أهليته أو يحد منها بحكم القانون."}, {"number": "110", "chapter": "الفصل الأول", "text": "ليس للصغير غير المميز حق التصرف فى ماله ، وتكون جميع تصرفاته باطلة."}, {"number": "111", "chapter": "الفصل الأول", "text": "( 1 ) إذا كان الصبى مميزا كانت تصرفاته المالية صحيحة متى كانت نافعة نفعا محضا ، وباطلة متى كانت ضارة ضررا محضا. ( 2 ) اما التصرفات المالية الدائرة بين النفع والضرر ، فتكون قابلة للإبطال لمصلحة القاصر ، ويزول حق التمسك بالإبطال إذا أجاز القاصر التصرف بعد بلوغه سن الرشد ، أو إذا صدرت الاجازة من وليه أو من المحكمة بحسب الأحوال وفقا للقانون."}, {"number": "112", "chapter": "الفصل الأول", "text": "إذا بلغ الصبى المميز الثامنة عشرة من عمره واذن له فى تسلم أمواله لإدارتها ، أو تسلمها بحكم القانون ، كانت أعمال الادارة الصادرة منه صحيحة فى الحدود التى رسمها القانون."}, {"number": "113", "chapter": "الفصل الأول", "text": "المجنون والمعتوه وذو الغفلة والسفيه تحجر عليهم المحكمة ، وترفع الحجر عنهم. وفقا للقواعد والإجراءات المقررة فى القانون."}, {"number": "114", "chapter": "الفصل الأول", "text": "( 1 ) يقع باطلا تصرف المجنون والمعتوه إذا صدر التصرف بعد تسجيل قرار الحجر. ( 2 ) اما إذا صدر التصرف قبل تسجيل قرار الحجر فلا يكون باطلا الا إذا كانت حالة الجنون أو العته شائعة وقت التعاقد. أو كان الطرف الآخر على بينة منها."}, {"number": "115", "chapter": "الفصل الأول", "text": "( 1 ) إذا صدر تصرف من ذى الغفلة أو من السفيه بعد تسجيل قرار الحجر. سرى على هذا التصرف ما يسرى على تصرفات الصبى المميز من أحكام. ( 2 ) اما التصرف الصادر قبل تسجيل قرار الحجر فلا يكون باطلا أو قابلا للإبطال ، الا إذا كان نتيجة استغلال أو تواطؤ."}, {"number": "116", "chapter": "الفصل الأول", "text": "( 1 ) يكون تصرف المحجور عليه لسفه أو غفلة بالوقف أو بالوصية صحيحا ، متى أذنته المحكمة فى ذلك. ( 2 ) وتكون أعمال الإدارة الصادرة من المحجور عليه لسفه المأذون له لتسلم أمواله ، صحيحة فى الحدود التى رسمها القانون."}, {"number": "117", "chapter": "الفصل الأول", "text": "( 1 ) إذا كان الشخص أصم ابكم أو اعمى أصم أو اعمى ابكم ، وتعذر عليه بسبب ذلك التعبير عن إرادته ، جاز للمحكمة أن تعين له مساعدا قضائيا يعاونه فى التصرفات التى تقتضى مصلحته فيها ذلك. ( 2 ) ويكون قابلا للإبطال كل تصرف من التصرفات التى تقررت المساعدة القضائية فيها ، متى صدر من الشخص الدعوى تقررت مساعدته قضائيا بغير معاونة المساعد ، إذا صدر التصرف بعد تسجيل قرار المساعدة."}, {"number": "118", "chapter": "الفصل الأول", "text": "التصرفات الصادرة من الأولياء والأوصياء والقوام ، تكون صحيحة فى الحدود التى رسمها القانون."}, {"number": "119", "chapter": "الفصل الأول", "text": "يجوز لناقص الأهلية أن يطلب إبطال العقد ، وهذا مع عدم الإخلال بإلزامه بالتعويض ، إذا لجأ إلى طرق إحتياليه ليخفى نقص أهليته."}, {"number": "120", "chapter": "الفصل الأول", "text": "إذا وقع المتعاقد فى غلط جوهرى جاز له أن يطلب إبطال العقد ، أن كان المتعاقد الآخر قد وقع مثله فى هذا الغلط ، أو كان على علم به ، أو كان من السهل عليه أن يتبينه."}, {"number": "121", "chapter": "الفصل الأول", "text": "( 1 ) يكون الغلط جوهريا إذا بلغ حدا من الجسامة بحيث يمتنع معه المتعاقد عن إبرام العقد لو لم يقع فى هذا الغلط. ( 2 ) ويعتبر الغلط جوهريا على الأخص : أ - إذا وقع فى صفة للشئ تكون جوهرية فى إعتبار المتعاقدين. أو يجب اعتبارها كذلك لما يلابس العقد من ظروف ولما ينبغى فى التعامل من حسن نية. ب - إذا وقع فى ذات المتعاقد أو فى صفة من صفاته ، وكانت تلك الذات أو هذه الصفة السبب الرئيس فى التعاقد."}, {"number": "122", "chapter": "الفصل الأول", "text": "يكون العقد قابلا للإبطال لغلط فى القانون ، إذا توافرت فيه شروط الغلط فى الواقع طبقا للمادتين السابقتين ، هذا ما لم يقض القانون بغيره."}, {"number": "123", "chapter": "الفصل الأول", "text": "لا يؤثر فى صحة العقد مجرد الغل فى الحساب. ولا غلطات القلم ، ولكن يجب تصحيح الغلط."}, {"number": "124", "chapter": "الفصل الأول", "text": "( 1 ) ليس لمن وقع فى غلط أن يتمسك به على وجه يتعارض مع ما يقضى به حسن النية. ( 2 ) ويبقى بالأخص ملزما بالعقد الذى قصد إبرامه ، إذا اظهر الطرف الآخر أستعداده لتنفيذ هنا العقد."}, {"number": "125", "chapter": "الفصل الأول", "text": "( 1 ) يجوز إبطال العقد للتدليس إذا كانت الحيل التى لجأ إليها أحد المتعاقدين ، أو نائب عنه ، من الجسامة ، بحيث لولاها لما ابرم الطرف الثانى العقد. ( 2 ) ويعتبر تدليسا السكوت عمدا عن واقعة أو ملابسة من إذا ثبت أن المدلس عليه ما كان ليبرم العقد لو علم بتلك الواقعة أو هذه الملابسة."}, {"number": "126", "chapter": "الفصل الأول", "text": "إذا صدر التدليس من غير المتعاقدين ، من فليس للمتعاقد المدلس عليه أن يطلب إبطال العقد ، ما لم يكبت أن المتعاقد الآخر كان يعلم أو كان من المفروض حتما أن يعلم لهذا التدليس."}, {"number": "127", "chapter": "الفصل الأول", "text": "( 1 ) يجوز إبطال العقد للإكراه إذا تعاقد شخص تحت سلطان رهبة بعثها المتعاقد الآخر فى نفسه دون حق. وكانت قائمة على أساس. ( 2 ) وتكون الرهبة قائمة على أساس إذا كانت ظروف الحال تصور للطرف الذى يدعيها أن خطرا جسيما محدقا يهدده هو أو غيره فى النفس أو الجسم أو الشرف أو المال. ( 3 ) ويراعى فى تقدير الأكراه جنس من وقع عليه هذا الإكراه وسنه وحالته الاجتماعية والصحية وكل ظرف آخر من شأنه أن يؤثر فى جسامة الإكراه."}, {"number": "128", "chapter": "الفصل الأول", "text": "إذا صدر الإكراه من غير المتعاقدين ، فليس للمتعاقد المكره أن يطلب إبطال العقد ، ما لم يثبت أن المتعاقد الآخر كان يعلم أو كان من المفروض حتما أن يعلم بهذا الإكراه."}, {"number": "129", "chapter": "الفصل الأول", "text": "( 1 ) إذا كانت إلتزامات أحد المتعاقدين لا تتعادل البتة مع ما حصل عليه هذا المتعاقد من فائدة بموجب العقد أو مع إلتزامات المتعاقد الآخر ، وتبين أن المتعاقد المغبون لم يبرم العقد الا لأن المتعاقد الآخر قد استغل فيه طيشا بينة أو هوى جامحا ، جاز للقاضى بناء على طلب المتعاقد المغبون أن يبطل العقد أو أن ينقص إلتزامات هذا المتعاقد. ( 2 ) ويجب أن ترفع الدعوى بذلك خلال سنة من تاريخ العقد ، والا كانت غير مقبولة. ( 3 ) ويجوز فى عقود المعاوضة أن يتوقى الطرف الآخر دعوى الإبطال ، إذا عرض ما يراه القاضى كافيا لرفع الغبن."}, {"number": "130", "chapter": "الفصل الأول", "text": "يراعى فى تطبيق المادة السابقة عدم الإخلال بالأحكام الخاصة بالغبن فى بعض العقود أو بسعر الفائدة. 2- المحل"}, {"number": "131", "chapter": "الفصل الأول", "text": "( 1 ) يجوز أن يكون محل الإلتزام شيئا مستقبلا. ( 2 ) غير أن التعامل فى تركة إنسان على قيد الحياة باطلا ، ولو كان برضاء ، الا فى الأحوال التى نص عليها فى القانون."}, {"number": "132", "chapter": "الفصل الأول", "text": "إذا كان محل الإلتزام مستحيلا فئ ذاته كان العقد باطلا."}, {"number": "133", "chapter": "الفصل الأول", "text": "( 1 ) إذا لم يكن محل الإلتزام معينا بذاته ، وجب أن يكون معينا بنوعه ومقداره والا كان العقد باطلا. ( 2 ) ويكفى أن يكون المحل معينا بنوعه فقط إذا تضمن العقد ما يستطاع به تعيين مقداره. وإذا لم يتفق المتعاقدان على درجة الشئ ، من حيث جودته ولم يمكن استخلاص ذلك من العرف أو من أى ظرف آخر ، التزم المدين بأن يسلم شيئا من صنف متوسط."}, {"number": "134", "chapter": "الفصل الأول", "text": "إذا كان محل الإلتزام نقودا ، التزم المدين بقدر عددها المذكور فى العقد دون أن يكون لارتفاع قيمة هذه النقود أو لانخفاضها وقت الوفاء أى أثر."}, {"number": "135", "chapter": "الفصل الأول", "text": "إذا كان محل الإلتزام مخالفا للنظام العام أو الآداب كان العقد باطلا. السبب :"}, {"number": "136", "chapter": "الفصل الأول", "text": "إذا لم يكن للإلتزام سبب ، أو كان سببه مخالفا للنظام العام أو الآداب ، كان العقد باطلا."}, {"number": "137", "chapter": "الفصل الأول", "text": "( 1 ) كل إلتزام لم يذكر له سبب فى العقد يفترض أن له سببا مشروعا. ما لا يقم الدليل على غير ذلك. ( 2 ) ويعتبر السبب المذكور فى العقد هو السبب الحقيقى حتى يقوم الدليل على ما يخالف ذلك ، فإذا قام الدليل على صورية السبب فعلى من يدعى أن للإلتزام سببا آخر مشروعا أن يثبت ما يدعيه. البطلان"}, {"number": "138", "chapter": "الفصل الأول", "text": "إذا جعل القانون لأحد المتعاقدين ، حقا فى إبطال العقد فليس للمتعاقد الآخر أن : يتمسك بهذا الحق."}, {"number": "139", "chapter": "الفصل الأول", "text": "( 1 ) يزول حق إبطال العقد بالإجازة الصريحة أو الضمنية. ( 2 ) وتستند الاجازة إلى التاريخ الذى تم فيه العقد ، دون إخلال بحقوق الغير."}, {"number": "140", "chapter": "الفصل الأول", "text": "( 1 ) يسقط الحق فى إبطال العقد إذا لم يتمسك به صاحبه خلال ثلاث سنوات. ( 2 ) ويبدأ سريان هذه المدة فى حالة نقص الأهلية. من اليوم الذى يزول فيه هذا السبب ، وفى حالة الغلط أو التدليس ، من اليوم الذى ينكشف فيه ، وفى حالة الإكراه من يوم انقطاعه ، وفى كل حال لا يجوز التمسك بحق الإبطال لغلط أو تدليس أو اكراه إذا انقضت خمس عشرة سنة من وقت تمام العقد."}, {"number": "141", "chapter": "الفصل الأول", "text": "( 1 ) إذا كان العقد باطلا جاز لكل ذى مصلحة أن يتمسك بالبطلان ، وللمحكمة أن تقضى به من تلقاء نفسها ، ولا يزول البطلان بالإجازة. ( 2 ) وتسقط دعوى البطلان بمضى خمس عشرة سنه من وقت العقد."}, {"number": "142", "chapter": "الفصل الأول", "text": "( 1 ) فى حالتى إبطال العقد وبطلانه يعاد المتعاقدان إلى الحالة التى كانا عليها قبل العقد. فإذا كان هذا مستحيلا جاز الحكم بتعويض معادل. ( 2 ) ومع ذلك لا يلزم ناقص الأهلية. إذا ابطل العقد لنقص أهليته. أن يرد غير ما عاد عليه من منفعة بسب تنفيذ العقد."}, {"number": "143", "chapter": "الفصل الأول", "text": "إذا كان العقد فى شق منه باطلا أو قابلا للإبطال فهذا الشق وحده هو الذى يبطل. الا إذا تبين أن العقد ما كان ليتم بغير الشق الذى وقع باطلا أو قابلا للإبطال فيبطل العقد كله."}, {"number": "144", "chapter": "الفصل الأول", "text": "إذا كان العقد باطلا أو قابلا للإبطال وتوافرت فيه أركان عقد آخر ، فإن العقد يكون صحيحا بإعتباره العقد الذى توافرت أركانه ، إذا تبين أن نية المتعاقدين كانت تنصرف إلى إبرام هذا العقد. 2 - آثار العقد"}, {"number": "145", "chapter": "الفصل الأول", "text": "ينصرف أثر العقد إلى المتعاقدين والخلف العام. دون إخلال بالقواعد المتعلقة بالميراث ، ما لم يتبين من العقد أو من طبيعة التعامل أو من نص القانون أن هذا الأثر لا ينصرف إلى الخلف العام."}, {"number": "14", "chapter": "الفصل الأول", "text": "6 إذا أنشأ العقد إلتزامات وحقوقا شخصية تتصل بشئ انتقل بعد ذلك إلى ، خلف خاص ، فإن هذه الإلتزامات والحقوق تنتقل إلى هذا الخلف فى الوقت الذى ينتقل فيه الشئ ، إذا كانت من مستلزماته وكان الخلف الخاص يعلم بها وقت انتقال الشئ إليه."}, {"number": "147", "chapter": "الفصل الأول", "text": "( 1 ) العقد شريعة المتعاقدين ، فلا يجوز نقضه ولا تعديله إلا باتفاق الطرفين ، أو للأسباب التى يقررها القانون. ( 2 ) ومع ذلك إذا طرأت حوادث استثنائية عامة لم يكن فى الوسع توقعها وترتب على حدوثها أن تنفيذ الإلتزام التعاقدى ، وان لم يصبح مستحيلا ، صار مرهقا للمدين بحيث يهدده بخسارة فادحة ، جاز للقاضى تبعا للظروف وسد الموازنة بين مصلحة الطرفين أن يرد الإلتزام المرهق إلى الحد المعقول. ويقع باطلا كل اتفاق على خلاف ذلك."}, {"number": "148", "chapter": "الفصل الأول", "text": "( 1 ) يجب تنفيذ العقد طبقا لما اشتمل عليه وبطريقة تتفق مع ما يوجبه حسن النية. ( 2 ) ولا يقتصر العقد على إلزام المتعاقد بما ورد فيه. ولكن يتناول أيضا ما هو من مستلزماته ، وفقا للقانون والعرف والعدالة بحسب طبيعة الإلتزام."}, {"number": "149", "chapter": "الفصل الأول", "text": "إذا تم العقد بطريق الإذعان وكان قد تضمن شروطا تعسفية جاز للقاضى أن يعدل هذه الشروط أو أن يعفى الطرف المذعن منها ، وذلك وفقا لما تقضى به العدالة. ويقع باطلا كل اتفاق على خلاف ذلك."}, {"number": "150", "chapter": "الفصل الأول", "text": "( 1 ) إذا كانت عبارة العقد واضحة ، فلا يجوز الانحراف عنها من طريق تفسيرها للتعرف على إرادة المتعاقدين. ( 2 ) اما إذا كان هناك محل لتفسير العقد ، فيجب البحث عن النية المشتركة للمتعاقدين دون الوقوف عند المعنى الحرفى للألفاظ ، مع الاستهداء فى ذلك بطبيعة التعامل ، وبما ينبغى أن يتوافر من أمانة وثقة بين المتعاقدين. وفقا للعرف الجارى فى المعاملات."}, {"number": "151", "chapter": "الفصل الأول", "text": "( 1 ) يفسر الشك فى مصلحة المدين. ( 2 ) ومع ذلك لا يجوز أن يكون تفسير العبارات الغامضة فى عقود الإذعان ضارا بمصلحة الطرف المذعن."}, {"number": "152", "chapter": "الفصل الأول", "text": "لا يرتب العقد التزاما فى ذمة الغير. ولكن يجوز أن يكسبه حقا."}, {"number": "153", "chapter": "الفصل الأول", "text": "( 1 ) إذا تعهد شخص بأن يجعل الغير يلتزم بأمر فلا يلزم الغير بتعهده ، فإذا رفض الغير أن يلتزم ، وجب على المتعهد أن يعوض من تعاقد معه ، ويجوز له مع ذلك أن يتخلص من التعويض بأن يقوم هو نفسه بتنفيذ الإلتزام الذى تعهد به. ( 2 ) اما إذا قبل الغير هذا التعهد ، فإن قبوله لا ينتج أثرا الا من وقت صدوره ، ما لم يتبين انه قصد صراحة أو ضمنا أن يستند أثر هذا القبول إلى الوقت الذى صدر فيه التعهد."}, {"number": "154", "chapter": "الفصل الأول", "text": "( 1 ) يجوز للشخص أن يتعاقد باسمه على التزامات يشترطها لمصلحة الغير ، إذا كان له فى تنفيذ هذه الإلتزامات مصلحة شخصية عادية كانت أو أدبية. ( 2 ) ويترتب على هذا الإشتراط أن يكسب الغير حقا مباشرا قبل المتعهد بتنفيذ الإشتراط يستطيع أن يطالبه بوفائه ، ما لم يتفق على خلاف ذلك. ولكون لهذا المتعهد أن يتمسك قبل المنتفع بالدفوع التى تنشأ عن العقد. ( 3 ) ويجوز كذلك للمشترط أن يطالب بتنفيذ ما اشترط لمصلحة المنتفع ، الا إذا تبين من العقد أن المنتفع وحده هو الذى يجوز له ذلك."}, {"number": "155", "chapter": "الفصل الأول", "text": "( 1 ) يجوز للمشترط دون دائنيه أو ورثته أن ينقض المشارطة قبل أن يعلن المنتفع إلى المتعهد أو إلى المشترط رغبته فى الاستفادة منها ، ما لم يكن ذلك مخالفا لما يقتضيه العقد. ( 2 ) ولا يترتب على نقض المشارطة أن تبرأ ذمة المتعهد قبل المشترط. الا إذا اتفق صراحة أو ضمنا على خلاف ذلك وللمشترط إحلال منتفع آخر محل المنتفع الأول ، كما له أن يستأثر لنفسه بالانتفاع من المشارطة."}, {"number": "156", "chapter": "الفصل الأول", "text": "يجوز فى الإشتراط لمصلحة الغير أن يكون المنتفع شخصا مستقبلا أو جهة مستقبلة ، كما يجوز أن يكون شخصا أو جهة لم يعينا وقت العقد ، متى كان تعيينهما مستطاعا فى وقت أن ينتج العقد أثره طبقا للمشارطة. 3 - انحلال العقد"}, {"number": "157", "chapter": "الفصل الأول", "text": "( 1 ) فى العقود الملزمة للجانبين ، إذا لم يوف أحد المتعاقدين بإلتزامه جاز للمتعاقد الآخر بعد اعذاره المدين أن يطالب بتنفيذ العقد أو بفسخه ، مع التعويض فى الهالتين أن كان له مقتض. ( 2 ) ويجوز للقاضى أن يمنح المدين اجلا إذا اقتضت الظروف ذلك ، كما يجوز له أن يرفض الفسخ إذا كان ما لم يرف به المدين قليل الأهمية بالنسبة إلى الإلتزام فى جملته."}, {"number": "158", "chapter": "الفصل الأول", "text": "يجوز الاتفاق على أن يعتبر العقد مفسوخا من تلقاء نفسه دون حاجة إلى حكم قضائى - عند عدم الوفاء بالإلتزامات الناشئة عنه ، وهذا الاتفاق لا يعفى من الاعذار ، الا إذا اتفق المتعاقدان صراحة على الإعفاء منه."}, {"number": "159", "chapter": "الفصل الأول", "text": "فى العقود الملزمة للجانبين إذا النقض إلتزام بسبب استحالة تنفيذه انقضت معه الإلتزامات المقابلة له وينفسخ العقد من تلقاء نفسه."}, {"number": "160", "chapter": "الفصل الأول", "text": "إذا فسخ العقد أعيد المتعاقدان إلى الحالة التى كانا عليها قبل العقد ، فاذا استحال ذلك جاز الحكم بالتعويض."}, {"number": "161", "chapter": "الفصل الأول", "text": "فى العقود الملزمة للجانبين إذا كانت الإلتزامات المتقابلة مستحقة الوفاء ، جاز لكل من المتعاقدين أن يمتنع عن تنفيذ إلتزامه إذا لم يقم المتعاقد الآخر بتنفيذ ما التزم به."}, {"number": "162", "chapter": "الفصل الثانى", "text": "( 1 ) من وجه للجمهور وعدا بجائزة يعطيها عن عمل معين التزم بإعطاء الجائزة لمن قام بهذا العمل ولو قام به دون نظر إلى الوعد بالجائزة أو دون علم بها. ( 2 ) وإذا لم يعين الواعد اجلا للقيام بالعمل جاز له الرجوع فى وعدم بإعلان للجمهور ، على الا يؤثر ذلك فى حق من أتم العمل قبل الرجوع فى الوعد. وتسقط دعوى المطالبة بالجائزة إذا لم ترفع خلال ستة اشهر من تاريخ إعلانه العدول للجمهور."}, {"number": "163", "chapter": "الفصل الثالث", "text": "كل خطأ سبب ضررا للغير يلزم من ارتكبه بالتعويض."}, {"number": "164", "chapter": "الفصل الثالث", "text": "( 1 ) يكون الشخص مسئولا عن أعماله غير المشروعة متى صدرت منه وهو مميز. ( 2 ) ومع ذلك إذا وقع الضرر من شخص غير مميز ولم يكن هناك من هو مسئول عنه ، أو تعذر الحصول على تعويض من المسئول ، جاز للقاضى أن يلزم من وقع منه الضرر بتعويض عادل ، مراعيا فى ذلك مركز الخصوم."}, {"number": "165", "chapter": "الفصل الثالث", "text": "إذا اثبت الشخص أن الضرر قد نشأ عن سبب أجنبى لا بد له فيه ، كحادث مفاجئ أو قوة قاهرة أو خطأ من المضرور أو خطأ من الغير ، كان غير ملزم بتعويض هذا الضرر ، ما لم يوجد نص أو اتفاق على غيرة ذلك."}, {"number": "166", "chapter": "الفصل الثالث", "text": "من احدث ضررا وهو فى حالة دفاع شرعى عن نفسه أو ماله أو عن نفس الغير أو ماله ، كان غير مسئول ، على الا يجاوز فى دفاعه القدر الضرورى. والا اصبح ملزما بتعريض تراعى فيه مقتضيات العدالة."}, {"number": "167", "chapter": "الفصل الثالث", "text": "لا يكون الموظف العام مسئولا عن عمله الذى أضر بالغير إذا قام به تنفيذا لأمر صدر إليه من رئيس ، متى كانت إطاعة هذا الأمر واجبة عليه ، أو كان يعتقد انها واجبة ، واثبت انه كان يعتقد مشروعية العمل الذى وقع منه ، وكان اعتقاده مبنيا على أسباب معقولة ، وانه راعى فى عمله جانب الحيطة."}, {"number": "168", "chapter": "الفصل الثالث", "text": "من سبب ضررا للغير ليتفادى ضررا اكبر محدقا به أو بغيره ، لا يكون ملزما الا بالتعويض الذى يراه القاضى مناسبا."}, {"number": "169", "chapter": "الفصل الثالث", "text": "إذا تعدد المسئولون عن عمل ضار كانوا متضامنين فى إلتزامهم بتعويض الضرر ، وتكون المسئولية فيما بينهم بالتساوى ، الا إذا عين القاضى نصيب كل منهم فى التعويض."}, {"number": "170", "chapter": "الفصل الثالث", "text": "يقدر القاضى مدى التعويض عن الضرر الذى لحق المضرور طبقا لأحكام المادتين 221 و 222 مراعيا فى ذلك الظروف الملابسة ، فإن لم يتيسر له وقت الحكم أن يعين مدى التعويض تعيينا نهائيا ، فله أن يحتفظ للمضرور بالحق فى أن يطالب خلال مدة معينة بإعادة النظر فى التقدير."}, {"number": "171", "chapter": "الفصل الثالث", "text": "( 1 ) يعين القاضى طريقة التعويض تبعا للظروف ويصح أن يكون التعويض مقسطا كما يصح أن يكون إيرادا مرتبا ، ويجوز فى هاتين الحالتين إلزام المدين بأن يقدم تأمينا. ( 2 ) ويقدر التعويض بالنقد على انه يجوز للقاضى ، تبعا للظروف وبناء على طلب المضرور ، أن يأمر بإعادة الحالة إلى ما كانت عليه ، أو أن يحكم بأداء أمرمعين متصل بالعمل غير المشروع ، وذلك على سبيل التعويض."}, {"number": "172", "chapter": "الفصل الثالث", "text": "( 1 ) تسقط بالتقادم دعوى التعويض الناشئة عن العمل غير المشروع بانقضاء ثلاث سنوات من اليوم الذى علم فيه المضرور بحدوث الفعل وبالشخص المسئول عنه. وتسقط هذه الدعوى فى كل حال ، بإنقضاء خمس عشرة سنة من يوم وقوع العمل غير المشروع. ( 2 ) على انه إذا كانت هذه الدعوى ناشئة عن جريمة ، وكانت الدعوى الجنائية لم تسقط بعد انقضاء المواعيد المذكورة فى الفقرة السابقة ، فإن دعوى التعويض لا تسقط الا بسقوط الدعوى الجنائية. 2 - المسئولية عن عمل الغير"}, {"number": "173", "chapter": "الفصل الثالث", "text": "( 1 ) كل من يجب عليه قانونا أو اتفاقا رقابة شخص فى حاجة إلى الرقابة ، بسبب قصره أو بسبب حالته العقلية أو الجسمية يكون ملزما بتعويض الضرر الدعوى يحدثه ذلك الشخص للغير بعمله غير المشروع. ويترتب هذا الإلتزام ولو كان من وقع منه العمل الضار غير مميز. ( 2 ) ويعتبر القاصر فى حاجة إلى الرقابة إذا لم يبلغ خمس عشرة سنة ، أو بلغها وكان فى كنف القائم على تربيته وتنتقل الرقابة على القاصر إلى معلمه فى المدرسة أو المشرف على الحرفة مادام القاصر تحت اشراف المعلم أو المشرف. وتنتقل الرقابة على الزوجة القاصر إلى زوجها أو إلى من يتولى الرقابة على الزوج. ( 3 ) وتستطيع المكلف بالرقابة أن يخلص من المسئولية إذا اثبت انه قام بواجب الرقابة ، أو اثبت أن الضرر كان لابد واقعا ولو قام بهذا الواجب بما ينبغى من العناية."}, {"number": "174", "chapter": "الفصل الثالث", "text": "( 1 ) يكون المتبوع مسئولا عن الضرر الذى يحدثه تابعه بعمله غير المشروع ، متى كان واقعا منه فى حال تأدية وظيفته أو بسببها. ( 2 ) وتقوم رابطة التبعية ، ولو لم يكن المتبوع حرا فى اختيار تابعه ، متى كانت له عليه سلطة فعليه فى رقابته وفى توجيهه."}, {"number": "175", "chapter": "الفصل الثالث", "text": "للمسئول عن عمل الغير حق الرجوع عليه فى الحدود التى يكون فيها هذا الغير مسئولا عن تعويض الضرر. 3 - المسئولية الناشئة عن الأشياء"}, {"number": "176", "chapter": "الفصل الثالث", "text": "حارس الحيوان ، ولو لم يكن مالكا له ، مسئول عما يحدثه الحيوان من ضرر ، ولو ضل الحيوان أو تسرب ، ما لم يثبت الحارس أن وقوع الحادث كان بسبب أجنبى لا يد له فيه."}, {"number": "177", "chapter": "الفصل الثالث", "text": "( 1 ) حارس البناء ، ولو لم يكن مالكا له ، مسئول عما يحدث انهدام البناء من ضرر ، ولو كان انهداما جزئيا ، ما لم يثبت أن الحادث لا يرجع سببه إلى إهمال فى الصيانة أو قدم فى البناء أو عيب فيه. ( 2 ) ويجوز لمن كان مهددا بضرر يصيبه من البناء أن يطالب المالك بأتخاذ ما يلزم من التدابير الضرورية لدرء الخطر فإن لم يقم المالك بذلك جاز الحصول على اذن من المحكمة فى أتخاذ هذه التدابير على حسابه."}, {"number": "178", "chapter": "الفصل الثالث", "text": "كل من تولى حراسة أشياء تتطلب حراستها عناية خاصة أو حراسة آلات ميكانيكية يكون مسئولا عما تحدثه هذه الأشياء من ضرر ، ما لم يثبت أن وقوع الضرر كان بسبب أجنبى لا يد له فيه ، هذا مع عدم الإخلال بما يرد فى ذلك من أحكام خاصة."}, {"number": "179", "chapter": "الفصل الرابع.", "text": "كل شخص ، ولو غير مميز ، يثرى دون سبب مشروع على حساب شخص آخر يلتزم فى حدود ما أثرى به بتعويض هذا الشخص عما لحقه من خسارة ، ويبقى هذا الإلتزام قائما ولو زال الأثراء فيما بعد."}, {"number": "180", "chapter": "الفصل الرابع.", "text": "تسقط دعوى التعويض عن الإثراء بلا سبب بانقضاء ثلاث سنوات من اليوم الذى يعلم فيه من لحقته الخسارة بحقه فى التعويض ، وتسقط الدعوى ، كذلك فى جميع الأحوال بانقضاء خمس عشرة سنة من اليوم الذى ينشأ فيه هذا الحق. 1 - دفع غير المستحق"}, {"number": "181", "chapter": "الفصل الرابع.", "text": "( 1 ) كل من تسلم على سبيل الوفاء ما ليس مستحقا له وجب عليه رده ( 2 ) على انه لا محل للرد إذا كان من قام بالوفاء كعلم انه غير ملزم بما دفعه ، الا أن يكون ناقص الأهلية ، أو يكون قد اكره على هذا الوفاء."}, {"number": "182", "chapter": "الفصل الرابع.", "text": "يصح استرداد غير المستحق إذا كان الوفاء قد تم تنفيذا لإلتزام لم يتحقق سببه أو لإلتزام زال سببه بعد أن تحقق."}, {"number": "183", "chapter": "الفصل الرابع.", "text": "( 1 ) يصح كذلك استرداد غير المستحق ، إذا كان الوفاء قد تم تنفينا لإلتزام لم يحل اجله وكان الموفى جاهلا قيام الأجل. ( 2 ) على انه يجوز للدائن أن يقتصر على رد ما استفاده بسبب الوفاء المعجل فى حدود ما لحق المدين من ضرر. فإذا كان الإلتزام الذى لم يحل اجله نقودا ، التزم الدائن أن يرد للمدين فائدتها بسعرها القانونى أو الاتفاقى عن المدة الباقية لحلول الأجل."}, {"number": "184", "chapter": "الفصل الرابع.", "text": "لا محل لاسترداد غير المستحق إذا حصل الوفاء من غير المدين وترتب عليه أن الدائن ، وهو حسن النية ، قد تجرد من سند الدين ، أو مما حصل عليه من التأمينات أو ترك دعواه قبل المدين الحقيقى تسقط بالتقادم. ويلتزم المدين الحقيقى فى هذه الحالة بتعويض الغير الذى قام بالوفاء."}, {"number": "185", "chapter": "الفصل الرابع.", "text": "( 1 ) إذا كان من تسلم غير المستحق حسن النية خلا يلتزم أن يرد الا ما تسلم. ( 2 ) اما إذا كان سيئ النية فانه يلتزم أن يرد أيضا الفوائد والأرباح التى جناها ، أو التى قصر فى جنيها من الشئ الذى تسلمه بغير حق ، وذلك من يوم الوفاء أو من اليوم الذى اصبح فيه سيئ النية. ( 3 ) وعلى أى حال يلتزم من تسلم غير المستحق برد الفوائد والثمرات من يرم رفع الدعوى."}, {"number": "186", "chapter": "الفصل الرابع.", "text": "إذا لم تتوافر أهلية التعاقد فيمن تسلم غير المستحق فلا يكون ملتزما الا بالقدر الذى أثرى به."}, {"number": "187", "chapter": "الفصل الرابع.", "text": "تسقط دعوى استرداد ما دفع بغير حق بانقضاء ثلاث سنوات من اليوم الدعوى يعلم فيه من دفع غير المستحق بحقه فى الاسترداد ، وتسقط الدعوى كذلك فى جميع الأحوال بانقضاء خمس عشرة سنة من اليوم الذى ينشأ فيه هذا الحق. 2 - الفضالة"}, {"number": "188", "chapter": "الفصل الرابع.", "text": "الفضالة هى أن يتولى شخص عن قصد القيام بشأن عاجل لحساب شخص آخر ، دون أن يكون ملزما بذلك."}, {"number": "189", "chapter": "الفصل الرابع.", "text": "تتحقق الفضالة ولو كان الفضولى. فى اثناء توليه شانا لنفسه ، قد تولى شأن غيره ، لما بين الشأنين من ارتباط لا يمكن معه القيام بأحدهما منفصلا عن الآخر."}, {"number": "190", "chapter": "الفصل الرابع.", "text": "تسرى قواعد الوكالة إذا أقر رب العمل ما قام به الفضولى."}, {"number": "191", "chapter": "الفصل الرابع.", "text": "يجب على الفضولى أن يمضى فى العمل الذى بدأه إلى أن يتمكن رب العمل من مباشرته بنفسه ، كما يجب عليه أن يخطر بتدخله رب العمل متى استطاع ذلك."}, {"number": "192", "chapter": "الفصل الرابع.", "text": "( 1 ) يجب على الفضولى أن يبذل فى القيام بالعمل عناية الشخص العادى ، ويكون مسئولا عن خطئه. ومع ذلك يجوز للقاضى أن ينقص التعويض المترتب على هذا الخطأ ، إذا كانت الظروف تبرر ذلك. ( 2 ) وإذا عهد الفضولى إلى غيره بكل العمل أو ببعضه كان مسئولا عن تصرفات نائبه ، دون إخلال بما لرب العمل من الرجوع مباشرة على هذا النائب. ( 3 ) وإذا تعدد الفضوليون فى القيام بعمل واحد ، كانوا متضامنين فى المسئولية."}, {"number": "193", "chapter": "الفصل الرابع.", "text": "يلتزم الفضولى بما يلتزم به الوكيل من رد ما استولى عليه بسبب الفضالة ، وتقديم حساب عما قام به."}, {"number": "194", "chapter": "الفصل الرابع.", "text": "( 1 ) إذا مات الفضولى التزم ورثته بما يلتزم به ورثة الوكيل طبقا لأحكام المادة 717 فقرة 2. ( 2 ) وإذا مات رب العمل بقى الفضولى ملتزما نحو الورثة بما كان ملتزما به نحو مورثهم."}, {"number": "195", "chapter": "الفصل الرابع.", "text": "يعتبر الفضولى نائبا عن رب العمل ، متى كان قد بذل فى إدارته عناية الشخص العادى ، ولو لم تتحقق النتيجة المرجوة. وفى هذه الحالة يكون رب العمل ملزما بأن ينفذ التعهدات التى عقدها الفضولى لحسابه ، وان يعوضه عن التعهدات التى التزم بها ، وان يرد له النفقات الضرورية والنافعة التى سوغتها الظروف مضافا إليها فوائدها من يوم دفعها ، وان يعوضه عن الضرر الذى لحقه بسبب قيامه بالعمل ، ولا يستحق الفضولى أجرا على عمله الا أن يكون من أعمال مهنته."}, {"number": "196", "chapter": "الفصل الرابع.", "text": "( 1 ) إذا لم تتوافر فى الفضولى أهلية التعاقد فلا يكون مسئولا عن إدارته الا بالقدر الذى أثرى به ، ما لم تكن مسئوليته ناشئة عن عمل غير مشروع. ( 2 ) اما رب العمل فتبقى مسئوليته كاملة ، ولو لم تتوافر فيه أهلية التعاقد."}, {"number": "197", "chapter": "الفصل الرابع.", "text": "تسقط الدعوى الناشئة عن الفضالة بانقضاء ثلاث سنوات من اليوم الذى يعلم فيه كل طرف بحقه. وتسقط كذلك فى جميع الأحوال بانقضاء خمس عشرة سنة من اليوم الذى ينشأ فيه هذا الحق."}, {"number": "198", "chapter": "الفصل الخامس", "text": "الإلتزامات التى تنشأ مباشرة عن القانون وحده تسرى عليها النصوص القانونية التى أنشأتها."}, {"number": "199", "chapter": "الباب الثانى", "text": "( 1 ) ينفذ الإلتزام جبرا على المدين. ( 2 ) ومع ذلك إذا كان الإلتزام طبيعيا فلا جبر فى تنفيذه."}, {"number": "200", "chapter": "الباب الثانى", "text": "يقدر القاضى ، عند عدم النص ، ما إذا كان هناك إلتزام طبيعى. وفى كل حال لا يجوز أن يقوم إلتزام طبيعى يخالف النظام العام."}, {"number": "201", "chapter": "الباب الثانى", "text": "لا يسترد المدين ما أداه باختياره. قاصدا أن يوفى إلتزاما طبيعيا."}, {"number": "202", "chapter": "الباب الثانى", "text": "الإلتزام الطبيعى يصلح سببا لإلتزام مدنى."}, {"number": "203", "chapter": "الفصل الأول", "text": "( 1 ) يجبر المدين بعد اعذاره طبقا للمادتين 219 ، 220 على تنفيذ إلتزامه تنفيذا عينيا ، متى كان ذلك ممكنا. ( 2 ) على انه إذا كان فى التنفيذ العينى إرهاق للمدين جاز له أن يقتصر على دفع تعويض نقدى ، إذا كان ذلك لا يلحق بالدائن ضررا جسيما."}, {"number": "204", "chapter": "الفصل الأول", "text": "الإلتزام بنقل الملكية أو أى حق عينى آخر ينقل من تلقاء نفسه هذا الحق. إذا كان محل الإلتزام شيئا معينا بالذات يملكه الملتزم ، وذلك دون إخلال بالقواعد المتعلقة بالتسجيل."}, {"number": "205", "chapter": "الفصل الأول", "text": "( 1 ) إذا ورد الإلتزام بنقل حق عينى على شئ لم يعين الا بنوعه فلا ينتقل الحق الا بإفراز هذا الشئ. ( 2 ) فإذا لم يقم المدين بتنفيذ إلتزامه ، جاز للدائن أن يحصل على شئ من النوع ذاته على نفقة المدين بعد استئذان القاضى أو دون استئذانه فى حالة الاستعجال ، كما يجوز له أن يطالب بقيمة الشئ من غير إخلال فى الحالتين بحقه فى التعويض."}, {"number": "206", "chapter": "الفصل الأول", "text": "الإلتزام بنقل حق عينى يتضمن الإلتزام بتسليم الشئ والمحافظة عليه حتى التسليم."}, {"number": "207", "chapter": "الفصل الأول", "text": "( 1 ) إذا التزم المدين أن ينقل حقا عينيا أو أن يقوم بعمل ، وتضمن إلتزامه أن يسلم شيئا ولم يقم بتسليمه بعد أن اعذر ، فإن هلاك الشئ يكون عليه ولو كان الهلاك قبل الاعذار على الدائن. ( 2 ) ومع ذلك لا يكون الهلاك على المدين ، ولو اعذر إذا اثبت أن الشئ كان يملك كذلك عند الدائن لو انه سلم إليه ، ما لم يكن المدين قد قبل أن يتحمل تبعة الحوادث المفاجئة. ( 3 ) على أن الشئ المسروق إذا هلك أو ضاع بأية صورة كانت فإن تبعة الهلاك تقع على السارق."}, {"number": "208", "chapter": "الفصل الأول", "text": "فى الإلتزام بعمل ، إذا نص الاتفاق أو استوجبت طبيعة الدين أن ينفذ المدين الإلتزام بنفسه جاز للدائن أن يرفض الوفاء من غير المدين."}, {"number": "209", "chapter": "الفصل الأول", "text": "( 1 ) فى الإلتزام بعمل ، إذا لم يقم المدين بتنفيذ إلتزامه جاز للدائن أن يطلب ترخيصا من القضاء فى تنفيذ الإلتزام على نفقة المدين إذا كان هذا التنفيذ ممكنا. ( 2 ) ويجوز فى حالة الاستعجال أن ينفذ الدائن الإلتزام على نفقة المدين ، دون ترخيص من القضاء."}, {"number": "210", "chapter": "الفصل الأول", "text": "فى الإلتزام بعمل يقوم حكم القاضى مقام التنفيذ ، إذا سمحت بهذا طبيعة الإلتزام."}, {"number": "211", "chapter": "الفصل الأول", "text": "( 1 ) فى الإلتزام بعمل ، إذا كان المطلوب من المدين هو أن يحافظ على الشئ أو أن يقوم بإدارته أو أن يتوخى الحيطة فى تنفيذ إلتزامه فإن المدين يكون قد وفى بالالتزام إذا بذل فى تنفيذه من العناية كل ما يبذله الشخص العادى ، ولو لم يتحقق الغرض المقصود ، هذا ما لم ينص القانون أو الاتفاق على غير ذلك. ( 2 ) وفى كل حال يبقى المدين مسئولا عما يأتيه من غش أو خطأ جسيم."}, {"number": "212", "chapter": "الفصل الأول", "text": "إذا التزم المدين بالامتناع عن عمل وأخل بهذا الإلتزام ، جاز للدائن أن يطلب إزالة ما وقع مخالفا للإلتزام. وله أن يطلب من القضاء ترخيصا فى أن يقوم بهذه الازالة على نفقة المدين."}, {"number": "213", "chapter": "الفصل الأول", "text": "( 1 ) إذا كان تنفيذ الإلتزام عينا غير ممكن أو غير ملائم الا إذا قام به المدين نفسه ، جاز للدائن أن يحصل على حكم بإلزام المدين بهذا التنفيذ وبدفع غرامة تهديدية أن امتنع عن ذلك. ( 2 ) وإذا رأى القاضى أن مقدار الغرامة ليس كافيا لإكراه المدين الممتنع عن التنفيذ جاز له أن يزيد فى الغرامة كلما رأى داعيا للزيادة."}, {"number": "214", "chapter": "الفصل الأول", "text": "إذا تم التنفيذ العينى أو أصر المدين على رفض التنفيذ حدد القاضى مقدار التعويض الذى يلزم به المدين مراعيا فى ذلك الضرر الذى أصاب الدائن والعنت الذى بدا من المدين."}, {"number": "215", "chapter": "الفصل الثانى", "text": "إذا استحال على المدين أن ينفذ الإلتزام عينا حكم عليه بالتعويض لعدم الوفاء بإلتزامه ، ما لم يثبت أن استحالة التنفيذ قد نشأت عن سبب أجنبى لا يد له فيه. ويكون الحكم كذلك إذا تأخر المدين فى تنفيذ إلتزامه."}, {"number": "216", "chapter": "الفصل الثانى", "text": "يجوز للقاضى أن ينقص مقدار التعويض أو ألا يحكم بتعويض ما إذا كان الدائن بخطئه قد اشترك فى احداث الضرر أو زاد فيه."}, {"number": "217", "chapter": "الفصل الثانى", "text": "( 1 ) يجوز الاتفاق على أن يتحمل المدين تبعة الحادث المفاجئ والقوة القاهرة. ( 2 ) وكذلك يجوز الاتفاق على إعفاء المدين من أية مسئولية تترتب على عدم تنفيذ إلتزامه التعاقدى الا ما ينشأ عن غشه أو عن خطئه الجسيم ، ومع ذلك يجوز للمدين أن يشترط عدم مسئوليته عن الغش أو الخطأ الجسيم الذى يقع من أشخاص يستخدمهم فى تنفيذ إلتزامه. ( 3 ) ويقع باطلا كل شرط يقضى بالإعفاء من المسئولية المترتبة على العمل غير المشروع."}, {"number": "218", "chapter": "الفصل الثانى", "text": "لا يستحق التعويض الا بعد أعذار المدين ، ما لم ينص على غير ذلك."}, {"number": "219", "chapter": "الفصل الثانى", "text": "يكون أعذار المدين بإنذاره أو بما يقوم مقام الإنذار ، ويجوز أن يتم الاعذار عن طريق البريد على الوجه المبين فى قانون المرافعات ، كما يجوز أن يكون مترتبا على اتفاق يقضى بأن يكون المدين معذرا بمجرد حلول الأجل دون حاجة إلى أى أجراء آخر."}, {"number": "220", "chapter": "الفصل الثانى", "text": "لا ضرورة لاعذار المدين فى الحالات الآتية : ( أ ) إذا اصبح تنفيذ الإلتزام غير ممكن أو كير مجد بفعل المدين. ( ب ) إذا كان محل الإلتزام تعويضا ترتب على عمل غير مشروع. ( جـ ) إذا كان محل الإلتزام رد شئ يعلم المدين انه مسروق أو شئ تسلمه دون حق وهو عالم بذلك. ( د ) إذا صرح المدين كتابة انه لا يريد القيام بإلتزامه."}, {"number": "221", "chapter": "الفصل الثانى", "text": "1- اذا لم يكن التعويض مقدرا فى العقد أو بنص فى القانون، فالقاضى هو الذى يقدره، ويشمل التعويض ما لحق الدائن من خسارة وما فاته من كسب ، بشرط أن يكون هذا نتيجة طبيعية لعدم الوفاء بالالتزام أو للتأخر فى الوفاء به ، ويعتبر الضرر نتيجة طبيعية اذا لم يكن فى استطاعة الدائن أن يتوفاه ببذل جهد معقول. 2- ومع ذلك اذا كان الالتزام مصدره العقد ، فلا يلتزم المدين الذى لم يرتكب غشا أو خطأ جسيما الابتعويض الضرر الذى كان يمكن توقعه عادة وقت التعاقد."}, {"number": "222", "chapter": "الفصل الثانى", "text": "1- يشمل التعويض الضرر الأدبى أيضا، ولكن لايجوز فى هذه الحالة أن ينتقل الى الغير الا اذا تحدد بمقتضى اتفاق، أوطالب الدائن به أمام القضاء. 2- ومع ذلك لايجوزالحكم بتعويض الا للأزواج والأقارب الى الدرجة الثانية عما يصيبهم من ألم من جراء موت المصاب."}, {"number": "223", "chapter": "الفصل الثانى", "text": "------- 1- يجوز للمتعاقدين أن يحددا مقدما قيمة التعويض بالنص عليها فى العقد أ فى اتفاق لاحق، ويراعى فى هذه الحالة احكام المواد من 215, الى 220."}, {"number": "224", "chapter": "الفصل الثانى", "text": "1-لايكون التعويض الاتفاقى مستحقا اذا أثبت المدين ان الدائن لم يلحقه أى ضرر. 2- ويجوز للقاضى أن يخفض هذا التعويض اذا أثبت المدين أن التقدير كان مبالغا فيه الى درجة كبيرة، أوأن الالتزام الاصلى قد نفذ فى جزء منه. 3- ويقع باطلا كل اتفاق يخالف أحكام الفقرتين السابقتين."}, {"number": "225", "chapter": "الفصل الثانى", "text": "اذا جاوز الضررفيه التعويض الاتفاقى فلا يجوز للدائن ان يطالب بأكثر من هذه القيمة الا اذا اثبت أن المدين قد ارتكب غشا أو خطأ جسيما."}, {"number": "226", "chapter": "الفصل الثانى", "text": "اذا كان محل الالتزام مبلغا من النقود وكان معلوم المقدار وقت الطلب وتاخر المدين فى الوفاء به ، كان ملزما بأن يدفع للدائن على سيبل التعويض عن التاخر فوائد قدرها أربعة فى المائة فى المسائل المدنية وخمسة فى المائة فى المسائل التجارية. وتسرى هذه الفوائد من تاريخ المطالبة القضائية بها، ان لم يحدد الاتفاق أو العرف التجارى تاريخا آخر لسريانها ، وهذا كله ما لم ينص القانون على غيره."}, {"number": "227", "chapter": "الفصل الثانى", "text": "1- يجوز للمتعاقدين أن يتفقا على سعر آ’خر للفوائد سواء أكان ذلك فى مقابل تأخير الوفاء أم فى أية حالة أخرى تشترط فيها الفوائد ، على ألا يزيد هذا السعر على سبعة فى المائة، فاذا اتفقا على فوائد تزيد على هذا السعر وجب تخفيضها الى سبعة فى المائة وتعين رد ما دفع زائدا على هذا القدر. 2- وكل عمولة أو منفعة ،أيا كان نوعها، اشترطها الدائن اذا زادت هي والفائدة المتفق عليها على الحد الاقصى المتقدم ذكره تعتبر فائدة مستترة ، وتكون قابلة للتخفيض، اذا ما ثبت ان هذه العمولة أو المنفعة لاتقابلها خدمة حقيقة يكون الدائن قد أداها ولامنفعة مشروعة."}, {"number": "228", "chapter": "الفصل الثانى", "text": "لايشترط لاستحقاق فوائد التأخير قانونية كانت أو اتفاقية أن يثبت الدائن ضررا لحقه من هذا التأخير."}, {"number": "229", "chapter": "الفصل الثانى", "text": "------- اذا تسبب الدائن ، بسوء نية ، وهو يطالب بحقهن فى اطالة امد النزاع فللقاضى أن يخفض الفوائد قانونية كانت أو اتفاقية أو لا يقضى بها اطلاقا عن المدة التى طال فيها النزاع بلامبرر."}, {"number": "230", "chapter": "الفصل الثانى", "text": "عند توزيع ثمن الشئ الذى بيع جبرا لا يكون الدائنون المقبولون فى التوزيع مستحقين بعد رسو المزاد لفوائد تأخير عن الأنصبة التى تقررت لهم فى هذا التوزيع الا اذا كان الراسى عليه المزاد ملزما بدفع فوائد الثمن، أو كانت خزانة المحكمة ملزمة بهذه الفوائد بسبب ايداع الثمن فيها ، على الايتجاوز ما يتقاضاه الدائنون من فوائد فى هذه الحالة ما هو مستحق منها قبل الراسى عليه المزاد أو حزانة المحكمة . وهذه الفوائد تقسم بين الدائنين جميعا قسمة غرماء."}, {"number": "231", "chapter": "الفصل الثانى", "text": "------- يجوز للدائن أن يطالب بتعويض تكميلى يضاف الى الفوائد ، اذا أثبت أن الضرر الذى يجاوز الفوائد قد تسبب فيه المدين بسوء نية."}, {"number": "232", "chapter": "الفصل الثانى", "text": "لايجوز تقاضى فوائد على متجمد الفوائد ، ولايجوز فى أية حال أن يكون مجموع الفوائد التى يتقاضاها الدائن أكثر من رأس المال وذلك كله دون اخلال بالقواعد والعادات التجارية."}, {"number": "233", "chapter": "الفصل الثانى", "text": "الفوائد التجارية التى تسرى على الحساب الجارى يختلف سعرها القانونى بختلاف الجهات، ويتبع فى طريقة حساب الفوائد المركبة فى الحساب الجارى مايفضى به العرف التجارى"}, {"number": "234", "chapter": "الفصل الثالث", "text": "1- أموال المدين جميعها ضامنة للوفاء بديونه. 2- وجميع الدائنين متساوون فى هذا الضمان الا من كان له منهم حق التقدم طبقا للقانون. 1- وسائل التنفيذ"}, {"number": "235", "chapter": "الفصل الثالث", "text": "------- 1- لكل دائن ولو لم يكن حقه مستحق الأداء أن يستعمل باسم مدينه جميع حقوق هذا المدين ، الا ما كان منها متصلا بشخصه خاصة أو غير قابل للحجز. 2- ولايكون استعمال الدائن لحقوق مدينه مقبولا الا اذا أثبت أن المدين لم يستعمل هذه الحقوق وأن عدم استعماله لها من شأنه أن يسبب اعساره أو أن يزيد فى هذا الاعسار ، ولايشترط لهذا المدين لاستعمال حقه ولكن يجب ادخاله خصما فى الدعوى."}, {"number": "236", "chapter": "الفصل الثالث", "text": "يعتبر الدائن فى استعمال حقوق مدينه نائبا عن هذا المدين ، وكل فائدة تنتج من استعمال هذه الحقوق تدخل فى أموال المدين وتكون ضمانا لجميع دائنيه."}, {"number": "237", "chapter": "الفصل الثالث", "text": "لكل دائن أصبح حقه مستحق الأداء، وصدر من مدينة تصرف ضار به أن يطلب عدم نفاذ هذا التصرف فى حقه، اذا كان التصرف قد أنقص من حقوق المدين أو زاد فى التزاماته وترتب عليه اعسار المدين أو الزيادة فى اعساره ، وذلك متى توافرت الشروط المنصوص عليها فى المادة التالية."}, {"number": "238", "chapter": "الفصل الثالث", "text": "1- اذا كان تصرف المدين بعوض، اشترط لعدم نفاذه فى حق الدائن أن يكون منطويا على غش من المدين ، وأن يكون من صدر له التصرف على علم بهذا الغش، ويكفى لاعتبار التصرف منطويا على الغش أن يكون قد صدر من المدين وهو عالم أنه معسر، كما يعتبر من صدر له التصرف عالما بغش المدين اذا كان قد علم أن هذا المدين معسر. 2- أما اذا كان التصرف تبرعا، فانه لاينفذ فى حق الدائن ، ولو كان من صدر له التبرع حسن النية ولو ثبت أن المدين لم يرتكب غشا. 3- واذا كان الخلف الذى انتقل اليه الشئ من المدين قد تصرف فيه بعوض الى خلف آخر، فلا يصح للدائن أن يتمسك بعدم نفاذ التصرف الا اذا كان الخلف الثانى يعلم غش المدين ، وعلم الخلف الأول بهذا الغش ، ان كان المدين قد تصرف بعوض ، أو كان هذا الخلف الثانى يعلم اعسار المدين وقت تصرفه للخلف الأول ان كان المدين قد تصرف له تبرعا."}, {"number": "239", "chapter": "الفصل الثالث", "text": "------- اذا ادعى الدائن اعسار المدين فليس عليه الا أن يثبت مقدار ما فى ذمته من ديون ، وعلى المدين نفسه ان يثبت أن له مالا يساوى قيمة الديون أو يزيد عليها."}, {"number": "240", "chapter": "الفصل الثالث", "text": "متى تقرر عدم نفاذ التصرف استفاد من ذلك جميع الدائنين الذين صدر هذا التصرف اضرار بهم."}, {"number": "241", "chapter": "الفصل الثالث", "text": "------- اذا كان من تلقى حقا من المدين المعسرلم يدفع ثمنه، فانه يتخلص من الدعوى متى كان هذا الثمن هو المثل، وقام بايداعه خزانة المحكمة."}, {"number": "242", "chapter": "الفصل الثالث", "text": "1- اذا لم يقصد بالغش الا تفضيل دائن على آخر دون حق، فلا يترتب عليه الا حرمان الدائن من هذه الميزة. 2- واذا وفى المدين المعسر أحد دائنيه قبل انقضاء الأجل الذى عين أصلا للوفاء ، فلايسرى هذا الوفاء فى حق باقى الدائنين . وكذلك لايسرى فى حقهم الوفاء ولو حصل بعد انفضاء هذا الأجل، اذا كان قد تم نتيجة تواطؤ بين المدين والدائن الذى استوفى حقه."}, {"number": "243", "chapter": "الفصل الثالث", "text": "تسقط بالتقادم دعوى عدم نفاذ التصرف بانقضاء ثلاث سنوات من اليوم الذى يعلم فيه الدائن بسبب عدم نفاذا التصرف وتسقط فى جميع الأحوال بانقضاء خمس عشرة سنة من الوقت الذى صدر فيه التصرف المطعون فيه."}, {"number": "244", "chapter": "الفصل الثالث", "text": "1- اذا أبرم عقد صورى فلدائنى المتعاقدين وللخلف الخاص، متى كانوا حسنى النية، أن يتمسكوا بالعقد الصورى، كما أن لهم أن يتمسكوا بالعقد المستتر ويثبتوا بجميع الوسائل صورية العقد الذى أضربهم. 2- واذا تعارضت مصالح ذوى الشأن ، فتمسك بعضهم بالعقد الظاهر وتمسك الآخرون بالعقد المستتر، كانت الأفضلية للأولين."}, {"number": "245", "chapter": "الفصل الثالث", "text": "اذا ستر المتعاقدان عقدا حقيقيا بعقد ظاهر ، فالعقد النافذ فيما بين المتعاقدين والخلف العام هو العقد الحقيقى. إحدى وسائل الضمان 2-الحق فى الحبس"}, {"number": "246", "chapter": "الفصل الثالث", "text": "1- لكل من التزم بأداء شئ أن يمتنع عن الوفاء به ، ما دام الدائن لم يعرض الوفاء بالتزام مترتب عليه بسبب التزام المدين ومرتبط به ، أو ما دام الدائن لم يقم بتقديم تأمين كاف للوفاء بالتزامه هذا. 2- ويكون ذلك بوجه خاص لحائز الشئ أو محرزه ، اذا هو انفق عليه مصروفات ضرورية أو نافعة ، فان له أن يمتنع عن رد هذا الشئ حتى يستوفى ماهو مستحق له ، الا أن يكون الالتزام بالرد ناشئا عن عمل غير مشروع."}, {"number": "247", "chapter": "الفصل الثالث", "text": "1- مجرد الحق فى حبس الشئ لايثت حق امتياز عليه . 2- واذا كان الشئ المحبوس يخشى عليه الهلاك أو التلف , فللحابس أن يحصل على أذن من القضاء فى بيعه وفقا لاحكام المنصوص عليها فى المادة 1119، وينتقل الحق فى الحبس من شئ الى ثمنه."}, {"number": "248", "chapter": "الفصل الثالث", "text": "- 1- ينقضى الحق فى الحبس بخروج الشئ من يد حائزه أو محرزه. 2- ومع ذلك يجوز لحابس الشئ اذا خرج الشئ من يده خفية أو بالرغم من معارضته ، أن يطلب استرداده ، اذا هو قام بهذا الطلب خلال ثلاثين يوما من الوقت الذى علم فيه بخروج الشئ من يده ، وقبل القضاء سنة من وقت خروجه. 3- الإعسار"}, {"number": "249", "chapter": "الفصل الثالث", "text": "يجوز أن يشهر اعسار المدين اذا كانت أمواله لاتكفى لوفاء ديونه المستحقة الأداء."}, {"number": "250", "chapter": "الفصل الثالث", "text": "يكون شهر الاعسار بحكم تصدره المحكمة الابتدائية التى يتبعها موطن المدين ، بناء على طلب المدين نفسه أو طلب أحد دائنيه، وتنظر الدعوى على وجه السرعة."}, {"number": "251", "chapter": "الفصل الثالث", "text": "على المحكمة فى كل حال ، قبل أن تشهر اعسار المدين، أن تراعى فى تقديرها جميع الظروف التى أحاطت به، سواء أكانت هذه الظروف عامة أم خاصة . فتنظر الى موارده المستقبلة ومقدرته الشخصية ومسئوليته عن الأسباب التى أدت الى اعساره ، ومصالح دائنيه المشروعة، وكل ظرف آخر من شأنه أن يؤثر فى حالته المادية."}, {"number": "252", "chapter": "الفصل الثالث", "text": "------- مدة المعارضة فى الأحكام الصادرة فى شأن الاعسار ثمانية أيام ، ومدة استئنافها خمسة عشر يوما ، تبدأ من تاريخ اعلان تلك الأحكام."}, {"number": "253", "chapter": "الفصل الثالث", "text": "1- على كاتب المحكمة فى اليوم الذى تقيد فيه دعوى الاعسار أن يسجل صحيفتها فى سجل خاص يرتب بحسب أسماء المعسرين، وعليه أن يؤشر فى هامش التسجيل المذكور بالحكم الصادر فى الدعوى، وبكل حكم يصدر بتأييده أو بالغائه، وذلك كله يوم صدور الحكم، 2- وعلى الكاتب أيضا أن يرسل الى قلم كتاب محكمة مصر صورة من هذه التسجيلات والتأشيرات لاثباتها فى سجل عام ، ينظم وفقا لقرار يصدر من وزير العدل."}, {"number": "254", "chapter": "الفصل الثالث", "text": "يجب على المدين اذا تغير موطنه أن يخطر بذلك كاتب المحكمة التى يتبعها موطنه السابق، وعلى هذا الكاتب بمجرد علمه بتغيير الموطن، سواء أخطره المدين أم علم ذلك من أى طريق آخر، أن يرسل على نفقة المدين صورة من حكم شهر الاعسار ومن البيانات المؤشر بها فى هامش التسجيل الى المحكمة التى يتبعها الموطن الجديد لتقوم بقيدها فى سجلاتها."}, {"number": "255", "chapter": "الفصل الثالث", "text": "1- يترتب على الحكم بشهر الاعسار أن يحل كل ما فى ذمة المدين من ديون مؤجلة. ويخصم من هذه الديون مقدار الفائدة الاتفاقية أو القانونبة عن المدة التى سقطت بسقوط الأجل. 2- ومع ذلك يجوز للقاضى أن يحكم ، بناء على طلب المدين وفى مواجهة ذوى الشأن من دائنيه، بابقاء الاجل أو مده بالنسبة الى الديون المؤجلة كما يجوز أن يمنح المدين أجلا بالنسبة الى الديون الحالة، اذا رأى أن هذا الاجراء تبرره الظروف ، وأنه خير وسيلة تكفل مصالح المدين والدائنين جميعا."}, {"number": "256", "chapter": "الفصل الثالث", "text": "1- لايحول شهر الاعسار دون اتخاذ الدائنين لأجراءات فردية ضد المدين. 2- على أنه لايجوز أن يحتج على الدائنين الذين يكون لهم حقوق سابقة على تسجيل صحيفة دعوى الاعسار بأى اختصاص يقع على عقارات المدين بعد هذا التسجيل."}, {"number": "257", "chapter": "الفصل الثالث", "text": "متى سجلت صحيفة دعوى الاعسار فلا يسرى فى حق الدائنين أى تصرف للمدين يكو من شأنه أن ينقص من حقوقه أو يزيد فى التزاماته. كما لايسرى فى حقهم أى وفاء يقوم به المدين."}, {"number": "258", "chapter": "الفصل الثالث", "text": "1- يجوز للمدين أن يتصرف فى ماله ولو بغير رضاء الدائنين ، على أن يكون ذلك بثمن المثل ، وأن يقوم المشترى بايداع الثمن خزانة المحكمة حتى يوزع وفقا لاجراءات التوزيع. 2- فاذا كان الثمن الذى بيع به المال أقل من ثمن المثل ، كان التصرف غير سار فى حق الدائنين ، الا اذا أودع المشترى فوق الثمن الذى اشترى به مانقص من ثمن المثل."}, {"number": "259", "chapter": "الفصل الثالث", "text": "اذا أوقع الدائنون الحجز على ايرادات المدين، كان لرئيس المحكمة المختصة بشهر الاعسار أن يقرر للمدين ، بناء على عريضة يقدمها، نفقة يتقاضاها من ايراداته المحجوزة ، ويجوز التظلم من الأمر الذى يصدر على هذه العريضة ، فى مدة ثلاثة أيام من تاريخ صدوره ، ان كان التظلم من المدين ومن تاريخ اعلان الأمر للدائنين ان كان التظلم منهم."}, {"number": "260", "chapter": "الفصل الثالث", "text": "يعاقب المدين بعقوبة التبديد فى الحالتين الآتيتين : (أ) اذا رفعت عليه دعوى بدين فتعمد الاعسار ، بقصد الاضرار بدائنيه ، وانتهت الدعوى بصدور حكم عليه بالدين وشهر اعساره. (ب) ان كان بعد الحكم بشهر اعساره أخفى بعض أمواله ليحول دون التنفيذ عليها، أو اصطنع ديونا صورية أو مبالغا فيها، وذلك كله بقصد الاضرار بدائنيه."}, {"number": "261", "chapter": "الفصل الثالث", "text": "1- تنتهى حالة الاعسار بحكم تصدره المحكمة الابتدائية التى يتبعها موطن المدين، بناء عل طلب ذى شأن فى الحالتين الآتيتين: (أ) متى ثبت أن ديون المدين أصبحت لاتزيد على أمواله. (ب) متى قام المدين بوفاء ديونه التى حلت دون أن يكون لشهرالاعسار أثر فى حلولها، وفى هذه الحالة تعود آجال الديون التى حلت بشهر الاعسار الى ما ما كانت عليه من قبل وفقا للمادة 263. 2- ويؤشر كاتب المحكمة من تلقاء نفسه بالحكم الصادر بانتهاء حالة الاعسار يوم صدوره على هامش التسجيل المنصوص عليه فى المادة 253، وعليه أن يرسل صورة منه الى قلم كتاب محكمة مصر للتأشير به كذلك."}, {"number": "262", "chapter": "الفصل الثالث", "text": "تنتهى حالة الاعسار بقوة القانون متى انقضت خمس سنوات على تاريخ التأشير بالحكم الصادر بشهر الاعسار."}, {"number": "263", "chapter": "الفصل الثالث", "text": "يجوز للمدين بعد انتهاء حالة الاعسار أن يطلب اعادة الديون التى كانت قد حلت بسبب شهر الاعسار ولم يتم دفعها الى أجلها، السابق ، بشرط أن يكون قد وفى ديونه التى حلت دون أن يكون لشهر الاعسار أثر فى حلولها."}, {"number": "264", "chapter": "الفصل الثالث", "text": "انتهاء حالة الاعسار بحكم أو بقوة القانون لايمنع الدائنين من الطعن فى تصرفات المدين، ولا من التمسك باستعمال حقوقه وفقا للمواد من 235 الى 243."}, {"number": "265", "chapter": "الفصل الأول", "text": "يكون الالتزام معلقا على شرط اذا كان وجوده أو زواله مترتبا على أمر مستقبل غير محقق الوقوع."}, {"number": "266", "chapter": "الفصل الأول", "text": "1- لايكون الالتزام قائما اذا علق على شرط غير ممكن أو على شرط مخالف للآداب أو النظام العام، هذا اذا كانن الشرط وافقا، أما اذا كان فاسخا فهو نفسه الذى يعتبر غير قائم. 2- ومع ذلك لايقوم الالتزام الذى علق على شرط فاسخ مخالف للآداب أو النظام العام، اذا كان هذا الشرط هو السبب الدافع للالتزام."}, {"number": "267", "chapter": "الفصل الأول", "text": "لايكون الالتزام قائما اذا علق على شرط واقف يجعل وجود الالتزام متوقعا على محض ارادة الملتزم."}, {"number": "268", "chapter": "الفصل الأول", "text": "اذا كان الالتزام معلقا على شرط واقف ، فلا يكون نافذا الا اذا تحقق الشرط، أما قبل تحقق الشرط، فلا يكون الالتزام قابلا للتنفيذ القهرى ولا للتنفيذ الاختيارى، على أنه يجوز للدائن ان يتخذ من الاجراءات ما يحافظ به على حقه."}, {"number": "269", "chapter": "الفصل الأول", "text": "1- يترتب على تحقق الشرط الفاسخ زوال الالتزام ويكون الدائن ملزما برد ما أخذه، فاذا استحال الرد لسبب هو مسئول عنه وجب عليه التعويض. 2- على أن أعمال الادارة التى تصدر من الدائن تبقى نافذة رغم تحقق الشرط."}, {"number": "270", "chapter": "الفصل الأول", "text": "1- اذا تحقق الشرط أسند أثره الى الوقت الذى نشأ فيه الالتزام، الا اذا تبين من ارادة المتعاقدين أو من طبيعة العقد أن وجود الالتزام ، أو زواله ، انما يكون فى الوقت الذى تحقق فيه الشرط. 2- ومع ذلك لايكون للشرط أثر رجعى، اذا أصبح تنفيذ الالتزام قبل تحقق الشرط غير ممكن لسبب أجنبى لايد للمدين فيه. 2- الأجل"}, {"number": "271", "chapter": "الفصل الأول", "text": "1- يكون الالتزام لأجل اذا كان نفاذه أو انقضاؤه متربتا على أمر مستقبل محقق الوقوع."}, {"number": "272", "chapter": "الفصل الأول", "text": "اذا تبين من الالتزام أن المدين لايقوم بوفائه الا عند المقدرة أو الميسرة، عين القاضى ميعادا مناسبا لحلول الأجل، مراعيا فى ذلك موارد المدين الحالية والمستقبلة، ومقتضيا منه عناية الرجل الحريص على الوفاء بالتزامه."}, {"number": "273", "chapter": "الفصل الأول", "text": "1- اذا شهر افلاسه أو اعساره وفقا لنصوص القانون. 2- اذا أضعف بفعله الى حد كبير ما أعطى الدائن من تأمين خاص، ولو كان هذا التأمين قد أعطى بعقد لاحق أو بمقتضى القانون، هذا مالم يؤثر الدائن أن يطالب بتكملة التأمين ، أما اذا كان اضعاف التأمين يرجع الى سبب لادخل لارادة المدين فيه، فان الأجل يسقط مالم يقدم المدين للدائن ضمانا كافيا. 3- اذا لم يقدم للدائن ما وعد فى العقد بتقديمه من التأمينات."}, {"number": "274", "chapter": "الفصل الأول", "text": "1- اذا كان الالتزام مقترنا بأجل واقف، فانه لايكون نافذا الا فى الوقت الذى ينقضى فيه الأجل ، على أنه يجوز للدائن حتى قبل انقضاء الأجل أن يتخذ من الاجراءات مايحافظ به عل حقوقه ، وله بوجه خاص أن يطالب بتأمين اذا خشى افلاس المدين أو اعساره واستند فى ذلك الى سبب معقول. 2- ويترتب على انقضاء الأجل الفاسخ زوال الالتزام ، دون أن يكون لهذا الزوال أثر رجعى."}, {"number": "275", "chapter": "الفصل الثانى", "text": "ويكون الالتزام تخييريا اذا شمل محله أشياء متعددة تبرأ ذمة المدين براءة تامة اذا أدى واحد منها ، ويكون الخيار للمدين مالم ينص القانون أو يتفق المتعاقدان على غير ذلك ."}, {"number": "276", "chapter": "الفصل الثانى", "text": "1- اذا كان الخيار للمدين وامتنع عن الاختيار. أو تعدد المدينون ولم يتفقوا فيما بينهم ، جاز للدائن أن يطلب من القاضى تعيين أجل يختار فيه المدين أو يتفق فيه المدينون، فاذا لم يتم ذلك تولى القاضى بنفسه تعيين محل الالتزام. 2- أما اذا كان الخيار أو تعدد الدائنون ولم يتفقوا فيما بينهم ، عين القاضى أجلا ان طلب المدين ذلك، فاذا انقضى الأجل انتقل الخيار الى المدين."}, {"number": "277", "chapter": "الفصل الثانى", "text": "------- اذا كان الخيار للمدين، ثم استحال تنفيذ كل من الأشياء المتعددة التى اشتمل عليها محل الالتزام ، وكان المدين مسئولا عن هذه الاستحالة ولو فيما يتعلق بواحدة من هذه الأشياء كان ملزما بأن يدفع قيمة آخر شئ استحال تنفيذه. 2- الإلتزام البدلى"}, {"number": "278", "chapter": "الفصل الثانى", "text": "1- يكون الالتزام بدليا اذا لم يشمل محله الا شيئا واحدا، ولكن تبرأ ذمة المدين اذا أدى بدلا منه شيئا آخر. 2- والشئ الذى يشمله محل الالتزام ، لا البديل الذى تبرأ ذمة المدين بأدائه ،هو وحده محل الالتزام وهو الذى يعين طبيعته."}, {"number": "279", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "التضامن بين الدائنين أو المدينين لايفترض، وانما يكون بناء على اتفاق أو نص فى القانون."}, {"number": "280", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- اذا كان التضامن بين الدائنين , جاز للمدين أن يوفى الدين لأى منهم ، الا اذا مانع أحدهم فى ذلك. 2- ومع ذلك لايحول التضامن دون انقسام الدين بين ورثة أحد الدائنين المتضامنين الا اذا كان الدين غير قابل للانقسام."}, {"number": "281", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- يجوز للدائنين المتضامنين ، مجتمعين أو منفردين، مطالبة المدين بالوفاء ، ويراعى فى ذلك ما يلحق رابطة كل دائن من وصف يعدل من أثر الدين. 2- ولايجوز للمدين اذا طالبه أحد الدائنين المتضامنين بالوفاء أن يحتج على هذا الدائن بأوجه الدفع الخاصة بغيره من الدائنين، ولكن يجوز له أن يحتج على الدائن المطالب بأوجه الدفع الخاصة بهذا الدائن ، وبأوجه الدفع المشتركة بين الدائنين جميعا."}, {"number": "282", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "1- اذا برئت ذمة المدين قبل أحد الدائنين المتضامنين بسبب غير الوفاء فلا تبرأ ذمته قبل الدائنين الابقدر حصة الدائن الذى برئت ذمة المدين قبله. 2- ولايجوز لأحد الدائنين المتضامنين أن يأتى عملا من شأنه الاضرار بالدائنين الآخرين."}, {"number": "283", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "1- كل مايستوفيه احد الدائنين المتضامنين من الدين يصير من حق الدائنين جميعا ويتحاصون فيه. 2- وتكون القسمة بينهم بالتساوى ، الا اذا وجد اتفاق أو نص يقضى بغير ذلك."}, {"number": "284", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "اذا كان التضامن بين المدينين فان وفاء أحدهم بالدين مبرئ لذمة الباقين."}, {"number": "285", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- يجوز للدائن مطالبة المدينين المتضامنين بالدين مجتمعين أو منفردين، ويراعى فى ذلك ما يلحق رابطة كل مدين من وصف يعدل من أثر الدين. 2- ولايجوز للمدين الذى يطالبه الدائن بالوفاء أن يحتج بأوجه الدفع الخاصة بغيره من المدينين، ولكن يجوز له أن يحتج بأوجه الدفع الخاصة به وبالأوجه المشتركة بين المدينين جميعا."}, {"number": "286", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- يترتب على تجديد الدين بين الدائن واحد المدينين المتضامنين ان تبرأ ذمة باقى المدينين ، الا اذا احتفظ الدائن بحقه قبلهم."}, {"number": "287", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- لايجوز للمدين المتضامن أن يتمسك بالمقاصة التى تقع بين الدائن ومدين متضامن آخر، الا بقدر حصة هذا المدين."}, {"number": "288", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- اذا اتحدت الذمة بين الدائن وأحد مدينيه المتضامنين، فان الدين لاينقضى بالنسبة الى باقى المدينين ، الابقدر حصة المدين الذى اتحدت ذمته مع الدائن."}, {"number": "289", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "1- اذا أبرأ الدائن أحد المدينين المتضامنين ، فلا تبرأ ذمة الباقين، الااذا صرح الدائن بذلك. 2- فاذا لم يصدر منه هذا التصريح ، لم يكن له أن يطالب باقى المدينين المتضامنين الا بما يبقى من الدين بعد خصم حصة المدين الذى أبرأه، الا أن يكون قد احتفظ بحقه فى الرجوع عليهم بكل الدين. وفى هذه الحالة يكون لهم حق الرجوع على المدين الذى صدر الابراء لصالحه بحصته فى الدين."}, {"number": "290", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "اذا أبرأ الدائن أحد المدينين المتضامنين من التضامن بقى حقه فى الرجوع على الباقين بكل الدين ، ما لم يتفق على غير ذلك."}, {"number": "291", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------ 1- فى جميع الأحوال التى يبرئ فيها الدائن أحد المدينين المتضامنين، سواء أكان الابراء من الدين أم من التضامن ، يكون لباقى المدينين أن يرجعوا عند الاقتضاء على هذا المدين بنصيته فى حصة المعسر منهم وفقا للمادة 298. 2- على أنه اذا أخلى الدائن المدين الذى أبرأه من كل مسئوليه عن الدين ، فان هذا الدائن هو الذى يتحمل نصيب هذا المدين فى حصة المعسر."}, {"number": "292", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- اذا انقضى الدين بالتقادم بالنسبة الى أحد المدينين المتضامنين ، فلا يستفيد من ذلك باقى المدينين الا بقدر حصة هذا المدين. 2- واذا انقطعت مدة التقادم أو وقف سريانه بالنسبة الى أحد المدينين المتضامنين، فلا يجوز للدائن أن يتمسك بذلك باقى المدينين الا بقدر حصة هذا المدين. 2- واذا انقطعت مدة التقادم أو وقف سريانه بالنسبة الى أحد المدينين المتضامنين ، فلا يجوز للدائن أن يتمسك بذلك قبل باقى المدينين."}, {"number": "293", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "1- لايكون المدين المتضامن مسئولا فى تنفيذ الالتزام الا عن فعله. 2- واذا أعذر الدائن أحد المدينين المتضامنين أو قاضاه، فلا يكون لذلك أثر بالنسبة الى باقى المدينين ، أما اذا أعذر أحد المدينين المتضامنين الدائن ، فان باقى المدينين يستفيدون من هذا الاعذار."}, {"number": "294", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "اذا تصالح الدائن مع أحد المدينين المتضامنين وتضمن الصلح الابراء من الدين أو براءة الذمة بأية وسيلة أخرى ، استفاد منه الباقون أما اذا كان من شأن هذا الصلح أن يرتب فى ذمتهم التزاما أو يزيد فيما هم ملتزمون به ، فانه لاينفذ فى حقهم الا اذا قبلوه."}, {"number": "295", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- اذا أقر أحد المدينين المتضامنين بالدين ، فلا يسرى هذا الاقرار فى حق الباقين. 2- واذا نكل أحد المدينين المتضامنين عن اليمين أو وجه الى الدائن يمينا حلفها، فلا يضار بذلك باقى المدينين. 3- واذا اقتصر الدائن على توجيه اليمين الى أحد المدينين المتضامنين فحلف ، فان المدينين الآخرين يستفيدون من ذلك."}, {"number": "296", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------ 1- اذا صدر حكم على أحد المدينين المتضامنين فلا يحتج بها الحكم على الباقين. 2- أما اذا صدر الحكم لصالح أحدهم ، فيستفيد منه الباقون الا اذا كان الحكم مبنيا على سبب خاص بالمدين الذى صدر الحكم لصالحه."}, {"number": "297", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- اذا وفى أحد المدينين المتضامنين كل الدين ، فلا يجوز له أن يرجع على أى من الباقين الا بقدر حصته فى الدين ، ولو كان بما له من حق الحلول قد رجع بدعوى الدائن. 2- وينقسم الدين اذا وفاه أحد المدينين حصصا متساوية بين الجميع, مالم يوجد اتفاق أو نص يقضى بغير ذلك."}, {"number": "298", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "اذا أعسر أحد المدينين المتضامنين تحمل تبعة هذا الاعسار المدين الذى وفى الدين ، وسائر المدينين الموسرين ، كل بقدر حصته."}, {"number": "299", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "اذا كان أحد المدينين المتضامنين هو وحده صاحب المصلحة فى الدين فهو الذى يتحمل به كله نحو الباقين. 3- عدم القابلية للإنقسام"}, {"number": "300", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "يكون الالتزام غير قابل للانقسام: (أ) اذا ورد على محل لايقبل بطبيعته أن ينقسم. (ب) اذا تبين من الغرض الذى رمى اليه المتعاقدان أن الالتزام لايجوز تنفيذه منقسما ، أو اذا انصرفت نية المتعاقدين الى ذلك ."}, {"number": "301", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "1- اذا تعدد المدينون فى التزام غير قابل للانقسام كان كل منهم ملزما بوفاء الدين كاملا. 2- وللمدين الذى وفى بالدين حق الرجوع على الباقين ، كل بقدر حصته الا اذا تبين من الظروف غير ذلك."}, {"number": "302", "chapter": "الفصل الثالث تعدد طرفى الإلتزام", "text": "------- 1- اذا تعدد الدائنون فى التزام غير قابل للانقسام، أو تعدد ورثه الدائن فى هذا الالتزام ، جاز لكل دائن أو وارث ان يطالب بأداء الالتزام كاملا ، فاذا اعترض أحد الدائنين أو الورثة على ذلك ، كان المدين ملزما بأداء الالتزام للدائنين مجتمعين أو أيداع الشئ محل الالتزام. 2- ويرجع الدائنون على الدائن الذى استوفى الالتزام ، كل بقدر حصته."}, {"number": "303", "chapter": "الفصل الأول", "text": "يجوز للدائن أن يحول حقه الى شخص آخر، الا اذا حال دون ذلك نص القانون أو اتفاق المتعاقدين أو طبيعة الالتزام. ويتم الحوالة دون حاجة الى رضاء المدين."}, {"number": "304", "chapter": "الفصل الأول", "text": "لايجوز حوالة الحق الا بمقدار ما يكون منه قابلا للحجز."}, {"number": "305", "chapter": "الفصل الأول", "text": "لا تكون الحوالة نافذة قبل المدين أو قبل الغير الا اذا قبلها المدين أو أعلن بها. على أن نفاذها قبل الغير بقبول المدين يستلزم أن يكون هذا القبول ثابت التاريخ."}, {"number": "306", "chapter": "الفصل الأول", "text": "------- يجوز قبل اعلان الحوالة أو قبولها أن يتخذ الدائن المحال له من الاجراءات ما يحافظ به على الحق الذى انتقل اليه."}, {"number": "307", "chapter": "الفصل الأول", "text": "------- تشمل حوالة الحق ضماناته، كالكفالة والامتياز والرهن ، كما تعتبر شاملة لما حل من فوائد وأقساط."}, {"number": "308", "chapter": "الفصل الأول", "text": "1- اذا كانت الحوالة بعوض فلا يضمن المحيل الا وجود الحق المحال به وقت الحوالة ، مالم يوجد اتفاق يقضى بغير ذلك. 2- أما اذا كانت الحوالة بغير عوض، فلا يكون المحيل ضامنا حتى لوجود الحق."}, {"number": "309", "chapter": "الفصل الأول", "text": "1- لايضمن المحيل يسار المدين الا اذا وجد اتفاق خاص على هذا الضمان. 2- واذا ضمن المحيل يسار المدين ، فلا ينصرف هذا الضمان الا الى اليسار وقت الحوالة مالم يتفق على غير ذلك."}, {"number": "310", "chapter": "الفصل الأول", "text": "اذا رجع المحال له بالضمان على المحيل طبقا للمادتين السابقتين فلا يلزم المحيل الا برد ما استولى عليه مع الفوائد والمصروفات، ولو وجد اتفاق يقضى يغير ذلك."}, {"number": "311", "chapter": "الفصل الأول", "text": "------- يكون المحيل مسئولا عن أفعاله الشخصية ، ولو كانت الحوالة بغير عوض أو اشترط عدم الضمان."}, {"number": "312", "chapter": "الفصل الأول", "text": "للمدين أن يتمسك قبل المحال له بالدفوع التى كان له أن يتمسك بها قبل المحيل وقت نفاذ الحوالة فى حقه ، كما يجوز له أن يتمسك بالدفوع المستمدة من عقد الحوالة."}, {"number": "313", "chapter": "الفصل الأول", "text": "اذا تعددت الحوالة بحق واحد فضلت الحوالة التى تصبح قبل غيرها نافذة فى حق الغير."}, {"number": "314", "chapter": "الفصل الأول", "text": "------- 1- اذا وقع تحت يد المحال عليه حجز قبل أن تصبح الحوالة نافذة فى حق الغير، كانت الحوالة بالنسبة الى الحاجز بمثابة حجز آخر. 2- وفى هذه الحالة اذا وقع حجز آخر بعد أن أصبحت الحوالة نافذة فى حق الغير ، فان الدين يقسم بين الحاجز المتقدم والمحال له والحاجز المتأخر قسمة غرماء ، على أن يؤخذ من حصة الحاجز المتأخر ما يستكمل به المحال له قيمة الحوالة."}, {"number": "315", "chapter": "الفصل الثانى", "text": "تتم حوالة الدين باتفاق بين المدين وشخص آخر يتحمل عنه الدين."}, {"number": "316", "chapter": "الفصل الثانى", "text": "------- 1- لاتكون الحوالة نافذة فى حق الدائن الا اذا أقرها. 2- واذا قام المحال عليه أو المدين الأصلى باعلان الحوالة الى الدائن، وعين له أجلا معقولا ليقر الحوالة ثم انقضى الأجل دون أن يصدر الاقرار، اعتبر سكوت الدائن رفضا للحوالة."}, {"number": "317", "chapter": "الفصل الثانى", "text": "1- مادام الدائن لم يحدد موقفه من الحوالة اقرار أو رفضا ، كان المحال عليه ملزما قبل المدين الأصلى بالوفاء للدائن فى الوقت المناسب مالم يوجد اتفاق بغير ذلك . ويسر هذا الحكم ولو رفض الدائن الحوالة. 2- على أنه لايجوز للمدين الأصلى أن يطالب المحال عليه بالوفاء للدائن ما دام لم يقم بما التزم به نحو المحال عليه بمقتضى عقد الحوالة."}, {"number": "318", "chapter": "الفصل الثانى", "text": "1- تبقى للدين المحال به ضماناته. 2- ومع ذلك لايبقى الكفيل ، عينيا كان أو شخصيا، ملتزما قبل الدائن الا اذا رضى بالحوالة."}, {"number": "319", "chapter": "الفصل الثانى", "text": "يضمن المدين الأصلى أن يكون المحال عليه موسرا وقت اقرار الدائن للحوالة، مالم يتفق على غير ذلك."}, {"number": "320", "chapter": "الفصل الثانى", "text": "للمحال عليه أن يتمسك قبل الدائن بالدفوع التى كان للمدين الاصلى أن يتمسك بها، كما يجوز له أن يتمسك بالدفوع المستمدة من عقد الحوالة."}, {"number": "321", "chapter": "الفصل الثانى", "text": "------- 1- يجوز أيضا أن تتم حوالة الدين باتفاق بين الدائن والمحال عليه يتقرر فيه ان هذا يحل محل المدين الأصلى فى التزامه. 2- وتسرى فى هذه الحالة أحكام المادتين 318, 320."}, {"number": "322", "chapter": "الفصل الثانى", "text": "1- لايستتبع بيع العقار المرهون رهنا رسميا انتقال الدين المضمون بالرهن الى ذمة المشترى الا اذا كان هناك اتفاق على ذلك. 2- فاذا اتفق البائع والمشترى على حوالة الدين ، وسجل عقد البيع تعين على الدائن متى أعلن رسميا بالحوالة أن يقرها أو يرفضها فى ميعاد لايتجاوز ستة أشهر، فاذا انقضى هذا الميعاد دون أن يبت برأى اعتبر سكوته اقرارا."}, {"number": "323", "chapter": "الفصل الأول", "text": "1- يصح الوفاء من المدين أو من نائبه أو من أى شخص آخر له مصلحة فى الوفاء، وذلك مع مراعاة ما جاء بالمادة 208. 2- ويصح الوفاء أيضاء مع التحفظ السابق ممن ليست له مصلحة فى هذا الوفاء ، ولو كان ذلك دون علم المدين أو رغم ارادته، على أنه يجوز للدائن أن يرفض الوفاء من الغير اذا اعترض المدين على ذلك وأبلغ الدائن هذا الاعتراض."}, {"number": "324", "chapter": "الفصل الأول", "text": "1- اذا قام الغير بوفاء الدين ، كان له حق الرجوع على المدين بقدر ما دفعه. 2- ومع ذلك يجوز للمدين الذى حصل الوفاء بغير ارادته أن يمنع رجوع الموفى بما وفاه عنه كلا أو بعضا ، اذا أثبت أن له أية مصلحة فى الاعتراض على الوفاء."}, {"number": "325", "chapter": "الفصل الأول", "text": "1- يشترط لصحة الوفاء أن يكون الموفى مالكا للشئ الذى وفى ، وأن يكون ذا أهلية للتصرف فيه. 2- ومع ذلك فالوفاء بالشئ المستحق ممن ليس أهلا للتصرف فيه ينقضى به الالتزام اذا لم يلحق الوفاء ضررا بالموفى."}, {"number": "326", "chapter": "الفصل الأول", "text": "------- اذا قام بالوفاء شخص غير المدين ، حل الموفى محل الدائن الذى استوفى حقه فى الأحوال الآتية: (أ) اذا كان الموفى ملزما بالدين مع المدين أو ملزما بوفائه عنه. (ب) اذا كان الموفى دائنا ووفى دائنا آخر مقدما عليه بما له من تأمين عينى، ولو لم يكن للموفى أى تأمين. (جـ) اذا كان الموفى قد اشترى عقارا ودفع ثمنه وفاء لدائنين خصص العقار لضمان حقوقهم. (د) اذا كان هناك نص خاص يقرر للموفى حق الحلول."}, {"number": "327", "chapter": "الفصل الأول", "text": "------- للدائن الذى استوفى حقه من غير المدين أن يتفق مع هذا الغير على أن يحل محله، ولو لم يقبل المدين ذلك ، ولايصح أن يتأخر هذا الاتفاق عن وقت الوفاء."}, {"number": "328", "chapter": "الفصل الأول", "text": "يجوز أيضا للمدين اذا اقترض مالا وفى به الدين أن يحل المقرض محل الدائن الذى استوفى حقه، ولو بغير رضاء هذا الدائن ، على أن يذكر فى عقد القرض أن المال قد خصص للوفاء، وفى المخالصة أن الوفاء كان من هذا المال الذى أقرضه الدائن الجديد."}, {"number": "329", "chapter": "الفصل الأول", "text": "------- من حل قانونا أو اتفاقا محل الدائن كان له حقه بما لهذا الحق من خصائص ، وما يلحقه من توابع ، وما يكفله من تأمينات، وما يرد عليه من دفوع، ويكون هذا الحلول بالقدر الذى أداه من ماله من حل محل الدائن."}, {"number": "330", "chapter": "الفصل الأول", "text": "------- 1- اذا وفى الغير الدائن جزاء من حقه وحل محله فيه ، فلا يضار الدائن بهذا الوفاء ويكون فى استيفاء ما بقى له من حق مقدما على من وفاه ، ما لم يوجد اتفاق يقضى بغير ذلك. 2- فاذا حل شخص آخر محل الدائن فيما بقى له من حق رجع من حل أخيرا هو ومن تقدمة فى الحلول كل بقدر ماهو مستحق له وتقاسما قسمة الغرماء."}, {"number": "331", "chapter": "الفصل الأول", "text": "------- اذا وفى حائز العقار المرهون كل الدين، وحل محل الدائنين ، فلا يكون له بمقتضى هذا الحلول أن يرجع على حائز لعقار آخر مرهون فى ذات الدين الا بقدر حصة هذا الحائز بحسب قيمة ماحازه من عقار."}, {"number": "332", "chapter": "الفصل الأول", "text": "يكون الوفاء للدائن أو لنائبه. ويعتبر ذا صفة فى استيفاء الدين من يقدم للمدين مخالصة صادرة من الدائن ، الا اذا كان متفقا على أن الوفاء يكون للدائن شخصيا."}, {"number": "333", "chapter": "الفصل الأول", "text": "اذا كان الوفاء لشخص غير الدائن أو نائبه ، فلا تبرأ ذمة المدين الا اذا أقر الدائن هذا الوفاء أو عادت عليه منفعة منه، وبقدر هذه المنفعة ، أو تم الوفاء بحسن نية لشخص كان الدين فى حيازته."}, {"number": "334", "chapter": "الفصل الأول", "text": "اذا رفض الدائن دون مبرر قبول الوفاء المعروض عرضا صحيحا، أو رفض القيام بالأعمال التى لايتم الوفاء، بدونها، أو أعلن أنه لن يقبل الوفاء ، اعتبر أنه قد تم اعذاره من الوقت الذى يسجل المدين عليه هذا الرفض باعلان رسمى."}, {"number": "335", "chapter": "الفصل الأول", "text": "------- اذا تم اعذار الدائن ، تحمل تبعة هلاك الشئ أو تلفه، ووقف سريان الفوائد، وأصبح للمدين الحق فى ايداع الشئ على نفقة الدائن والمطالبة بتعويض ما أصابه من ضرر."}, {"number": "336", "chapter": "الفصل الأول", "text": "------- اذا كان محل الوفاء شيئا معينا بالذات ، وكان الواجب أن يسلم فى المكان الذى وجد فيه، جاز للمدين بعد أن ينذر الدائن بتسلمه أن يحصل على ترخيص من القضاء فى ايداعه. فاذا كان هذا الشئ عقارا أو شيئا معدا للبقاء حيث وجد، جاز للمدين أن يطلب وضعه تحت الحراسة."}, {"number": "337", "chapter": "الفصل الأول", "text": "------- 1- يجوز للمدين بعد استئذان القضاء أن يبيع بالمزاد العلنى الأشياء التى يسرع اليها التلف، أو التى تكلف نفقات باهظة فى ايداعها أو حراستها، وأن يودع الثمن خزانة المحكمة. 2- فاذا كان الشئ له سعر معروف فى الأسواق ، أو كان التعامل فيه متداولا فى البورصات فلا يجوز بيعه بالمزاد الا اذا تعذر البيع ممارسة بالسعر المعروف."}, {"number": "338", "chapter": "الفصل الأول", "text": "يكون الايداع أو مايقوم مقامه من اجراء جائزا أيضا، اذا كان المدين يجهل شخصية الدائن وموطنه ، أو كان الدائن عديم الاهلية أو ناقصها ولم يكن له نائب يقبل عنه الوفاء، أو كان الدين متنازعا عليه بين عدة أشخاص، أو كانت هناك أسباب جدية أخرى تبرر هذا الاجراء"}, {"number": "339", "chapter": "الفصل الأول", "text": "------- يقوم العرض الحقيقى بالنسبة الى المدين مقام الوفاء ، اذا تلاه ايداع يتم وفقا لاحكام قانون المرافعات، أو تلاه أى اجراء مماثل ، وذلك اذا قبله الدائن أو صدر حكم نهائى بصحته."}, {"number": "340", "chapter": "الفصل الأول", "text": "1- اذا عرض المدين الدين وأتبع العرض بايداع أو باجراء مماثل ، جاز له أن يرجع فى هذا العرض ما دام الدائن لم يقبله، أو ما دام لم يصدر حكم نهائى بصحته واذا رجع فلا تبرأ ذمة شركائه فى الدين ولا ذمة الضامنين. 2- فاذا رجع المدين فى العرض بعد أن قبله الدائن ، أو بعد ان حكم بصحته، وقبل الدائن منه هذا الرجوع، لم يكن لهذا الدائن أن يتمسك بعد ذلك بما يكفل حقه من تأمينات وتبرأ ذمة الشركاء فى الدين وذمة الضامنين. 2- محل الوفاء"}, {"number": "341", "chapter": "الفصل الأول", "text": "الشئ المستحق أصلا هو الذى به يكون الوفاء فلا يجبر الدائن على قبول شئ غيره، ولو كان هذا الشئ مساويا له فى القيمة أو كانت له قيمة أعلى."}, {"number": "342", "chapter": "الفصل الأول", "text": "1- لايجوز للمدين أن يجبر الدائن على أن يقبل وفاء جزئيا لحقه ، مالم يوجد اتفاق أو نص يقضى بغير ذلك. 2- فاذا كان الدين متنازعا فى جزء منه وقبل الدائن أن يستوفى الجزء المعترف به ، فليس للمدين أن يرفض الوفاء بهذا الجزء"}, {"number": "343", "chapter": "الفصل الأول", "text": "اذا كان المدين ملزما بأن يوفى مع الدين مصروفات وفوائد وكان ما أداه لايفى بالدين مع هذه الملحقات، خصم ما أدى من حساب المصروفات ثم من الفوائد ثم من أصل الدين، كل هذا ما لم يتفق على غيره."}, {"number": "344", "chapter": "الفصل الأول", "text": "اذا تعددت الديون فى ذمة المدين، وكانت لدائن واحد ومن جنس واحد ، وكان ما أداه المدين لايفى بهذه الديون جميعا، جاز للمدين عند الوفاء أن يعين الدين الذى يريد الوفاء به، ما لم يوجد مانع قانونى أو اتفاقى يحول دون هذا التعيين."}, {"number": "345", "chapter": "الفصل الأول", "text": "اذا لم يعين الدين على الوجه المبين فى المادة السابقة كان الخصم من حساب الدين الذى حل ، فاذا تعددت الديون الحالة فمن حساب أشدها كلفة على المدين ، فاذا تساوت الديون فى الكلفة فمن حساب الدين الذى يعينه الدائن."}, {"number": "346", "chapter": "الفصل الأول", "text": "------- 1- يجب أن يتم الوفاء فورا بمجرد ترتيب الالتزام نهائيا فى ذمة المدين، مالم يوجد اتفاق أو نص يقضى بغير ذلك. 2- على أنه يجوز للقاضى فى حالات استثنائية، اذا لم يمنعه نص فى القانون ، أن ينظر المدين الى أجل معقول أو آجال ينفذ فيها التزامه، اذا استدعت حالته ذلك ولم يلحق الدائن من التأجيل ضرر جسيم."}, {"number": "347", "chapter": "الفصل الأول", "text": "------- 1- اذا كان محل الالتزام شيئا معينا بالذات وجب تسليمه فى المكان الذى كان موجودا فيه وقت نشوء الالتزام ، مالم يوجد اتفاق أو نص يقضى بغير ذلك. 2- أما فى الالتزامات الأخرى فيكون الوفاء فى المكان الذى يوجد فيه موطن المدين وقت الوفاء ، أو فى المكان الذى يوجد فيه مركز أعمال المدين اذا كان الالتزام متعلقا بهذه الأعمال."}, {"number": "348", "chapter": "الفصل الأول", "text": "------- تكون نفقات الوفاء على المدين ، الا اذا وجد اتفاق أو نص يقضى بغير ذلك."}, {"number": "349", "chapter": "الفصل الأول", "text": "------- 1- لمن قام بوفاء جزء من الدين أن يطلب مخالصة بما وفاه مع التأشير على سند الدين بحصول هذا الوفاء ، فاذا وفى الدين كله كان له أن يطلب رد سند الدين أو الغاءه، فان كان السند قد ضاع كان له أن يطلب من الدائن أن يقر كتابة بضياع السند. 2- فاذا رفض الدائن القيام بما فرضته عليه الفقرة السابقة ، جاز للمدين أن يودع الشئ المستحق ايداعا قضائيا."}, {"number": "350", "chapter": "الفصل الثانى", "text": "اذا قبل الدائن فى استيفاء حقه مقابلا استعاض به عن الشئ المستحق قام هذا مقام الوفاء."}, {"number": "351", "chapter": "الفصل الثانى", "text": "يسرى على الوفاء بمقابل ، فيما اذا كان بنقل ملكية شئ أعطى فى مقابله الدين ، أحكام البيع ، والأخص ما تعلق منها بأهلية المتعاقدين وضمان الاستحقاق وضمان العيوب الخفية. ويسرى عليه من حيث أنه يقضى الدين أحكام الوفاء ، وبالأخص ماتعلق منها بتعيين جهة الدفع وانقضاء التأمينات. 2- التجديد والإنابة"}, {"number": "352", "chapter": "الفصل الثانى", "text": "------- يتجدد الالتزام : أولا:- بتغيير الدين اذا اتفق الطرفان على أن يستبدلا بالالتزام الأصلى التزاما جديدا يختلف عنه فى محله أو فى مصدره. ثانيا:- بتغيير المدين اذ اتفق الدائن مع أجنبى على أن يكون هذا الاجنبى مدينا مكان المدين الاصلى ، وعلى ان تبرأ ذمة المدين الأصلى دون حاجة لرضائه، أو اذا حصل المدين عل رضاء الدائن بشخص أجنبى قبل أن يكون هو المدين الجديد."}, {"number": "353", "chapter": "الفصل الثانى", "text": "1- لايتم التجديد الا اذا كان الالتزامان القديم والجديد قد خلا كل منهما من أسباب البطلان. 2- أما اذا كان الالتزام القديم ناشئا عن عقد قابل للابطال ، فلا يكون التجديد صحيحا الا اذا قصد بالالتزام الجديد أجازة العقد، وأن يحل محله."}, {"number": "354", "chapter": "الفصل الثانى", "text": "1- التجديد لايفترض ، بل يجب أن يتفق عليه صراحة، أو أن يستخلص بوضوح من الظروف. 2- وبوجه خاص لا يستفاد التجديد من كتابة سند بدين موجود قبل ذلك ، ولا مما يحدث فى الالتزام من تغيير لايتناول الا زمان الوفاء أو مكانه أو كيفيته، ولا مما يدخل على الالتزام من تعديل لايتناول الا التأمينات أو سعر الفائدة، كل هذا مالم يوجد اتفاق يقضى بغيره"}, {"number": "355", "chapter": "الفصل الثانى", "text": "1- لايكون تجديدا مجرد تقييد الالتزامات فى حساب جار. 2- وانما يتجدد الالتزام اذا قطع رصيد الحساب وتم اقراره. على أنه اذا كان الالتزام مكفولا بتأمين خاص ، فان هذا التأمين يبقى ما لم يتفق على ذلك."}, {"number": "356", "chapter": "الفصل الثانى", "text": "1- يترتب على التجديد أن ينقضى الالتزام الأصلى بتوابعه وأن ينشأ مكانه التزام جديد. 2- ولاينتقل الى الالتزام الجديد التأمينات التى كانت تكفل تنفيذ الالتزام الأصلى الا بنص فى القانون، أو الا اذا تبين من الاتفاق أو من الظروف أن المتعاقدين قد انصرفت الى ذلك."}, {"number": "357", "chapter": "الفصل الثانى", "text": "1- اذا كانت هناك تأمينات عينية قدمها المدين لكفالة الالتزام الأصلى، فان الاتفاق على نقل هذه التأمينات الى الالتزام الجديد تراعى فيه الأحكام الآتية: (أ) اذا كان التجديد بتغيير الدين ، جاز للدائن والمدين أن يتفقا على انتقال التأمينات للالتزام الجديد فى الحدود التى لاتلحق ضررا بالغير. (ب) اذا كان التجديد بتغيير المدين، جاز للدائن والمدين الجديد أن يتفقا على استبقاء التأمينات العينية، دون حاجة الى رضاء المدين القديم. (جـ) اذا كان التجديد بتغيير الدائن ، جاز للمتعاقدين ثلاثتهم أن يتفقوا على استبقاء التأمينات. 2-ولا يكون الاتفاق على نقل التأمينات العيني نافذا فى حق الغير الا اذا تم مع التجديد فى وقت واحد، هذا مع مراعاة الأحكام المتعلقة بالتسجيل."}, {"number": "358", "chapter": "الفصل الثانى", "text": "لاينتقل الى الالتزام الجديد الكفالة عينية كانت أو شخصية ولا التضامن ، الا اذا رضى بذلك الكفلاء والمدينون المتضامنون."}, {"number": "359", "chapter": "الفصل الثانى", "text": "1- تتم الانابة اذا حصل المدين على رضاء الدائن بشخص أجنبى يلتزم بوفاء الدين مكان المدين. 2- ولاتقتضى الانابة أن تكون هناك مديونية سابقة ما بين المدين والأجنبى."}, {"number": "360", "chapter": "الفصل الثانى", "text": "1- اذا اتفق المتعاقدون فى الانابة على أن يستبدلوا بالتزام سابق التزاما جديدا، كانت هذه الانابة تجديدا للالتزام بتغيير المدين، ويترتب عليها أن تبرأ ذمة المنيب قبل المناب لديه، على أن يكون الالتزام الجديد الذى ارتضاه المناب صحيحا وألا يكون المناب معسرا وقت الانابة. 2- ومع ذلك لا يفترض التجديد فىالانابة ، فاذا لم يكن هناك اتفاق على التجديد قام الالتزام الجديد الى جانب الالتزام الأول."}, {"number": "361", "chapter": "الفصل الثانى", "text": "يكون التزام المناب قبل المناب لدية صحيحا ولو كا التزامه قبل المنيب باطلا أو كان هذا الالتزام خاضعا لدفع من الدفوع، ولايبقى للمناب الا حق الرجوع على المنيب، كل هذا مالم يوجد اتفاق يقضى بغيره. 3- المقاصة"}, {"number": "362", "chapter": "الفصل الثانى", "text": "1- للمدين حق المقاصة بين ما هو مستحق عليه لدائنه وما هو مستحق له قبل هذا الدائن , ولو اختلف سبب الدينين ، اذا كان موضوع كل منهما نقودا أو مثليات متحدده فى النوع والجودة وكان كل منهما خاليا من النزاع مستحق الآداء صالحا للمطالبة به قضاء. 2- ولا يمنع المقاصة أن يتأخر ميعاد الوفاء لمهلة منحها القاضى أو تبرع بها الدائن."}, {"number": "363", "chapter": "الفصل الثانى", "text": "يجوز للمدين أن يمسك بالمقاصة ولو اختلف مكان الوفاء فى الدينين ولكن يجب عليه فى هذه الحالة أن يعوض الدائن عما لحقه من ضرر لعدم تمكنه بسبب المقاصة من استيفاء ما له من حق أو الوفاء بما عليه من دين فى المكان الذى عين لذلك."}, {"number": "364", "chapter": "الفصل الثانى", "text": "------- تقع المقاصة فى الديون أيا كان مصدرها وذلك فيما عدا الأحوال الآتية: (أ) اذا كان أحد الدينين شيئا نزع دون حق من يد مالكه وكان مطلوبا رده. (ب) اذا كان أحد الديني شيئا مودعا أو معارا عارية استعمال وكان مطلوبا رده. (جـ) اذا كان أحد الدينين حقا غير قابل للحجز."}, {"number": "365", "chapter": "الفصل الثانى", "text": "------- 1- لاتقع المقاصة الا اذا تمسك بها من له مصلحة فيها، ولايجوز النزول عنها قبل ثبوت الحق فيها. 2- ويترتب على المقاصة انقضاء الدينين بقدر الأقل منهما، منذ الوقت الذى يصبحان فيه صالحين للمقاصة، ويكون تعيين جهة الدفع فى المقاصة كتعيينها فى الوفاء."}, {"number": "366", "chapter": "الفصل الثانى", "text": "اذا كان الدين قد مضت عليه مدة التقادم وقت التمسك بالمقاصة فلا يمنع ذلك من وقوع المقاصة به رغم التمسك بالتقادم ما دامت هذه المدة لم تكن قد تمت فى الوقت الذى أصبحت فيه المقاصة ممكنة"}, {"number": "367", "chapter": "الفصل الثانى", "text": "1- لايجوز أن تقع المقاصة اضرار بحقوق كسبها الغير 2- فاذا أوقع الغير حجزا تحت يد المدين ، ثم أصبح المدين دائنا لدائنه، فلا يجوز له أن يتمسك بالمقاصة اضرارا بالحاجز."}, {"number": "368", "chapter": "الفصل الثانى", "text": "1- اذا حول الدائن حقه للغير وقبل المدين الحوالة دون تحفظ فلا يجوز لهذا المدين أن يتمسك قبل المحال له بالمقاصة التى كان له أن يتمسك بها قبل قبوله للحوالة ولايكون له الا الرجوع بحقه عل المحيل. 2-أما أذا كان المدين لم يقبل الحوالة وكلن أعلن بها ، فلا تمنعه هذه الحوالة أن يتمسك بالمقاصة."}, {"number": "369", "chapter": "الفصل الثانى", "text": "اذا وفى المدين دينا وكان له أن يطلب المقاصة فيه بحق له ، فلا يجوز أن يتمسك اضرارا بالغير بالتأمينات التى تكفل حقه الا اذا كان يجهل وجود هذا الحق. 4- إتحاد الذمة"}, {"number": "370", "chapter": "الفصل الثانى", "text": "1- اذا اجتمع فى شخص واحد صفتا الدائن والمدين بالنسبة الى دين واحد، انقضى هذا الدين بالقدر الذى اتحدت فيه الذمة. 2- واذا زال السبب الذى أدى لاتحاد الذمة ، وكان لزواله أثر رجعى، عاد الدين الى الوجود هو وملحقاته بالنسبة الى ذوى الشأن جميعا ويعتبر الذمة كأن لم يكن."}, {"number": "371", "chapter": "الفصل الثالث", "text": "ينقضى الالتزام اذا أبرأ الدائن مدينه مختارا ، ويتم الابراء متى وصل الى علم المدين ، ويرتد برده."}, {"number": "372", "chapter": "الفصل الثالث", "text": "1- يسرى على الابراء الأحكام الموضوعية التى تسرى على كل تبرع. 2- ولا يشترط فيه شكل خاص، ولو وقع على التزام يشترط لقيامه توافر شكل فرضه القانون أو اتفق عليه المتعاقدان. 2- إستحالة التنفيذ"}, {"number": "373", "chapter": "الفصل الثالث", "text": "ينقضى الالتزام اذا أثبت المدين أن الوفاء به أصبح مستحيلا عليه لسبب أجنبى لايد له فيه. 3- التقادم المسقط"}, {"number": "374", "chapter": "الفصل الثالث", "text": "يتقادم الالتزام بانقضاء خمس عشرة سنة فيما عدا الحالات التى ورد عنها نص خاص فى القانون وفيما عدا الاستثناءات التالية."}, {"number": "375", "chapter": "الفصل الثالث", "text": "1- يتقادم بخمس سنوات كل حق دورى متجدد ولو أقر به المدين، كأجرة المبانى والأراضى الزراعية ومقابل الحكر، وكالفوائد والايرادات المترتبة والمهايا والأجور والمعاشات. 2- ولايسقط الريع المستحق فى ذمة الحائز سئ النية ، ولا الريع الواجب على ناظر الوقف أداؤه للمستحقين الا بانقضاء خمس عشرة سنة."}, {"number": "376", "chapter": "الفصل الثالث", "text": "تتقادم بخمس سنوات حقوق الأطباء والصيادلة والمحامين والمهندسين والخبراء ووكلاء التفليسة والسماسرة والأساتذة والمعلمين، على أن تكون هذه الحقوق واجبة لهم جزاء عما أدوه من عمل من أعمال مهنتهم وما تكبدوه من مصروفات."}, {"number": "377", "chapter": "الفصل الثالث", "text": "\" 1- تتقادم بثلاث سنوات الضرائب والرسوم المستحقة للدولة، ويبدأ سريان التقادم فى الضرائب والرسوم السنوية من نهاية السنة التى تستحق عنها، وفى الرسوم الستحقة عن الأوراق القضائية من تاريخ انتهاء المرافعة فى الدعوى التى حررت فى شأنها هذه الأوراق ، أو من تاريخ تحريرها اذا لم تحصل مرافعة. 2- ويتقادم بخمس سنوات الحق فى المطالبة برد الضرائب والرسوم التى دفعت بغير حق ويبدأ سريانها من يوم دفعها . 3- ولاتخل الأحكام السابقة بأحكام النصوص الواردة فى القوانين الخاصة. إستبدلت الفقرة الثانية من المادة- بالمرسوم بقانون 106 لسنة 2011- الجريدة الرسمية – العدد28-مكرر فى 16-يوليه-2011\""}, {"number": "378", "chapter": "الفصل الثالث", "text": "1- تتقادم بسنة واحدة الحقوق الآتية: (أ) حقوق التجار والصناع عن أشياء، وحقوق أصحاب الفنادق والمطاعم عن أجر الاقامة وثمن الطعام وكل ماصرفوه لحساب عملائهم. (ب) حقوق العمال والخدم والأجراء من أجور يومية وغير يومية ومن ثمن ما قاموا به من توريدات. 2- ويجب على من يتمسك بأن الحق قد تقادم بسنة أن يحلف اليمين على أنه أدى الدين فعلا. وهذه اليمين يوجهها القاضى من تلقاء نفسه وتوجه الى ورثة المدين أو أوصيائهم، ان كانوا قصرا، بأنهم لايعلمون بوجود الدين أو يعلمون بحصول الوفاء"}, {"number": "379", "chapter": "الفصل الثالث", "text": "1- يبدأ سريان التقادم فى الحقوق المذكورة فى المادتين 376, 378 من الوقت الذى يتم فيه الدائنون تقدماتهم ، ولو استمروا يؤدون تقدمات أخرى. 2- واذا حرر سند بحق من هذه الحقوق فلا يتقادم الحق الابانقضاء خمس عشرة سنة."}, {"number": "380", "chapter": "الفصل الثالث", "text": "تحسب مدة التقادم بالأيام لا بالساعات ولا يحسب اليوم الأول ، وتكمل المدة بانقضاء آخر يوم منها."}, {"number": "381", "chapter": "الفصل الثالث", "text": "1- لايبدأ سريان التقادم فيما لم يرد فيه نص خاص الا من اليوم الذى أصبح فيه الدين مستحق الأداء. 2- وبخاصة لايسرى التقادم بالنسبة الى دين معلق على شرط واقف الا من الوقت الذى يتحقق فيه الشرط، وبالنسبة الى ضمان الاستحقاق الا من الوقت الذى يثبت فيه الاستحقاق ، وبالنسبة الى الدين المؤجل الا من الوقت الذى ينقضى فيه الأجل. 3- واذا كان تحديد ميعاد الوفاء متوقفا على ارادة الدائن سرى التقادم من الوقت الذى يتمكن فيه الدائن من اعلان ارادته."}, {"number": "382", "chapter": "الفصل الثالث", "text": "1- لايسرى التقادم كلما وجد مانع يتعذرعلى الدائن أن يطالب بحقه ولو كان المانع أدبيا. وكذلك لايسرى التقادم فيما بين الأصل والنائب. 2- ولايسرى التقادم الذى تزيد مدته على خمس سنوات فى حق من لاتتوافر فيه الاهلية أو فى حق الغائب أو فى حق المحكوم عليه بعقوبة جناية اذا لم يكن له نائب يمثله قانونا."}, {"number": "383", "chapter": "الفصل الثالث", "text": "ينقطع التقادم بالمطالبة القضائية ولو رفعت الدعوى الى محكمة غير مختصة وبالتنبه ، وبالحجز ، وبالطلب الذى يتقدم به الدائن لقبول حقه فى تفليس أو فى توزيع وبأى عمل يقوم به الدائن للتمسك بحقه أثناء السير فى احدى الدعاوى."}, {"number": "384", "chapter": "الفصل الثالث", "text": "------- 1- ينقطع التقادم اذا أقر المدين بحق الدائن اقرارا صريحا أو ضمنيا. 2-ويعتبر اقرارا ضمنيا أن يترك المدين تحت يد الدائن مالا له مرهونا رهنا حيازيا تأمينا لوفاء الدين."}, {"number": "385", "chapter": "الفصل الثالث", "text": "1- اذا انقطع التقادم بدأ تقادم جديد يسرى من وقت انتهاء الاثر المترتب على سبب الانقطاع، وتكون مدته هى مدة التقادم الأول. 2- على أنه اذا حكم الدين وحاز الحكم قوة الأمر المقضى أو اذا كان الدين مما يتقادم بسنة واحدة وانقطع تقادمه باقرار المدين، كانت مدة التقادم الجديد خمس عشرة سنة، الا أن يكون الدين المحكوم به متضمنا لالتزامات دورية متجددة لا تستحق الأداء الا بعد صدور الحكم."}, {"number": "386", "chapter": "الفصل الثالث", "text": "1- يترتب على التقادم انقضاء الالتزام ومع ذلك يتخلف فى ذمة المدين التزام طبيعى. 2- واذا سقط الحق بالتقادم سقطت معه الفوائد وغيرها من الملحقات لولم تكتمل مدة التقادم الخاصة بهذه الملحقات."}, {"number": "387", "chapter": "الفصل الثالث", "text": "1- لايجوز للمحكمة ان تقضى بالتقادم من تلقاء نفسها، بل يجب أن يكون ذلك بناء على طلب المدين أو بناء عى طلب دائنيه أو أى شخص له مصلحة فيه ولو لم يتمسك به المدين. 2- ويجوز التمسك بالتقادم فى أية حالة كانت عليها الدعوى ولو أمام المحكمة الاستئنافية."}, {"number": "388", "chapter": "الفصل الثالث", "text": "1- لايجوز النزول عن التقادم قبل ثبوت الحق فيه، كما لايجوز الاتفاق على أن يتم التقادم فى مدة تختلف عن المدة التى عينها القانون. 2- وانما يجوز لكل شخص يملك التصرف فى حقوقه أن ينزل ولو ضمنا عن التقادم بعد ثبوت الحق فيه، على أن هذا النزول لا ينفذ فى حق الدائنين اذا صدر اضرارا بهم. إثبات الإلتزام الغيت المواد من 389 إلى 417 بالقانون 25 لسنة 1968 الخاص بالإثبات"}, {"number": "418", "chapter": "الفصل الأول البيع", "text": "البيع عقد يلتزم به البائع أن ينقل للمشترى ملكية شئ أو حقا ماليا آخر فى مقابل ثمن نقدى."}, {"number": "419", "chapter": "الفصل الأول البيع", "text": "( 1 ) يجب أن يكون المشترى عالما بالمبيع علما كافيا ، ويعتبر العلم كافيا إذا اشتمل العقد على بيان المبيع وأوصافه الأساسية بيانا يمكن من تعرفه. ( 2 ) وإذا ذكر فى عقد البيع أن المشترى عالم بالمبيع. سقط حقه فى طلب إبطال البيع بدعوى عدم علمه به الا إذا اثبت تدليس البائع."}, {"number": "420", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا كان البيع \"بالعينة ، وجب أن يكون المبيع مطابقا لها. ( 2 ) وإذا تلفت \"العينة\" أو هلكت فى يد أحد المتعاقدين ولو دون خطأ ، كان على المتعاقد بائعا أو مشتريا أن يثبت أن الشئ مطابق للعينة أو غير مطابق."}, {"number": "421", "chapter": "الفصل الأول البيع", "text": "( 1 ) فى البيع بشرط التجزئة يجوز للمشترى أن يقبل المبيع أو يرفضه ، وعلى البائع أن يمكنه من التجربة ، فإذا رفض المشترى المبيع وجب أن يعلن الرفض فى المدة المتفق عليها ، فإن لم يكن هناك اتفاق على المدة ففى مدة معقولة يعينها ، البائع فإذا انقضت هذه المدة وسكت المشترى مع تمكنه من لتجربة المبيع اعتبر سكوته قبولا. ( 2 ) ويعتبر البيع بشرط التجربة معلقا على شرط واقف هو قبول المبيع الا إذا تبين من الاتفاق أو الظروف أن البيع معلق على شرط فاسخ."}, {"number": "422", "chapter": "الفصل الأول البيع", "text": "إذا بيع الشئ بشرط المذاق كان للمشترى أن يقبل البيع أن شاء ، ولكن عليه أن يعلن هذا القبول فى المدة التى يعينها الاتفاق أو العرف ولا ينعقد البيع الا من الوقت الذى يتم فيه هذا الإعلان."}, {"number": "423", "chapter": "الفصل الأول البيع", "text": "( 1 ) يجوز أن يقتصر تقدير الثمن على بيان الأسس التى يحدد بمقتضاها فيما بعد. ( 2 ) وإذا اتفق على أن الثمن هو سعر السوق ، وجب عند الشك ، أن يكون الثمن سعر السوق فى المكان والزمان اللذين يجب فيهما تسليم المبيع للمشترى ، فإذا لم يكن فى مكان التسليم سوق ، وجب الرجوع إلى سعر السوق فى المكان الذى يقضى العرف أن تكون أسعاره هى السارية."}, {"number": "424", "chapter": "الفصل الأول البيع", "text": "إذا لم يحدد المتعاقدان ثمنا للمبيع ، فلا يترتب على ذلك بطلان البيع متى تبين من الظروف أن المتعاقدين قد نويا اعتماد السعر المتداول فى التجارة أو السعر الذى جرى عليه التعامل بينهما."}, {"number": "425", "chapter": "الفصل الأول البيع", "text": "كان فى البيع غبن يزيد على الخمس فللبائع أن يطلب تكملة الثمن إلى أربعة أخماس ثمن المثل. ( 2 ) ويجب لتقدير ما إذا كان الغبن يزيد على الخمس أن يقوم العقار بحسب قيمته وقت البيع."}, {"number": "426", "chapter": "الفصل الأول البيع", "text": "( 1 ) تسقط بالتقادم دعوى تكملة الثمن بسبب الغبن إذا انقضت ثلاث سنوات من وقت توافر الأهلية أو من اليوم الذى يموت فيه صاحب العقار المبيع. ( 2 ) ولا تلحق مادة الدعوى ضررا بالغير حسن النية إذا كسب حقا عينيا على العقار المبيع."}, {"number": "427", "chapter": "الفصل الأول البيع", "text": "لا يجوز الطعن بالغبن فى بيع تم كنص القانون بطريق المزاد العلنى. التزامات البائع :"}, {"number": "428", "chapter": "الفصل الأول البيع", "text": "يلتزم البائع أن يقوم بما هو ضرورى لنقل الحق المبيع إلى المشترى وان يكف عن أى عمل من شأنه أن يجعل نقل الحق مستحيلا أو عسيرا."}, {"number": "429", "chapter": "الفصل الأول البيع", "text": "إذا كان البيع جزافا ، انتقلت الملكية إلى المشترى على النحو الذى تنتقل به فى الشئ المعين بالذات ، ويكون البيع جزافا ولو كان تحديد الثمن موقوفا على تقدير المبيع."}, {"number": "430", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا كان البيع مؤجل الثمن ، جاز للبائع أن يشترط أن تكون نقل أية إلى المشترى موقوفا على استيفاء الثمن كله ولو تم تسليم المبيع. ( 2 ) فإذا كان الثمن يدفع أقساطا. جاز للمتعاقدين أن يتفقا على أن يستبقى البائع جزء ، منه تعويضا له عن فسخ البيع إذا لم توف جميع الأقساط ، ومع ذلك يجوز للقاضى تبعا للظروف أن يخفض التعويض المتفق عليه وفقا للفقرة الثانية من المادة 224. ( 3 ) وإذا وفيت الأقساط جميعا ، فإن انتقال الملكية إلى المشترى يعتبر مستندا إلى وقت البيع. ( 4 ) وتسرى أحكام الفقرات الثلاث السابقة ولو سمى المتعاقدان البيع إيجارا."}, {"number": "431", "chapter": "الفصل الأول البيع", "text": "يلتزم البائع بتسليم المبيع للمشترى بالحالة التى كان عليها وقت البيع."}, {"number": "432", "chapter": "الفصل الأول البيع", "text": "يشمل التسليم ملحقات الشئ المبيع وكل ما اعد بصفة دائمة لاستعمال هذا الشئ وذلك طبقا لما تقضى به طبيعة الأشياء وعرف الجهة وقصد المتعاقدين."}, {"number": "433", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا عين فى العقد مقدار المبيع كان البائع مسئولا عن نقص هنا القدر بحسب ما يقضى به العرف ما لم يتفق على غير ذلك ، على انه لا يجوز للمشترى أن يطلب فسخ العقد لنقص فى المبيع الا إذا اثبت أن هذا النقص من الجسامة بحيث لو انه كان يعلمه لما أتم العقد. ( 2 ) اما إذا تبين أن القدر الدعوى يشتمل عليه المبيع يزيد على ما ذكر فى العقد وكان الثمن مقدرا بحساب الوحدة وجب على المشترى ، إذا كان المبيع غير قابل للتبعيض ، أن يكمل ، الثمن الا إذا كانت الزيادة جسيمة فيجوز له أن يطلب فسخ العقد وكل هذا ما لم يوجد اتفاق يخالفه."}, {"number": "434", "chapter": "الفصل الأول البيع", "text": "إذا وجد فى المبيع عجز أو زيادة ، فإن حق المشترى فى طلب إنقاص الثمن أو فى طلب فسخ العقد وحق البائع فى طلب تكملة الثمن يسقط كل منهما بالتقادم إذا انقضت سنة من وقت تسليم المبيع تسليما فعليا."}, {"number": "435", "chapter": "الفصل الأول البيع", "text": "( 1 ) يكون التسليم بوضع المبيع تحت تصرف المشترى بحيث يتمكن من حيازته والانتفاع به دون عائق ولو لم يستول عليه استيلاء ماديا مادام البائع قد اعلمه بذلك. ويحصل هذا التسليم على النحو الذى يتفق مع طبيعة الشئ المبيع. ( 2 ) ويجوز أن يتم التسليم بمجرد تراضى المتعاقدين إذا كان المبيع فى حيازة المشترى قبل البيع أو كان البائع قد استبقى المبيع فى حيازته بعد البيع لسبب آخر غير الملكية."}, {"number": "436", "chapter": "الفصل الأول البيع", "text": "إذا وجب تصدير المبيع للمشترى ، فلا يتم التسليم الا إذا وصل إليه ما لم يوجد اتفاق يقضى بغير ذلك."}, {"number": "437", "chapter": "الفصل الأول البيع", "text": "إذا هلك المبيع قبل التسليم لسبب لا يد للبائع فيه ، انفسخ البيع واسترد المشترى الثمن الا إذا كان الهلاك بعد أعذار المشترى لتسليم المبيع."}, {"number": "438", "chapter": "الفصل الأول البيع", "text": "إذا نقصت قيمة المبيع قبل التسليم لتلف أصابه ، جاز للمشترى اما أن يطلب فسخ البيع إذا كان النقص جسيما بحيث لو طرأ قبل العقد لما تم البيع ، واما أن يبقى البيع مع إنقاص الثمن."}, {"number": "439", "chapter": "الفصل الأول البيع", "text": "يضمن البائع عدم التعرض للمشترى فى الانتفاع بالمبيع كله أو بعضه سواء كان التعرض من فعله هو أو من فعل أجنبى يكون له وقت البيع حق على المبيع يحتج به على المشترى ويكون البائع ملزما بالضمان ولو كان الأجنبى قد ثبت حقه بعد البيع إذا كان هذا الحق قد آل إليه من البائع نفسه."}, {"number": "440", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا رفعت على المشترى دعوى بإستحقاق المبيع واخطر بها البائع ، كان على البائع بحسب الأحوال ، وفقا لقانون المرافعات أن يتدخل فى الدعوى إلى جانب المشترى أو أن يحل فيها محله. ( 2 ) فإذا تم الإخطار فى الوقت الملائم ولم يتدخل البائع فى الدعوى ، وجب عليه الضمان الا إذا اثبت أن الحكم الصادر فى الدعوى كان نتيجة لتدليس من المشترى أو لخطأ جسيم منه. ( 3 ) وإذا لم يخطر المشترى البائع الدعوى فى الوقت الملائم وصدر عليه حكم حاز قوة الأمر المقضى فقد حقه فى الرجوع بالضمان إذا اثبت البائع أن تدخله فى الدعوى كان يؤدى إلى رفض دعوى الإستحقاق."}, {"number": "441", "chapter": "الفصل الأول البيع", "text": "يثبت حق المشترى فى الضمان ولو اعترف وهو حسن النية للأجنبى بحقه أو تصالح معه على هذا الحق دون أن ينتظر فى ذلك صدور حكم قضائى متى كان قد أخطر البائع بالدعوى فى الوقت الملائم ودعاه أن يحل محله فيها فلم يفعل كل ذلك ما لم يثبت البائع أن الأجنبى لم يكن على حق فى دعواه."}, {"number": "442", "chapter": "الفصل الأول البيع", "text": "إذا توقى المشترى إستحقاق المبيع كله أو بعضه بدفع مبلغ من النقود أو بأداء شئ آخر ، كان للبائع أن يتخلص من نتائج الضمان بأن يرد للمشترى المبلغ الذى دفعه أو قيمة ما أداه من الفوائد القانونية وجميع المصروفات."}, {"number": "443", "chapter": "الفصل الأول البيع", "text": "إذا استحق كل المبيع كان للمشترى أن يطلب من البائع : ( 1 ) قيمة المبيع وقت الإستحقاق مع الفوائد القانونية من ذلك الوقت. ( 2 ) قيمة الثمار التى الزم المشترى بردها لمن استحق المبيع. ( 3 ) المصروفات النافعة التى لا يستطيع المشترى أن يلزم بها المستحق وكذلك المصروفات الكمالية إذا كان البائع سيئ النية. ( 4 ) جميع مصروفات دعوى الضمان ودعوى الإستحقاق عدا ما كان المشترى يستطيع أن يتقيه منها لو أخطر البائع بالدعوى طبقا للمادة 440. ( 5 ) وبوجه عام ، تعويض المشترى عما لحقه من خسارة أو فاته من كسب بسبب إستحقاق المبيع. كل هذا ما لم يكن رجوع المشترى مبنيا على المطالبة بفسخ البيع أو إبطاله."}, {"number": "444", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا أستحق بعض المبيع أو وجد مثقلا بتكليف وكانت خسارة المشترى عن ذلك قد بلغت قدرا لو علمه لما أتم العقد ، كان له أن يطالب البائع بالمبالغ المبينة فى المادة السابقة على أن يرد له المبيع وما أفاده منه. ( 2 ) فإذا اختار المشترى استبقاء المبيع ، أو كانت الخسارة التى لحقته لم تبلغ القدر المبين فى الفقرة السابقة لم يكن له الا أن يطالب بالتعويض عما أصابه من ضرر بسبب الإستحقاق."}, {"number": "445", "chapter": "الفصل الأول البيع", "text": "( 1 ) يجوز للمتعاقدين باتفاق خاص أن يزيدا ضمان الإستحقاق ، أو أن ينقصا منه ، أو أن يسقطا هذا الضمان. ( 2 ) ويفترض فى حق الارتفاق أن البائع قد اشترط عدم الضمان إذا كان هذا الحق طاهرا أو كان البائع قد أبان عنه للمشترى. ( 3 ) ويقع باطلا كل شرط يسقط الضمان أو ينقصه إذا كان البائع قد تعمد إخفاء حق الأجنبى."}, {"number": "446", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا اتفق على عدم الضمان بقى البائع مع ذلك مسئولا عن أى إستحقاق ينشأ من فعله ، ويقع باطلا كل اتفاق يقضى بغير ذلك. ( 2 ) اما إذا كان إستحقاق المبيع قد نشأ من فعل الغير ، فإن البائع يكون مسئولا عن رد قيمة المبيع وقت الإستحقاق ، الا إذا اثبت أن المشترى كان يعلم وقت البيع سبب الإستحقاق. أو انه اشترى ساقط الخيار."}, {"number": "447", "chapter": "الفصل الأول البيع", "text": "( 1 ) يكون البائع ملزما بالضمان إذا لم يتوافر فى المبيع وقت التسليم الصفات التى كفل للمشترى وجودها فيه ، أو إذا كان بالمبيع عيب ينقص من قيمته أو من نفعه بحسب الغاية المقصودة مستفادة مما هو مبين فى العقد أو مما هو ظاهر من طبيعة الشئ ، أو الغرض الذى اعد له ، ولضمن البائع هنا العيب ولو لم يكن عالما بوجوده. ( 2 ) ومع ذلك لا يضمن البائع العيوب التى كان المشترى يعرفها وقت البيع ، أو كان يستطيع أن يتبينها بنفسه لو انه فحص المبيع بعناية الرجل العادى ، الا إذا اثبت المشترى أن البائع قد أكد له خلو المبيع من هذا العيب ، أو اثبت أن البائع قد تعمد إخفاء العيب غشا منه."}, {"number": "448", "chapter": "الفصل الأول البيع", "text": "لا يضمن البائع عيبا جرى العرف على التسامح فيه."}, {"number": "449", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا تسلم المشترى المبيع. وجب عليه التحقق من حالته بمجرد أن يتمكن من ذلك ، وفقا للمألوف فى التعامل ، فاذا كشف عيبا يضمنه البائع وجب عليه أن يخطره به خلال مدة معقولة ، فإن لم يفعل اعتبر قابلا للمبيع. ( 2 ) اما إذا كان العيب مما لا يمكن الكشف عنه بالفحص المعتاد ثم كشفه المشترى أوجب عليه أن يخطر به البائع بمجرد ظهوره والا اعتبر قابلا للمبيع بما فيه من عيب."}, {"number": "450", "chapter": "الفصل الأول البيع", "text": "إذا أخطر المشترى البائع بالعيب فى الوقت الملائم كان له أن يرجع بالضمان على النحو المبين فى المادة 444."}, {"number": "451", "chapter": "الفصل الأول البيع", "text": "تبقى دعوى الضمان ولو هلك المبيع بأى سبب كان."}, {"number": "452", "chapter": "الفصل الأول البيع", "text": "( 1 ) تسقط بالتقادم دعوى الضمان إذا انقضت سنة من وقت تسليم المبيع ولو لم يكشف المشترى العيب الا بعد ذلك ما لم يقبل البائع أن يلتزم بالضمان لمدة أطول. ( 2 ) على انه لا يجوز للبائع أن يتمسك بالسنة لتمام التقادم إذا ثبت انه تعمد إخفاء العيب غشا منه."}, {"number": "453", "chapter": "الفصل الأول البيع", "text": "يجوز للمتعاقدين لاتفاق خاص أن يزيدا فى الضمان أو أن ينقصا منه أو أن يسقطا هذا الضمان ، على أن كل شرط يسقط الضمان أو ينقصه يقع باطلا إذا كان البائع قد تعمد إخفاء العيب فى المبيع غشا منه."}, {"number": "454", "chapter": "الفصل الأول البيع", "text": "لا ضمان للعيب فى البيوع القضائية ، ولا فى البيوع الإدارية إذا كانت بالمزاد."}, {"number": "455", "chapter": "الفصل الأول البيع", "text": "إذا ضمن البائع صلاحية المبيع للعمل مدة معلومة ثم ظهر خلل فى المبيع ، فعلى المشترى أن يخطر البائع بهذا الخلل فى مدة شهر من ظهوره وان يرفع الدعوى فى مدة ستة شهور من هذا الإخطار ، والا سقط حقه فى الضمان ، كل هذا ما لم يتفق على غيره. إلتزامات المشترى :"}, {"number": "456", "chapter": "الفصل الأول البيع", "text": "( 1 ) يكون الثمن مستحق الوفاء فى المكان الذى سلم فيه المبيع ما لم يوجد اتفاق أو عرف يقضى بغير ذلك. ( 2 ) فإذا لم يكن الثمن مستحقا وقت تسليم المبيع. وجب الوفاء به فى المكان الذى يوجد فيه موطن المشترى وقت إستحقاق الثمن."}, {"number": "457", "chapter": "الفصل الأول البيع", "text": "( 1 ) يكون الثمن مستحق الوفاء فى الوقت الذى يسلم فيه المبيع ما لم يوجد اتفاق أو عرف يقضى بغير ذلك ( 2 ) فإذا تعرض أحد للمشترى مستندا إلى حق سابق على البيع أو آيل من البائع ، أو إذا خيف على المبيع أن ينزع من يد المشترى ، جاز له ما لم يمنعه شرط فى العقد أن يحبس الثمن حتى ينقطع التعرض أو يزول الخطر. ومع ذلك يجوز للبائع فى هذه الحالة أن يطالب باستيفاء الثمن على أن يقدم كفيلا. ( 3 ) ويسرى حكم الفقرة السابقة فى حالة ما إذا كشف المشترى عيبا فى المبيع."}, {"number": "458", "chapter": "الفصل الأول البيع", "text": "( 1 ) لا حق للبائع فى الفرائد القانونية عن الثمن الا إذا اعذر المشترى أو إذا سلم الشئ المبيع وكان هذا الشئ قابلا أن ينتج ثمرات أو ايرادات اخرى ، هذا ما لم يوجد اتفاق أو عرف يقضى بغيره. ( 2 ) وللمشترى ثمر البيع ونماؤه من وقت تمام البيع ، وعليه تكاليف المبيع من هذا الوقت أيضا. هذا ما لم يوجد اتفاق أو عرف يقضى بغيره."}, {"number": "459", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا كان الثمن كله أو بعضه مستحق الدفع فى الحال فللبائع أن يحبس المبيع حتى يستوفى ما هو مستحق له ولو قدم المشترى رهنا أو كفالة. هذا ما لم يمنح البائع المشترى اجلا بعد البيع. ( 2 ) وكذلك يجوز للبائع أن يحبس المبيع ولو لم يحل الأجل المشترط لدفع الثمن إذا سقط حق المشترى فى الأجل طبقا لأحكام المادة 273."}, {"number": "460", "chapter": "الفصل الأول البيع", "text": "إذا هلك المبيع فى يد البائع وهو حابس له كان الهلاك على المشترى ما لم يكن المبيع قد هلك بفعل البائع."}, {"number": "461", "chapter": "الفصل الأول البيع", "text": "فى بيع العروض وغيرها من المنقولات إذا اتفق على ميعاد لدفع الثمن وتسلم المبيع يكون البيع مفسوخا دون حاجة إلى أعذار أن لم يدفع الثمن عند حلول الميعاد إذا اختار البائع ذلك ، وهذا ما لم يوجد اتفاق على غيره."}, {"number": "462", "chapter": "الفصل الأول البيع", "text": "نفقات عقد البيع ورسوم الدمغة ، والتسجيل وغير ذلك من مصروفات تكون على المشترى ما لم يوجد اتفاق أو عرف يقضى بغير ذلك."}, {"number": "463", "chapter": "الفصل الأول البيع", "text": "إذا لم يعين الاتفاق أو العرف مكانا أو زمانا لتسلم المبيع وجب على المشترى أن يتسلمه فى المكان الذى يوجد فيه المبيع وقت البيع وان ينقله دون إبطاء الا ما يقتضيه النقل من زمن."}, {"number": "464", "chapter": "الفصل الأول البيع", "text": "نفقات تسلم المبيع على المشترى ما لم يوجد عرف أو اتفاق يقضى بغير ذلك. 2 - بعض أنواع البيوع بيع الوفاء :"}, {"number": "465", "chapter": "الفصل الأول البيع", "text": "إذا احتفظ البائع عند البيع بحق استرداد المبيع خلال مدة معينة وقع البيع باطلا. بيع ملك الغير :"}, {"number": "466", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا باع شخص شيئا معينا بالذات وهو لا يملكه. جاز للمشترى أن يطلب إبطال البيع ، ويكون الأمر كذلك ولو وقع البيع على عقار ، سجل العقد أو لم يسجل. ( 2 ) وفى كل حال لا يسرى هذا البيع فى حق المالك للعين المبيعة ولو أجاز المشترى العقد."}, {"number": "467", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا أقر المالك البيع سرى العقد فى حقه وانقلب صحيحا فى حق المشترى. ( 2 ) وكذلك ينقلب العقد صحيحا فى حق المشترى إذا آلت ملكية المبيع إلى البائع بعد صدور العقد."}, {"number": "468", "chapter": "الفصل الأول البيع", "text": "إذا حكم للمشترى بإبطال البيع وكان يجهل أن المبيع غير مملوك للبائع. فله أن يطالب بتعويض ولو كان البائع حسن النية. بيع الحقوق المتنازع عليها :"}, {"number": "469", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا كان الحق المتنازع فيه قد نزل عنه صاحبه بمقابل إلى شخص آخر فللمتنازل ضده أن يتخلص من المطالبة إذا هو رد إلى المتنازل له الثمن الحقيقى الذى دفعه مع المصروفات وفوائد الثمن من وقت الدفع. ( 2 ) ويعتبر الحق متنازعا فيه إذا كان موضوعه قد رفعت به دعوى أو تام فى شأنه نزاع جدى."}, {"number": "470", "chapter": "الفصل الأول البيع", "text": "لا تسرى أحكام المادة السابقة فى الأحوال الآتية : ( أ ) إذا كان الحق المتنازع فيه داخلا ضمن مجموعة أموال بيعت جزافا كثمن واحد. ( ب ) إذا كان الحق المتنازع فيه ضائعا بين ورثة أو ملاك وباع أحدهم نصيبه للآخر. ( جـ ) إذا نزل المدين للدائن عن حق متنازع فيه وفاء للدين المستحق فى ذمته. ( د ) إذا كان الحق المتنازع فيه يثقل عقارا وبيع الحق لحائز العقار."}, {"number": "471", "chapter": "الفصل الأول البيع", "text": "لا يجوز للقضاة ولا لأعضاء النيابة ولا للمحامين ولا لكتبة المحاكم ولا للمحضرين أن يشتروا بأسمائهم ولا باسم مستعار الحق المتنازع فيه كله أو بعضه إذا كان النظر فى النزاع يدخل فى اختصاص المحكمة التى يباشرون أعمالهم فى دائرتها والا كان البيع باطلا."}, {"number": "472", "chapter": "الفصل الأول البيع", "text": "لا يجوز للمحامين أن يتعاملوا مع موكليهم فى الحقوق المتنازع فيها إذا كانوا هم الذين يتولون الدفاع عنها سواء أكان التعامل بأسمائهم أم باسم مستعار والا كان العقد باطلا. بيع التركة :"}, {"number": "473", "chapter": "الفصل الأول البيع", "text": "من باع تركة ، دون أن يفصل مشتملاتها ، لا يضمن الا ثبوت وراثته ما لم يتفق على غير ذلك."}, {"number": "474", "chapter": "الفصل الأول البيع", "text": "إذا بيعت تركة فلا يسرى البيع فى حق الغير الا إذا استوفى المشترى الإجراءات الواجبة لنقل كل حق اشتملت عليه التركة ، فإذا نص القانون على إجراءات لنقل الحق فيما بين المتعاقدين ، وجب أيضا أن تستوفى عدم الإجراءات."}, {"number": "475", "chapter": "الفصل الأول البيع", "text": "إذا كان البائع قد استوفى بعض ما للتركة من الديون أو باع شيئا مما اشتملت عليه ، وجب أن يرد للمشترى ما استولى عليه ما لم يكن عقد البيع قد اشترط صراحة عدم الرد."}, {"number": "476", "chapter": "الفصل الأول البيع", "text": "يرد المشترى للبائع ما وفاه هذا من ديون التركة ويحسب للبائع كل ما يكون دائنا به للتركة ما لم يوجد اتفاق يقضى بغير ذلك. البيع فى مرض الموت :"}, {"number": "477", "chapter": "الفصل الأول البيع", "text": "( 1 ) إذا باع المريض مرض الموت لوارث أو لغير وارث بثمن يقل عن قيمة المبيع وقت الموت فإن البيع يسرى فى حق الورثة إذا كانت زيادة قيمة المبيع على الثمن لا يجاوز ثلث التركة داخلا فيها المبيع ذاته. ( 2 ) اما إذا كانت هذه الزيادة تجاوز ثلث التركة فإن البيع فيما يجاوز الثلث لا يسرى فى حق الورثة الا إذا اقروه أو رد المشترى للتركة ما يفى بتكملة الثلثين. ( 3 ) ويسرى على بيع المريض مرض الموت أحكام المادة 916."}, {"number": "478", "chapter": "الفصل الأول البيع", "text": "لا تسرى أحكام المادة السابقة إضرارا بالغير حسن النية إذا كان هذا الغير قد كسب بعوض حقا عينيا على العين المبيعة. بيع النائب لنفسه :"}, {"number": "479", "chapter": "الفصل الأول البيع", "text": "لا يجوز لمن ينوب عن غيره بمقتضى اتفاق أو نص أو أمرمن السلطات المختصة أن يشترى بنفسه مباشرة أو باسم مستعار ولو بطريق المزاد العلنى ما نيط به بيعه بموجب هذه النيابة ما لم يكن ذلك بإذن القضاء ومع عدم الإخلال بما يكون منصوصا عليه فى قوانين اخرى."}, {"number": "480", "chapter": "الفصل الأول البيع", "text": "لا يجوز للسماسرة ولا للخبراء أن يشتروا الأموال المعهود إليهم فى بيعها أو فى تقدير قيمتها سواء أكان الشراء بأسمائهم أم باسم مستعار."}, {"number": "481", "chapter": "الفصل الأول البيع", "text": "يصح العقد فى الأحوال المنصوص عليها فى المادتين السابقتين إذا أجازه من تم البيع لحساب."}, {"number": "482", "chapter": "الفصل الثانى", "text": "المقايضة عقد به يلتزم كل دق المتعاقدين أن ينقل إلى الآخر ، على سبيل التبادل ،ملكية مال ليس من النقود."}, {"number": "483", "chapter": "الفصل الثانى", "text": "إذا كان للأشياء المتقايض فيها قيم مختلفة فى تقدير المتعاقدين ، جاز تعويض الفرق بمبلغ من النقود يكون معدلا."}, {"number": "484", "chapter": "الفصل الثانى", "text": "مصروفات عقد المقايضة وغيرها من النفقات الأخرى يتحملها المتقايضان مناصفة. ما لم يوجد اتفاق يقضى بغير ذلك."}, {"number": "485", "chapter": "الفصل الثانى", "text": "تسرى على المقايضة أحكام البيع ، بالقدر الذى تسمح به طبيعة المقايضة ، ويعتبر كل من المتقايضين بائعا للشئ الذى قايض به ومشتريا للشئ الذى قايض عليه."}, {"number": "486", "chapter": "الفصل الثالث", "text": "( 1 ) الهبة عقد يتصرف بمقتضاه الواهب فى مال له دون عوض. ( 2 ) ويجوز للواهب ، دون أن يتجرد عن نية التبرع ، أن يفرض على الموهوب له القيام بإلتزام معين."}, {"number": "487", "chapter": "الفصل الثالث", "text": "( 1 ) لا تتم الهبة الا إذا قبلها الموهوب له أو نائبه. ( 2 ) فإذا كان الواهب هو ولى الموهوب له أو وصيه ناب عنه فى قبول الهبة وقبض الشئ الموهوب."}, {"number": "488", "chapter": "الفصل الثالث", "text": "( 1 ) تكون الهبة بورقة رسمية ، والا وقعت باطلة ما لم تتم تحت ستار عقد آخر. ( 2 ) ومع ذلك يجوز فى المنقول أن تتم الهبة بالقبض ، دون حاجة إلى ورقة رسمية."}, {"number": "489", "chapter": "الفصل الثالث", "text": "إذا تام الواهب أو ورثته مختارين بتنفيذ هبة باطلة لعيب فى الشكل ، فلا يجوز لهم أن يستردوا ما سلموه."}, {"number": "490", "chapter": "الفصل الثالث", "text": "الوعد بالهبة لا ينعقد الا إذا كان بورقة رسمية."}, {"number": "491", "chapter": "الفصل الثالث", "text": "إذا وردت الهبة على شئ معين بالذات ، غير مملوك للواهب ، سرت عليها أحكام المادتين 466 و 467."}, {"number": "492", "chapter": "الفصل الثالث", "text": "تقع هبة الأموال المستقبلة باطلة. 2 - آثار الهبة"}, {"number": "493", "chapter": "الفصل الثالث", "text": "إذا لم يكن الموهوب له قد تسلم الشئ الموهوب ، فإن الواهب يلتزم بتسليمه اياه ، وتسرى فى ذلك الأحكام المتعلقة بتسليم المبيع."}, {"number": "494", "chapter": "الفصل الثالث", "text": "( 1 ) لا يضمن الواهب إستحقاق الشئ الموهوب ، الا إذا تعمد إخفاء سبب الإستحقاق أو كانت الهبة بعوض. وفى الحالة الأولى يقدر القاضى للموهوب له تعويضا عادلا عما أصابه من الضرر. وفى الحالة الثانية لا يضمن الواهب الإستحقاق الا بقدر ما أداه الموهوب له من عوض. كل هذا ما لم يتفق على غيره. ( 2 ) وإذا استحق الشئ الموهوب حل الموهوب له محل الواهب فيما له من حقوق ودعاوى."}, {"number": "495", "chapter": "الفصل الثالث", "text": "( 1 ) لا يضمن الواهب خلو الشئ الموهوب من العيب. ( 2 ) على انه إذا تعمد الواهب إخفاء العيب ، أو ضمن خلو الشئ الموهوب من العيوب ، كان ملزما بتعويض الموهوب له عن الضرر الذى يسببه العيب ، ويكون كذلك ملزما بالتعويض إذا كانت الهبة بعوض على الا يجاوز التعويض فى هذه الحالة قدر ما أداه الموهوب له من هذا التعويض."}, {"number": "496", "chapter": "الفصل الثالث", "text": "لا يكون الواهب مسئولا الا عن فعله العمد أو خطئه الجسيم."}, {"number": "497", "chapter": "الفصل الثالث", "text": "يلتزم الموهوب له بأداء ما اشترط عليه من عوض سواء اشترط هذا العوض لمصلحة الواهب أم لمصلحة أجنبى أم للمصلحة العامة."}, {"number": "498", "chapter": "الفصل الثالث", "text": "إذا تبين أن الشئ الموهوب أقل فى القيمة من العوض المشترط ، فلا يكون الموهوب له ملزما بأن يؤدى من هذا العوض الا بقدر قيمة الشئ الموهوب."}, {"number": "499", "chapter": "الفصل الثالث", "text": "( 1 ) إذا اشتر الواهب عوضا عن الهبة وفاء ديونه ، فلا يكون الموهوب له ملزما الا بوفاء الديون التى كانت موجودة وقت الهبة هذا ما لم يتفق على غير ( 2 ) وإذا كان الشئ الموهوب مثقلا بحق عينى ضمانا لدين فى ذمة الواهب ، أو فى ذمة شخص آخر ، فإن الموهوب له يلتزم بوفاء هذا الدين ، ما لم يوجد اتفاق على غير ذلك. 3 - الرجوع فى الهبة"}, {"number": "500", "chapter": "الفصل الثالث", "text": "( 1 ) يجوز للواهب أن يرجع فى الهبة إذا قبل الموهوب له ذلك. ( 2 ) فإذا لم بقبل الموهوب له جاز للواهب أن يطلب من القضاء الترخيص له فى الرجوع ، متى كان يستند فى ذلك إلى عذر مقبول ، ولم يوجد مانع من الرجوع."}, {"number": "501", "chapter": "الفصل الثالث", "text": "يعتبر بنوع خاص عذرا مقبولا للرجوع فى الهبة : ( أ ) أن يخل الموهوب له بما يجب عليه نحو الواهب ، أو نحو أحد من أقاربه ، بحيث يكون هذا الإخلال جحودا كبيرا من جانبه. ( ب ) أن بصبح الواهب عاجزا عن أن بوفر لنفسه أسباب المعيشة بما يتفق مع مكانته الاجتماعية ، أو أن يصبح غير قادر على الوفاء بما يفرضه عليه القانون من النفقة على الغير. ( جـ ) أن يرزق الواهب بعد الهبة ولدا يظل حيا إلى وقت الرجوع. أو أن يكون للواهب ولد يظنه ميتا وقت الهبة فإذا به حى."}, {"number": "502", "chapter": "الفصل الثالث", "text": "يرفض طلب الرجوع فى الهبة إذا وجد مانع من الموانع الآتية : ( أ ) إذا حصل للشئ الموهوب زيادة متصلة موجبة لزيادة قيمته فإذا زال المانع عاد حق الرجوع. ( ب ) إذا مات أحد طرفى عقد الهبة. ( جـ ) إذا تصرف الموهوب له فى الشئ الموهوب تصرفا نهائيا ، فإذا اقتصر التصرف على بعض الموهوب ، جاز للواهب أن يرجع فى الباقى. ( د ) إذا كانت الهبة من أحد الزوجين للآخر ولو اراد الواهب الرجوع بعد انقضاء الزوجية. ( هـ ) إذا كانت الهبة لذى رحم محرم. ( و ) إذا هلك الشئ الموهوب فى يد الموهوب له ، سواء كان الهلاك بفعله أو بحادث أجنبى لا يد له فيه أو بسبب الاستعمال ، فإذا لم يهلك الا بعض الشئ ، جاز الرجوع فى الباقى. ( ز ) إذا قدم الموهوب له عوضا عن الهبة. ( ح ) إذا كانت الهبة صدقة أو عملا من أعمال البر."}, {"number": "503", "chapter": "الفصل الثالث", "text": "( 1 ) يترتب على الرجوع فى الهبة بالتراضى أو بالتقاضى أن تعتبر الهبة كان لم تكن. ( 2 ) ولا يرد الموهوب له الثمرات الا من وقت الاتفاق على الرجوع ، أو من وقت رفع الدعوى ، وله أن يرجع بجميع ما أنفقه من مصروفات ضرورية ، اما المصروفات النافعة فلا يجاوز فى الرجوع بها القدر الذى زاد فى قيمة الشئ الموهوب."}, {"number": "504", "chapter": "الفصل الثالث", "text": "( 1 ) إذا استولى الواهب على الشئ الموهوب ، بغير التراضى أو التقاضى ، كان مسئولا قبل الموهوب له عن هلاك الشئ سواء كان الهلاك بفعل الواهب أو بسبب أجنبى لا يد اله فيه أو بسبب الاستعمال. ( 2 ) اما إذا صدر حكم بالرجوع فى الهبة وملك الشئ فى يد الموهوب له بعد اعذاره بالتسليم ، فيكون الموهوب له مسئولا عن هنا الهلاك ، ولو كان الهلاك بسبب أجنبى."}, {"number": "505", "chapter": "الفصل الرابع الشركة", "text": "الشركة عقد بمقتضاه يلتزم شخصان أو أكثر بأن يساهم كل منهم فى مشروع مالى ، بتقديم حصة من مال أو من عمل ، لاقتسام ما قد ينشأ عن هذا المشروع من ربح أو من خسارة"}, {"number": "506", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تعتبر الشركة بمجرد تكوينها شخصا إعتبار لا ولكن لا يحتج لهذه الشخصية على الغير الا بعد استيفاء إجراءات النشر التى يقررها القانون. ( 2 ) ومع ذلك للغير إذا لم تقم الشركة بإجراءات النشر المقررة أن يتمسك بشخصيتها. 1 – أركان الشركة"}, {"number": "507", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) يجب أن يكون عقد الشركة مكتوبا والا كان باطلا. وكذلك يكون باطلا كل ما يدخل على العقد من تعديلات دون أن تستوفى الشكل الذى افرغ فيه ذلك العقد. ( 2 ) غير أن هذا البطلان لا يجوز أن يحتج به الشركاء قبل الغير. ولا يكون له أثر فيما بين الشركاء أنفسهم ، الا من وقت أن يطلب الشريك الحكم بالبطلان."}, {"number": "508", "chapter": "الفصل الرابع الشركة", "text": "تعتبر حصص الشركاء متساوية القيمة ، وانها واردة على ملكية المال لا على مجرد الانتفاع به ، ما لم يوجد اتفاق أو عرف يقضى بغير ذلك."}, {"number": "509", "chapter": "الفصل الرابع الشركة", "text": "لا يجوز أن تقتصر حصة الشريك على ما يكون له من نفوذ ، أو على ما يتمتع به من ثقة مالية."}, {"number": "510", "chapter": "الفصل الرابع الشركة", "text": "إذا تعهد الشريك بأن يقدم حصته فى الشركة مبلغا من النقود ، ولم يقدم هذا المبلغ لزمته فوائده من وقت استحقاقه من غير حاجة إلى مطالبة قضائية أو اعذاره وذلك دون إخلال بما قد يستحق من تعويض تكميلى عند الاقتضاء."}, {"number": "511", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا كانت حصة الشريك حق ملكية أو حق منفعة أو أى حق عينى آخر ، فإن أحكام البيع هى التى تسرى فى ضمان الحصة إذا هلكت ، أو استحقت ، أو ظهر فيها عيب أو نقص. ( 2 ) اما إذا كانت الحصة مجرد الانتفاع بالمال ، فإن أحكام الإيجار هى التى تسرى فى كل ذلك."}, {"number": "512", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا تعهد الشريك بأن يقدم حصته فى الشركة عملا وجب عليه أن يقوم بالخدمات التى تعهد بها ، وان يقدم حسابا عما يكون قد كسبه من وقت قيام الشركة بمزاولته العمل الذى قدمه حصة له. ( 2 ) على انه لا يكون ملزما بأن يظم للشركة ما يكون قد حصل عليه من حق اختراع ، الا إذا وجد اتفاق يقضى بغير ذلك."}, {"number": "513", "chapter": "الفصل الرابع الشركة", "text": "إذا كانت الحصة التى قدمها الشريك هى ديون له فى ذمة الغير ، فلا ينقضى التزامه للشركة الا إذا استوفيت هذه الديون. ويكون الشريك فوق ذلك مسئولا عن تعويض الضرر إذا لم توف الديون عند حلول اجلها."}, {"number": "514", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا لم يبين عقد الشركة نصيب كل من الشركاء فى الأرباح والخسائر ، كان نصيب كل منهم فى ذلك بنسبة حصته فى رأس المال. ( 2 ) فإذا اقتصر العقد على تعيين نصيب الشركاء فى الربح وجب إعتبار هذا النصيب فى الخسارة أيضا ، وكذلك الحال إذا اقتصر العقد على تعيين النصيب فى الخسارة ( 3 ) وإذا كانت حصة أحد الشركاء مقصورة على عمله ، وجب أن يقدر نصيبه فى الربح والخسارة تبعا لما تفيده الشركة من هذا العمل فإذا قدم فوق عمله نقودا أو أى شئ أضر كان له نصيب عن العمل وآخر عما قدمه فوقه."}, {"number": "515", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا اتفق على أن أحد الشركاء لا يساهم فى أرباح الشركة أو فى خسائرها ، كان عقد الشركة باطلا. ( 2 ) ويجوز الاتفاق على إعفاء الشريك الذى لم يقدم غير عمله فى المساهمة فى الخسائر ، بشرط الا يكون قد تقرر له أجر عن عمله. 2 - إدارة الشركة"}, {"number": "516", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) للشريك المنتدب للإدارة بنص خاص فى عقد الشركة أن يقوم بالرغم من معارضة سائر الشركاء بأعمال الادارة بالتصرفات التى تدخل فى غرض الشركة ، متى كانت أعماله وتصرفاته خالية من الغش. ولا يجوز عزل هذا الشريك من الإدارة دون مسوغ ، مادامت الشركة باقية. ( 2 ) واذا كان انتداب الشريك للادارة لاحقا لعقد الشركة ، جاز الرجوع فيه كما يجوز فى التوكيل العادى. ( 3 ) اما المديرون من غير الشركاء فهم دائما قابلون للعزل."}, {"number": "517", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا تعدد الشركاء المنتدبون للادارة دون أن يعين اختصاص كل منهم ودون أن ينص على عدم جواز انفراد أى منهم بالإدارة كان لكل منهم أن يقوم منفردا بأى عمل من أعمال الادارة على أن يكون لكل من باقى الشركاء المنتدبين أن يعترض على العمل قبل إتمامه ، وعلى أن يكون من حق أغلبية الشركاء المنتدبين رفض هذا الاعتراض فإذا تسارى الجانبان كان الرفض من حق أغلبية الشركاء جميعا. ( 2 ) اما إذا اتفق على أن تكون قرارات الشركاء المنتدبين بالإجماع أو بالأغلبية ، فلا يجوز الخروج على ذلك ، الا أن يكون لأمر عاجل يترتب على تفويته خسارة جسيمة لا تستطيع الشركة تعويضها."}, {"number": "518", "chapter": "الفصل الرابع الشركة", "text": "إذا وجب أن يصدر قرار بالأغلبية ، تعين الأخذ بالأغلبية العددية ما لم يتفق على غير ذلك."}, {"number": "519", "chapter": "الفصل الرابع الشركة", "text": "الشركاء غير المديرين ممنوعون من الإدارة ولكن يجوز لهم أن يطلعوا بأنفسهم على دفاتر الشركة ومستنداتها ، وكل اتفاق على غير ذلك باطل."}, {"number": "520", "chapter": "الفصل الرابع الشركة", "text": "إذا لم يوجد نص خاص على طريقة الإدارة ، اعتبر كل شربك مفوضا من الآخرين فى إدارة الشركة ، وكان له أن يباشر أعمال الشركة دون رجوع إلى غيره من الشركاء على أن يكون لهؤلاء أو لأى منهم حق الاعتراض على أى عمل قبل تمامه ، ولأغلبية الشركاء الحق فى رفض هذا الاعتراض. 3 - آثار الشركة"}, {"number": "521", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) على الشريك أن يمتنع عن أى نشاط يلحق الضرر بالشركة ، أو يكون مخالفا للغرض الذى أنشئت لتحقيقه. ( 2 ) وعليه أن يبذل من العناية فى تدبير مصالح الشركة ما يبذله فى تدبير مصالحه الخاصة ، الا إذا كان منتدبا للادارة بأجر فلا يجوز أن ينزل فى ذلك عن عناية الرجل المعتاد."}, {"number": "522", "chapter": "الفصل الرابع الشركة", "text": "إذا أخذ الشريك أو احتجز مبلغا من مال الشركة ، لزمته فوائد هذا المبلغ من يوم أخذه أو احتجازه ، بغير حاجة إلى مطالبة قضائية أو أعذار وذلك دون إخلال بما قد يستحق للشركة من تعويض تكميلى عند الاقتضاء. ( 2 ) وإذا أمد الشريك الشركة من ماله ، أو انفق فى مصلحتها شيئا من المصروفات النافعة عن حسن نية وتبصر ، وجبت له على الشركة فوائد هذه المبالغ من يوم دفعها."}, {"number": "523", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) إذا لم تف أموال الشركة بديونها ، كان الشركاء مسئولين عن هذه الديون فى أموالهم الخاصة ، كل منهم بنسبة نصيبه فى خسائر الشركة ، ما لم يوجد اتفاق على نسبة اخرى. ويكون باطلا كل اتفاق يعفى الشريك من المسئولية عن ديون الشركة. ( 2 ) وفى كل حال يكون لدائنى الشركة حق مطالبة الشركاء كل بقدر الحصة التى تخصصت له فى أرياح الشركة."}, {"number": "524", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) لا تضامن بين الشركاء فيما يلزم كلا منهم من ديون الشركة ، ما لم يتفق على خلاف ذلك. ( 2 ) غير انه إذا اعسر أحد الشركاء ، وزعت حصته فى الدين على الباقين ، كل بقدر نصيبه فى تحمل الخسارة."}, {"number": "525", "chapter": "الفصل الرابع الشركة", "text": "إذا كان لأحد الشركاء دائنون شخصيون ، فليس لهم اثناء قيام الشركة أن يتقاضوا حقوقهم مما يخص ذلك الشريك فى رأس المال. وإنما لهم أن يتقاضوها مما يخصه فى الأرباح ، اما بعد تصفية الشركة فيكون لهم أن يتقاضوا حقوقهم من نصيب مدينهم فى أموال الشركة بعد استنزال ديونها. ومع ذلك يجوز لهم قبل التصفية توقيع الحجز التحفظى على نصيب هذا المدين. 4 – طرق انقضاء الشركة"}, {"number": "526", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تنتهى الشركة بإنقضاء الميعاد المعين لها ، أو بانتهاء العمل الذى قامت من اجله. ( 2 ) فإذا انقضت المدة المعينة أو انتهى العمل ثم استمر الشركاء يقومون بعمل من نوع الأعمال التى تألفت لها الشركة امتد العقد سنة فسنة بالشروط ذاتها. ( 3 ) ويجوز لدائن أحد الشركاء أن يعترض على هذا الامتداد ويترتب على اعتراضه وقف أثره فى حقه."}, {"number": "527", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تنتهى الشركة بهلاك جميع مالها أو جزء كبير منه بحيث لا تبقى فائدة فى استمرارها. ( 2 ) وإذا كان أحد الشركاء قد تعهد بأن يقدم حصته شيئا معينا بالذات وهلك هذا الشئ قبل تقديمه ، أصبحت الشركة منحلة فى حق جميع الشركاء."}, {"number": "528", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تنتهى الشركة بموت أحد الشركاء أو بالحجر عليه أو بإعساره أو بإفلاسه. ( 2 ) ومع ذلك يجوز الاتفاق على انه إذا مات أحد الشركاء تستمر الشركة مع ورثته. ولو كانوا قصرا ( 3 ) ويجوز أيضا الاتفاق على انه إذا مات أحد الشركاء أو حجر عليه أو اعصر أو أفلس أو انسحب وفقا لأحكام المادة التالية. تستمر الشركة فيما بين الباقين من الشركاء ، وفى هذه الحالة لا يكون لهذا الشريك أو ورثته الا نصيبه فى أموال الشركة ، ويقدر هذا النصيب بحسب قيمته يوم وقوع الحادث الذى أدى إلى خروجه من الشركة ويدفع له نقدا. ولا يكون له نصيب فيما يستجد بعد ذلك من حقوق. الا بقدر ما تكون تلك الحقوق ناتجة من عمليات سابقة على ذلك الحادث."}, {"number": "529", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تنتهى الشركة بانسحاب أحد الشركاء ، إذا كانت مدتها غير معينة. على أن يعلن الشريك إرادته فى الانسحاب إلى سائر الشركاء قبل حصوله ، والا يكون انسحابه عن غش أو فى وقت غير لائق. ( 2 ) وتنتهى أيضا بإجماع الشركاء على حلها."}, {"number": "530", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) يجوز للمحكمة أن تقضى بحل الشركة بناء على طلب أحد الشركاء. لعدم وفاء الشريك بما تعهد به أو لأى سبب أضر لا يرجع إلى الشركاء ، ويقدر القاضى ما ينطوى عليه هذا السبب من خطورة تسوغ الحل. ( 2 ) ويكون باطلا كل اتفاق يقضى بغير ذلك."}, {"number": "531", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) يجوز لكل شريك أن يطلب من القضاء الحكم بفصل أى من الشركاء يكون وجوده فى الشركة قد آثار اعتراضا على مد اجلها أو تكون تصرفاته مما يمكن اعتباره سببا مسوغا لحل الشركة ، على أن تظل الشركة قائمة فيما بين الباقين. ( 2 ) ويجوز أيضا لأى شريك إذا كانت الشركة معينة المدة أن يطلب من القضاء إخراجه من الشركة متى استند فى ذلك إلى أسباب معقولة ، وفى هذه الحالة تنحل الشركة ما لم يتفق باقى الشركاء على استمرارها. 5 - تصفية الشركة وقسمتها"}, {"number": "532", "chapter": "الفصل الرابع الشركة", "text": "تتم تصفية أموال الشركة وقسمتها بالطريقة المبينة فى العقد. وعند خلوه من حكم خاص تتبع الأحكام الآتية :"}, {"number": "533", "chapter": "الفصل الرابع الشركة", "text": "تنتهى عند حل الشركة سلطة المديرين. اما شخصية الشركة فتبقى بالقدر اللازم للتصفية وإلى أن تنتهى هذه التصفية."}, {"number": "534", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) يقوم بالتصفية عند الاقتضاء ، اما جميع الشركاء ، واما مصف واحد أو أكثر تعينهم أغلبية الشركاء. ( 2 ) وإذا لم يتفق الشركاء على تعيين المصفى ، تولى القاضى تعيينه ، بناء على طلب أحدهم. ( 3 ) وفى الحالات التى تكون فيها الشركة باطلة تعين المحكمة المصفى ، وتحدد طريقة التصفية ، بناه على طلب كل ذى شأن. ( 4 ) وحتى يتم تعيا المصفى يعتبر المديرون بالنسبة إلى الغير فى حكم المصفين."}, {"number": "535", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) ليس للمصفى أن يبدأ أعمالا جديدة للشركة ، الا أن تكون لازمة لإتمام أعمال سابقة. ( 2 ) ويجوز له أن يبيع مال الشركة منقولا أو عقارا اما بالمزاد ، واما بالممارسة ، ما لم ينص فى أمرتعيينه على تقييد هذه السلطة."}, {"number": "536", "chapter": "الفصل الرابع الشركة", "text": "( 1 ) تقسم أموال الشركة بين الشركاء جميعا وذلك بعد استيفاء الدائنين لحقوقهم ، وبعد استنزال المبالغ اللازمة لوفاء الديون التى لم تحل أو الديون المتنازع فيها وبعد رد المصروفات أو القروض التى يكون أحد الشركاء قد باشرها فى مصلحة الشركة. ( 2 ) ويختص كل واحد من الشركاء بمبلغ يعادل قيمة الحصة التى قدمها فى رأس المال. كما هى مبينة فى العقد أو بما يعادل قيمة هذه الحصة وقت تسليمها إذا لم تبين قيمتها فى العقد ، ما لم يكن الشريك قد اقتصر على تقديم عمله أو اقتصر فيما قدمه من شئ على حق المنفعة فيه أو على مجرد الانتفاع به. ( 3 ) وإذا بقى شئ بعد ذلك وجبت قسمته بين الشركاء بنسبة نصيب كل منهم فى الأرباح. ( 4 ) اما اذا لم يكف صافى مال الشركة للوفاء بحصص الشركاء ، فإن الخسارة توزع عليهم جميعا بحسب النسبة المتفق عليها فى توزيع الخسائر."}, {"number": "537", "chapter": "الفصل الرابع الشركة", "text": "تتبع فى قسمة الشركات القواعد المتعلقة بقسمة المال الشائع."}, {"number": "538", "chapter": "الفصل الخامس", "text": "القرض عقد يلتزم به المقرض أن ينقل إلى المقترض ملكية مبلغ من النقود أو أى شئ مثلى آخر. على أن يرد إليه المقترض عند نهاية القرض شيئا مثله فى مقداره ونوعه وصفته."}, {"number": "539", "chapter": "الفصل الخامس", "text": "يجب على المقرض أن يسلم الشئ موضوع القد إلى المقترض ، ولا يجوز له أن يطالبه برد المثل الا عند انتهاء القرض. ( 2 ) وإذا هلك الشئ قبل تسليمه إلى المقترض كان الهلاك على المقرض."}, {"number": "540", "chapter": "الفصل الخامس", "text": "إذا استحق الشئ ، فإن كان القرض بأجر سرت أحكام البيع ، والا فأحكام العارية."}, {"number": "541", "chapter": "الفصل الخامس", "text": "( 1 ) إذا ظهر فى الشئ عيب خفى وكان القرض بغير أجر واختار المقترض استيفاء الشئ. فلا يلزمه أن يرد الا قيمة الشئ معيبا. ( 2 ) اما إذا كان القرض بأجر أو كان بغير أجر ولكن المقرض قد تعمد إخفاء العيب ، فيكون للمقترض أن يطلب اما إصلاح العيب ، واما استبدال شئ سليم بالشئ المعيب."}, {"number": "542", "chapter": "الفصل الخامس", "text": "على المقترض أن يدفع الفوائد المتفق عليها عند حلول مواعيد استحقاقها. فإذا لم يكن هناك اتفاق على فوائد اعتبر القرض بغير أجر."}, {"number": "543", "chapter": "الفصل الخامس", "text": "ينتهى القرض بانتهاء الميعاد المتفق عليه."}, {"number": "544", "chapter": "الفصل الخامس", "text": "إذا اتفق على الفوائد ، كان للمدين إذا انقضت ستة اشهر على القرض أن يعلن رغبته فى إلغاء العقد ورد ما اقترضه ، على أن يتم الرد فى أجل لا يجاوز ستة اشهر من تاريخ هذا الإعلان ، وفى هذه الحالة يلزم المدين بأداء الفوائد المستحقة عن ستة اشهر التالية للإعلان ، ولا يجوز بوجه من الوجوه إلزامه بأن يؤدى فائدة أو مقابلا من أى نوع بسبب تعجيل الوفاء ، ولا يجوز الاتفاق على إسقاط حق المقترض فى الرد أو الحد منه. 2 - الدخل الدائم"}, {"number": "545", "chapter": "الفصل الخامس", "text": "( 1 ) يجوز أن يتعهد شخص بأن يؤدى على الدوام إلى شخص آخر وإلى خلفائه من بعده دخلا دوريا يكون مبلغا من النقود أو مقدارا معينا من أشياء مثلية اخرى. ويكون هذا التعهد بعقد من عقود المعاوضة أو التبرع أو بطريق الوصية. ( 2 ) فإذا كان ترتيب الدخل بعقد من عقود المعاوضة ، اتبع فى شأنه من حيث سعر الفائدة القواعد التى تسرى على القرض ذى الفائدة."}, {"number": "546", "chapter": "الفصل الخامس", "text": "( 1 ) يشترط فى الدخل الدائم أن يكون قابلا للاستبدال فى أى وقت شاء المدين. ويقع باطلا كل اتفاق يقضى بغير ذلك. ( 2 ) غير انه يجوز الاتفاق على الا يحصل الاستبدال مادام مستحق الدخل حيا ، أو على الا يحصل قبل انقضاء مدة لا يجوز أن تزيد على خمس عشرة سنة. ( 3 ) وفى كل حال لا يجوز استعمال حق الاستبدال الا بعد إعلان الرغبة فى ذلك ، وانقضاء سنة على هذا الإعلان."}, {"number": "547", "chapter": "الفصل الخامس", "text": "يجبر المدين على الاستبدال فى الأحوال الآتية : ( أ ) إذا لم يدفع الدخل سنتين متواليتين ، رغم اعذاره. ( ب ) إذا قصر فى تقديم ما وعد به الدائن من تأمينات أو إذا أنعدمت التأمينات ولم يقدم بديلا عنها. ( جـ ) إذا أفلس أو اعسر."}, {"number": "548", "chapter": "الفصل الخامس", "text": "( 1 ) إذا رتب الدخل مقابل مبلغ من النقود تم الاستبدال برد المبلغ بتمامه ، أو برد مبلغ أقل منه إذا اتفق على ذلك. ( 2 ) وفى الحالات الأخرى يتم الاستبدال بدفع مبلغ من النقود تكون فائدته محسوبة بالسعر القانونى مساوية للدخل."}, {"number": "549", "chapter": "الفصل السادس", "text": "الصلح عقد بحسم به الطرفان نزاعا قائما أو يتوقيان به نزاعا محتملا ، وذلك بأن ينزل كل منهما على وجه التقابل عن جزء من ادعائه."}, {"number": "550", "chapter": "الفصل السادس", "text": "يشترط فيمن يعقد صلحا أن يكون أهلا للتصرف يعوض فى الحقوق التى يشملها عقد الصلح."}, {"number": "551", "chapter": "الفصل السادس", "text": "لا يجوز الصلح فى المسائل المتعلقة بالحالة الشخصية أو بالنظام العام. ولكن يجوز الصلح على المصالح المالية التى تترتب على الحالة الشخصية ، أو التى تنشأ عن ارتكاب احدى الجرائم."}, {"number": "552", "chapter": "الفصل السادس", "text": "لا يثبت الصلح الا بالكتابة أو بمحضر رسمى. 2 - آثار الصلح"}, {"number": "553", "chapter": "الفصل السادس", "text": "( 1 ) تنحسم بالصلح المنازعات التى تناولها. ( 2 ) ويترتب عليه انقضاء الحقوق والإدعاءات التى نزل عنها أى من المتعاقدين نزولا نهائيا."}, {"number": "554", "chapter": "الفصل السادس", "text": "للصلع أثر كاشف بالنسبة إلى ماتناوله من الحقوق ويقتصر هنا الأثر على الحقوق المتنازع فيها دون غيرها."}, {"number": "555", "chapter": "الفصل السادس", "text": "يجب أن تفسر عبارات التنازل التى يتضمنها الصلح تفسيرا ضيقا ، وأيا كانت تلك العبارات فإن التنازل لا ينصب الا على الحقوق التى كانت وحدها بصفة جلية محلا للنزاع الذى حسمه الصلح. 3 - بطلان الصلح."}, {"number": "556", "chapter": "الفصل السادس", "text": "لا يجوز الطعن فى الصلع بسبب غلط فى القانون."}, {"number": "557", "chapter": "الفصل السادس", "text": "( 1 ) الصلح لا يتجزأ ، فبطلان جزء منه يقتضى بطلان العقد كله. ( 2 ) على أن هذا الحكم لا يسرى إذا تبين من عبارات العقد ، أو من الظروف ، أن المتعاقدين قد اتفقا على أن أجزاء العقد مستقلة بعضها عن بعض."}, {"number": "558", "chapter": "الفصل الأول", "text": "الايجار عقد يلتزم المؤجر بمقتضاه أن يمكن المستأجر من الانتفاع بشىء معين عدة معينه لقاء أجر معلوم."}, {"number": "559", "chapter": "الفصل الأول", "text": "لا يجوز لمن لا يملك الا حق الإدارة أن يعقد إيجارا تزيد مدته على ثلاث سنوات الا بترخيص من السلطة المختصة ، فإذا كان عقد الإيجار لمدة أطول من ذلك أنقضت المدة إلى ثلاث سنوات كل هذا ما لم يوجد نص يقضى بغيره."}, {"number": "560", "chapter": "الفصل الأول", "text": "الاجارة الصادرة ممن له حق المنفعة تنقضى بإنقضاء هذا الحق اذا لم يجزها مالك الرقبة ، على أن تراعى المواعيد المقررة للتنبيه بالإخلاء والمواعيد اللازمة لنقل محصول السنة."}, {"number": "561", "chapter": "الفصل الأول", "text": "يجوز أن تكون الأجرة نقودا كما يجوز أن تكون أى تقدمه اخرى."}, {"number": "562", "chapter": "الفصل الأول", "text": "إذا لم يتفق المتعاقدان على مقدار الأجرة أو على كيفية تقديرها ، أو إذا تعذر إثبات مقدار الأجرة وجب اعتبار أجرة المثل."}, {"number": "563", "chapter": "الفصل الأول", "text": "إذا عقد الإيجار دون اتفاق على مدة أو عقد لمدة غير معينة أو تعذر إثبات المدة المدعاه اعتبر الإيجار منعقدا للفترة المعينة لدفع الأجرة ، وينتهى بإنقضاء هذه الفترة بناء على طلب أحد المتعاقدين إذا هو نبه على المتعاقد الآخر بالإخلاء فى المواعيد الآتى بيانها : ( أ ) فى الأراضى الزراعية والأراضى البور إذا كانت المدة المعينة لدفع الأجرة ستة اشهر أو أكثر. يكون التنبيه قبل انتهائها بثلاثة اشهر ، فإذا كانت المدة أقل من ذلك ، وجب التنبيه. قبل نصفها الأخير ، كل هذا مع مراعاة حق المستأجر فى المحصول وفقا للعرف. ( ب ) فى المنازل والحوانيت والمكاتب والمتاجر والمصانع والمخازن وما الى ذلك إذا كانت الفترة المعينة لدفع الأجرة أربعة اشهر أو أكثر وجب التنبيه قبل انتهائها بشهرين ، فإذا كانت الفترة أقل من ذلك وجب التنبيه قبل نصفها الأخير. ( جـ ) فى المساكن والغرف المؤثثة وفى أى شئ غير ما تقدم إذا كانت الفترة المعينة لدفع الأجرة شهرين أو أكثر ، وجب التنبيه قبل نهايتها بشهر فإذا كانت أقل من ذلك ، وجب التنبيه قبل نصفها الأخير. ثاني -آثار الإيجار :"}, {"number": "564", "chapter": "الفصل الأول", "text": "يلتزم المؤجر أن يسلم المستأجر العين المؤجرة وملحقاتها فى حالة تصلح معها لأن تفى بما أعدت له من المنفعة ، وفقا لما تم عليه الاتفاق أو لطبيعة العين."}, {"number": "565", "chapter": "الفصل الأول", "text": "( 1 ) إذا سلمت العين المؤجرة فى صالة لا تكون فيها صالحة للانتفاع الذى أوجرت من اجله أو إذا نقص هنا الانتفاع نقصا كبيرا ، جاز للمستأجر أن يطلب فسخ العقد أو إنقاص الأجرة بقدر ما نقص من الانتفاع مع التعويض فى الحالتين إذا كان لذلك مقتض. ( 2 ) فإذا كانت العين المؤجرة فى حالة من شأنها أن تعرض صحة المستأجر أو من يعيشون معه أو مستخدميه أو عماله لخطر جسيم ، جاز للمستأجر أن يطلب فسخ العقد ، ولو كان قد سبق له أن نزل عن هذا الحق."}, {"number": "566", "chapter": "الفصل الأول", "text": "يسرى على الالتزام بتسليم العين المؤجرة ما يسرى على الإلتزام بتسليم العين المبيعة من أحكام ، وعلى الأخص ما يتعلق منها بزمان التسليم ومكانه وتحديد مقدار العين المؤجرة وتحديد ملحقاتها."}, {"number": "567", "chapter": "الفصل الأول", "text": "( 1 ) على المؤجر أن يتعهد العين المؤجرة بالصيانة لتبقى على الحالة التى سلمت بها وان يقوم فى اثناء الاجارة بجميع الترميمات الضرورية دون الترميمات \" التأجيرية \". ( 2 ) وعليه أن يجرى الأعمال اللازمة للأسطح من تجصيص أو بياض وان يقوم بنزح الآبار والمراحيض ومصارف المياه. ( 3 ) ويتحمل المؤجر التكاليف والضرائب المستحقة على العين المؤجرة ويلزم بثمن المياه إذا قدر جزافا. فإذا كان تقديره \" بالعداد \" كان على المستأجر. اما ثمن الكهرباء والغاز وغير ذلك مما هو خاص بالاستعمال الشخصى فيتحمله المستأجر. ( 4 ) كل هذا ما لم يقض الاتفاق بغيره."}, {"number": "568", "chapter": "الفصل الأول", "text": "( 1 ) إذا تأخر المؤجر بعد اعذاره عن القيام بتنفيذ الإلتزامات المبينة فى المادة السابقة ، جاز للمستأجر أن يحصل على ترخيص من القضاء فى أجراء ذلك بنفسه وفى استيفاء ما انفقه خصما من الأجرة. وهذا دون إخلال بحقه فى طلب الفسخ أو إنقاص الأجرة ( 2 ) ويجوز للمستأجر دون حاجة إلى ترخيص من القضاء أن يقوم بإجراء الترميمات المستعجلة أو الترميمات البسيطة مما يلتزم به المؤجر ، سواء كان العيب موجودا وقت بدء الانتفاع أو طرأ بعد ذلك إذا لم يقم المؤجر بعد اعذاره بتنفيذ هذا الإلتزام فى ميعاد مناسب ، على أن يستوفى المستأجر ما انفقه خصما من الأجرة."}, {"number": "569", "chapter": "الفصل الأول", "text": "( 1 ) إذا هلكت العين المؤجرة اثناء الإيجار هلاكا كليا انفسخ العقد من تلقاء نفسه. ( 2 ) اما إذا كان هلاك العين جزئيا ، أو إذا أصبحت العين فى حالة لا تصلح معها للانتفاع الذى أوجرت من اجله ، أو نقص هذا الانتفاع نقصا كبيرا ولم يكن للمستأجر يد فى شئ من ذلك ، فيجوز له ، اذا لم يقم المؤجر فى ميعاد مناسب بإعادة العين إلى الحالة التى كانت عليها أن يطلب تبعا للظروف اما إنقاص الأجرة أو فسخ الإيجار ذاته دون. إخلال بما له من حق فى أن يقوم بنفسه بتنفيذ إلتزام المؤجر وفقا لأحكام المادة السابقة. ( 3 ) ولا يجوز للمستأجر فى الحالتين السابقتين أن يطلب تعويضا إذا كان الهلاك أو التلف يرجع إلى سبب لا يد للمؤجر فيه."}, {"number": "570", "chapter": "الفصل الأول", "text": "( 1 ) لا يجوز للمستأجر أن يمنع المؤجر من أجراء الترميمات المستعجلة التى تكون ضرورية لحفظ العين المؤجرة على انه إذا ترتب أعلى هذه الترميمات إخلالا كلى أو جزئى بالانتفاع بالعين ، جاز للمستأجر أن يطلب تبعا للظروف اما فسخ الإيجار أو إنقاص الأجرة ( 2 ) ومع ذلك إذا بقى المستأجر فى العين المؤجرة إلى أن تتم الترميمات ، سقط حقه فى طلب الفسخ."}, {"number": "571", "chapter": "الفصل الأول", "text": "( 1 ) على المؤجر أن يمتنع عن كل ما من شأنه أن يحول دون انتفاع المستأجر بالعين المؤجرة ولا يجوز له أن يحدث بالعين أو ملحقاتها أى تغيير يخل بهذا الانتفاع. ( 3 ) ولا يقتصر ضمان المؤجر على الأعمال التى تصدر منه أو من اتباعه ، بل يمتد هذا الضمان إلى كل تعرض أو إضرار مبنى على سبب قانونى يصدر من أى مستأجر آخر أو من أى شخص تلقى الحق عن المؤجر."}, {"number": "572", "chapter": "الفصل الأول", "text": "( 1 ) إذا ادعى أجنبى حقا يتعارض مع ما للمستأجر من حقوق بمقتضى عقد الإيجار ، وجب على المستأجر أن يبادر بإخطار المؤجر بذلك وكان له أن يخرج من الدعوى ، وفى هذه الحالة لا توجه الإجراءات الا إلى المؤجر. ( 2 ) فإذا ترتب على هذا الإدعاء أن حرم المستأجر فعلا من الانتفاع الذى له بموجب عقد الإيجار ، جاز له تبعا للظروف أن يطلب الفسخ أو إنقاص الأجرة مع التعويض أن كان له مقتض."}, {"number": "573", "chapter": "الفصل الأول", "text": "( 1 ) إذا تعدد المستأجرون لعين واحدة فضل من سبق منهم إلى وضع يده عليها دون غش ، فإذا كان مستأجر عقار قد سجل عقده وهو حسن النية قبل أن يضع مستأجر آخر يده على العقار المؤجر أو قبل أن يتجدد عقد إيجاره ، فانه هو الذى يفضل. ( 2 ) فإذا لم يوجد سبب لتفضيل أحد المستأجرين فليس لهم فيما تعارضت فيه حقوقهم الا طلب التعويض."}, {"number": "574", "chapter": "الفصل الأول", "text": "إذا ترتب على عمل من جهة حكومية فى حدود القانون نقص كبير فى الانتفاع بالعين المؤجرة جاز للمستأجر تبعا للظروف أن يطلب فسخ العقد أو إنقاص الأجرة وله أن يطالب المؤجر بتعويضه إذا كان عمل الجهة الحكومية قد صدر بسبب يكون المؤجر مسئولا عنه ، كل هذا ما لم يقض الاتفاق بغيره."}, {"number": "575", "chapter": "الفصل الأول", "text": "( 1 ) لا يضمن المؤجر للمستأجر التعرض المادى إذا صدر من الجانبين مادام المتعرض لا يدعى حقا ، ولكن هذا لا يخل بما للمستأجر من الحق فى أن يرفع باسمه على المتعرض دعوى المطالبة بالتعويض وجميع دعاوى وضع اليد. ( 2 ) على انه إذا وقع التعرض المادى لسبب لا يد للمستأجر فيه ، وكان هذا التعرض من الجسامة بحيث يحرم المستأجر من الانتفاع بالعين المؤجرة جاز له تبعا للظروف أن يطلب فسخ العقد أو إنقاص الأجرة."}, {"number": "576", "chapter": "الفصل الأول", "text": "( 1 ) يضمن المؤجر للمستأجر جميع ما يوجد فى العين المؤجرة من عيوب تحول دون الانتفاع بها ، أو تنقص من هذا الانتفاع إنقاصا كبيرا ولكنه لا يضمن العيوب التى جرى العرف بالتسامح فيها. وهو مسئول عن خلو العين من صفات تعهد صراحة بتوافرها أو عن خلوها من صفات يقتضيها الانتفاع بها ، كل هذا ما لم يقض اتفاق بغيره. ( 2 ) ومع ذلك لا يضمن المؤجر العيب إذا كان المستأجر قد أخطر به أو كان يعلم به وقت التعاقد."}, {"number": "577", "chapter": "الفصل الأول", "text": "( 1 ) إذا وجد بالعين المؤجرة عيب يتحقق معه الضمان. جاز للمستأجر تبعا للظروف أن يطلب فسخ العقد أو إنقاص الأجرة وله كذلك أن يطلب إصلاح العيب أو أن يقوم هو بإصلاحه على نفقة المؤجر إذا كان هذا الإصلاح لا يبهظ المؤجر. ( 2 ) فإذا لحق المستأجر ضرر من العيب التزم المؤجر بتعويضه ، ما لم يثبت انه كان يجهل وجود العيب."}, {"number": "578", "chapter": "الفصل الأول", "text": "يقع باطلا كل اتفاق يتضمن الإعفاء أو الحد من ضمان التعرض أو العيب إذا كان المؤجر قد اخفى عن غش سبب هذا الضمان."}, {"number": "579", "chapter": "الفصل الأول", "text": "يلتزم المستأجر بأن يستعمل العين المؤجرة على النحو المتفق عليه ، فإن لم يكن هناك اتفاق التزم أن يستعمل العين بحسب ما أعدت له."}, {"number": "580", "chapter": "الفصل الأول", "text": "( 1 ) لا يجوز للمستأجر أن يحدث بالعين المؤجرة تغييرا بدون اذن المؤجر الا إذا كان هذا التغيير لا ينشأ عنه أى ضرر للمؤجر. ( 2 ) فإذا احدث المستأجر تغييرا فى العين المؤجرة مجاوزا فى ذلك حدود الإلتزام الواردة فى الفقرة السابقة ، جاز إلزامه بإعادة العين إلى الحالة التى كانت عليها وبالتعويض أن كان له مقتض."}, {"number": "581", "chapter": "الفصل الأول", "text": "( 1 ) يجوز للمستأجر أن يضع بالعين المؤجر أجهزة لتوصيل المياه والنور الكهربائى والغاز والتليفون والراديو وما إلى ذلك ما دامت الطريقة التى توضع بها هذه الأجهزة لا تخالف الأصول المرعية ، وذلك ما لم يثبت المؤجر أن وضع هذه الأجهزة يهدد سلامة العقار. ( 2 ) فإذا كان تدخل المؤجر لازما لإتمام شئ من ذلك. جاز للمستأجر أن يقتضى منه هذا التدخل ، على أن يتكفل بما ينفقه المؤجر."}, {"number": "582", "chapter": "الفصل الأول", "text": "يلتزم المستأجر بإجراء الترميمات التأجيرية ، التى يقضى بها العرف ، ما لم يكن هناك اتفاق على غير ذلك."}, {"number": "583", "chapter": "الفصل الأول", "text": "( 1 ) يجب على المستأجر أن يبذل من العناية فى استعمال العين المؤجرة وفى المحافظة عليها ما يبذله الشخص المعتاد. ( 2 ) وهو مسئول عما يصيب العين اثناء انتفاعه بها من تلف أو هلاك غير ناشئ عن استعمالها استعمالا مألوفا."}, {"number": "584", "chapter": "الفصل الأول", "text": "( 1 ) المستأجر مسئول عن حريق العين المؤجرة الا إذا اثبت أن الحريق نشأ عن سبب لا يد له فيه. ( 2 ) فإذا تعدد المستأجرون لعقار واحد ، كان كل منهم مسئولا عن الحريق بنسبة الجزء الذى يشغله ، ويتناول ذلك المؤجر أن كان مقيما فى العقار. هذا ما يثبت النار ابتدأ شبوبها فى الجزء الذى شغله أحد المستأجرين فيكون وحده مسئولا عن الحريق."}, {"number": "585", "chapter": "الفصل الأول", "text": "يجب على المستأجر أن يبادر إلى إخطار المؤجر بكل أمريستوجب تدخله ، كأن تحتاج العين إلى ترميمات مستعجلة ، أو ينكشف عيب بها ، أو يقع اغتصاب عليها ، أو يعتدى أجنبى بالتعرض لها ، أو بإحداث ضرر بها."}, {"number": "586", "chapter": "الفصل الأول", "text": "1- يجب على المستأجر أن يقوم بوفاء الأجرة فى المواعيد المتفق عليها، فاذا لم يكن هناك اتفاق وجب وفاء الأجرة فى المواعيد التى يعينها عرف الجهة. 2- ويكون الوفاء فى موطن المستأجر مالم يكن هناك اتفاق أو عرف يقضى بغير ذلك."}, {"number": "587", "chapter": "الفصل الأول", "text": "الوفاء بقسط من الأجرة قرينة على الوفاء بالأقساط السابقة على هذا القسط حتى يقوم الدليل على عكس ذلك."}, {"number": "588", "chapter": "الفصل الأول", "text": "- يجب على كل من استأجر منزلا أو مخزنا أو حانوتا أو مكانا مماثلا لذلك أو أرضا زراعية أن يضع فى العين المؤجرة أثاثا أو بضائع أو محصولات أو مواشى أو أداوت تكون قيمتها كافية لضمان الأجرة عن سنتين ، أو عن كل مدة الايجار اذا قلت عن سنتين، هذا مالم تكن الأجرة قدعجلت ، ويعفى المستأجر من هذا الالتزام اذا تم الاتفاق على هذا الاعفاء أو اذا قدم المستأجر تأمينا آخر."}, {"number": "589", "chapter": "الفصل الأول", "text": "1- يكون للمؤجر ، ضمانا لكل حق يثبت له بمقتضى عقد الايجار، أن يحبس جميع المنقولات القابلة للحجز الموجودة فى العين المؤجرة ما دامت مثقلة بامتياز المؤجر ولو لم تكن مملوكة للمستأجر وللمؤجر الحق فى أن يمانع فى نقلها ، فاذا نقلت رغم معارضته أو دون علمه كان له الحق فى استردادها من الحائز لها ولو كان حسن النية، مع عدم الاخلال بما يكون لهذا الحائز من حقوق. 2- وليس للمؤجر أن يستعمل حقه فى الحبس أو فى الاسترداد اذا كان نقل هذه الاشياء أمرا اقتضته حرفة المستأجر أو المألوف من شئون الحياة، أو كانت المنقولات التى تركت فى العين المؤجرة أو التى تم استردادها تفى بضمان الأجرة وفاء تاما."}, {"number": "590", "chapter": "الفصل الأول", "text": "يجب على المستأجر أن يرد العين المؤجرة عند انتهاء الايجار، فاذا أبقاها تحت يده دون حق كان ملزما أن يدفع للمؤجر تعويضا يراعى فى تقديره القيمة الايجارية للعين وما أصاب المؤجر من ضرر."}, {"number": "591", "chapter": "الفصل الأول", "text": "1- على المستاجر أن يرد العين المؤجرة بالحالة التى تسلمها عليها، الا مايكون قد أصاب العين من هلاك أو تلف لسبب لايد له فيه. 2- فاذا كان تسليم العين للمستأجر قد تم دون كتابة محضر أو دون بيان بأوصاف هذه العين ، افترض حتى يقوم الدليل على العكس، ان المستاجر قد تسلم العين فى حالة حسنة."}, {"number": "592", "chapter": "الفصل الأول", "text": "1- اذا أوجد المستأجر فى العين المؤجرة بناء أو غراسا أو غير ذلك من التحسينات مما يزيد فى قيمة العقار، التزم المؤجر أن يرد للمستأجر عند انقضاء الايجار ما أنفقه فى هذه التحسينات أو ما زاد فى قيمة العقار ، ما لم يكن هناك اتفاق يقضى بغير ذلك. 2- اذا كانت تلك التحسينات قد استحدثت دون علم المؤجر أو رغم معارضته ، كان له أيضا أن يطلب من المستأجر ازالتها. وله أن يطلب فوق ذلك تعويضا عن الضرر الذى يصيب العقار من هذه الازالة ان كان للتعويض مقتض. 3- فاذا اختار المؤجر أن يحتفظ بهذه الحسينات فى مقابل رد احدى القيمتين المتقدم ذكرهما ، جاز للمحكمة أن تنذره الى أجل للوفاء بها. ثالثا - التنازل عن الإيجار والإيجار من الباطن"}, {"number": "593", "chapter": "الفصل الأول", "text": "للمستأجر حق التنازل عن الايجار أو الايجار من الباطن وذلك عن كل ما استأجره أو بعضه مالم يقض الاتفاق بغير ذلك."}, {"number": "594", "chapter": "الفصل الأول", "text": "1- منع المستأجر من ان يؤجر من الباطن يقتضى منعه من التنازل عن الايجار وكذلك العكس. 2- ومع ذلك اذا كان الأمر خاصا بايجار عقار أنشئ به مصنع أو متجر واقتضت الضرورة أن يبيع المستأجر هذا المصنع أو المتجر، جاز للمحكمة بالرغم من وجود الشرط المانع أن تقضى بابقاء الايجار اذا قدم المشترى ضمانا كافيا ولم يلحق المؤجر من ذلك ضرر محقق."}, {"number": "595", "chapter": "الفصل الأول", "text": "فى حالة التنازل عن الايجار يبقى المستأجر ضامنا للمتنازل له فى تنفيذ التزاماته."}, {"number": "596", "chapter": "الفصل الأول", "text": "------- 1- يكون المستأجر من الباطن ملزما بأن يؤدى للمؤجرة مباشرة ما يكون ثابتا فى ذمته للمتسأجر الأصلى وقت أن ينذره المؤجر. 2- ولايجوز للمستأجر من الباطن أن يتمسك قبل المؤجر بما يكون قد عجله من الأجرة للمستأجر الأصلى ، ما لم يكن ذلك قد تم قبل الانذار وفقا للعرف أو لاتفاق ثابت تم وقت الايجار من الباطن."}, {"number": "597", "chapter": "الفصل الأول", "text": "تبرأ ذمة المستأجر الاصلى قبل المؤجر سواء فيما يتعلق بضمانه للمتنازل له فى حالة التنازل عن الايجار أو فيما يتعلق بما يفرضه عقد الايجار الاصلى من التزامات فى حالة الايجار من الباطن: أولا:- اذا صدر من المؤجر قبول صريح بالتنازل عن الايجار أو بالأيجار من الباطن. ثانيا:- اذا استوفى المؤجر الأجرة مباشرة من المتنازل له أو من المستأجر من الباطن دون أن يبدى أى تحفظ فى شأن حقوقه قبل المستأجر الأصلى. رابعا - إنتهاء الإيجار"}, {"number": "598", "chapter": "الفصل الأول", "text": "- ينتهى الايجار بانتهاء المدة المعينة فى العقد دون حاجة الى تنبيه بالاخلاء."}, {"number": "599", "chapter": "الفصل الأول", "text": "- 1- اذا انتهى عقد الايجار وبقى المستأجر منتفعا بالعين المؤجرة بعلم المؤجر ودون اعتراض منه ، اعتبر الايجار قد تجدد بشروطه الأولى ولكن لمدة غير معينة، وتسرى على الايجار اذا تجدد علىهذا الوجه أحكام المادة 563. 2- ويعتبر هذا التجديد الضمنى ايجارا جديدا لامجرد امتداد للايجار الأصلى ، ومع ذلك تنتقل الى الايجار القديم مع مراعاة قواعد الشهر العقارى ، أما الكفالة شخصية كانت أو عينية فلا تنتقل الى الايجار الجديد الا اذا رضى الكفيل بذلك."}, {"number": "600", "chapter": "الفصل الأول", "text": "اذا نبه أحد الطرفين على الآخر بالاخلاء واستمر المستأجر مع ذلك منتفعا بالعين بعد انتهاء الايجار فلا يفترض أن الايجار قد تجدد مالم يقم الدليل على عكس ذلك. خامسا - موت المستأجر أو إعساره"}, {"number": "601", "chapter": "الفصل الأول", "text": "- 1- لا ينتهى الايجار بموت المؤجر ولابموت المتسأجر. 2- ومع ذلك اذا مات المستأجر جاز لورثته أن يطلبوا انهاء العقد اذا أثبتوا أنه بسبب موت مورثهم أصبحت أعباء العقد أثقل من أن تتحملها مواردهم ، أو اصبح الايجار مجاوزا حدود حاجتهم. وفى هذه الحالة يجب أن تراعى مواعيد التنبيه بالاخلاء المبينة فى المادة 563 ، وأن يكون طلب انهاء العقد فى مدة ستة أشهر على الأكثر من وقت موت المستأجر."}, {"number": "602", "chapter": "الفصل الأول", "text": "- اذا لم يعقد الايجار الا بسبب حرفة المستأجر أو لاعتبارات أخرى تتعلق بشخصه ثم مات ، جاز لورثته أو للمؤجر أن يطلبوا انهاء العقد."}, {"number": "603", "chapter": "الفصل الأول", "text": "1- لايترتب على اعسار المستاجر أن تحل أجرة لم تستحق. 2- ومع ذلك يجوز للمؤجر ان يطلب فسخ الايجار اذا لم تقدم له فى ميعاد مناسب تأمينات تكفل الوفاء بالأجرة التى لم تحل. وكذلك يجوز للمستأجر اذا لم يرخص له فى التنازل عن الايجار أو فى الايجار من الباطن أن يطلب الفسخ على أن يدفع تعويضا عادلا."}, {"number": "604", "chapter": "الفصل الأول", "text": "- 1- اذا انتقلت ملكية العين المؤجرة اختيارا أو جبرا الى شخص آخر ، فلا يكون الايجار نافذا فى حق هذا الشخص اذا لم يكن له تاريخ ثابت سابق على التصرف الذى نقل الملكية. 2- ومع ذلك يجوز لمن انتقلت اليه الملكية أن يتمسك بعقد الايجار ولو كان هذا العقد غير نافذ فى حقه."}, {"number": "605", "chapter": "الفصل الأول", "text": "1- لايجوز لمن انتقلت اليه ملكية العين المؤجرة ولم يكن الايجار نافذا فى حقه أن يجبر المستأجر على الاخلاء الا بعد التنبية عليه بذلك فى المواعيد المبينة فى المادة 563. 2- فاذا نبه على المستأجر بالاخلاء قبل انقضاء الايجار فان المؤجر يلتزم بأن يدفع للمستأجر تعويضا ما لم يتفق على غير ذلك ، ولايجبر المستأجر على الاخلاء الا بعد أن يتقاضى التعويض من المؤجر أو ممن انتقلت اليه الملكية نيابة عن المؤجر أو بعد أن يحصل على تأمين كاف للوفاء بهذا التعويض."}, {"number": "606", "chapter": "الفصل الأول", "text": "لايجوز للمستاجر أن يتمسك بما عجله من الأجرة قبل من انتقلت اليه اذا أثبت هذا أن المستأجر وقت الدفع كان يعلم انتقال الملكية أوكان من المفروض حتما أن يعلم . فاذا عجز من انتقلت اليه الملكية عن الاثبات فلا يكون له الا الرجوع على المؤجر."}, {"number": "607", "chapter": "الفصل الأول", "text": "اذا اتفق على أنه يجوز للمؤجر أن ينهى العقد اذا وجدت له حاجة شخصية للعين ، وجب عليه فى استعمال هذا الحق أن ينبه علىالمستأجر بالاخلاء فى المواعيد المبينة بالمادة 563 ما لم يقض الاتفاق بغير ذلك ."}, {"number": "608", "chapter": "الفصل الأول", "text": "1- اذا كان الايجار معين المدة ، جاز لكل من المتعاقدين أن يطلب انهاء العقد قبل انقضاء مدته اذا جدت ظروف خطيرة غير متوقعة من شأنها أن تجعل تنفيذ الايجار من مبدأ الأمر أو فى أثناء سريانه مرهقا، على أن يراعى من يطلب انهاء العقد مواعيد التنبيه بالاخلاء المبينة بالمادة 563، وعلى أن يعوض الطرف الآخر تعويضا عادلا. 2- فاذا كان المؤجر هو الذى يطلب انهاء العقد ، فلايجبر المستاجر على رد العين المؤجرة حتى يستوف التعويض. أو يحصل على تامين كاف."}, {"number": "609", "chapter": "الفصل الأول", "text": "يجوز للموظف أو المستخدم اذا اقتضى عمله أن يغير محل اقامته ، أن يطلب انهاء ايجار مسكنه اذا كان هذا الايجار معين المدة على أن يراعى المواعيد المبينة فى المادة 563، ويقع باطلا كل اتفاق على غير ذلك. 2- بعض أنواع الإيجار إيجارالأراضى الزراعية"}, {"number": "610", "chapter": "الفصل الأول", "text": "اذا كانت العين المؤجرة أرضا زراعية ، فلا يكون المؤجر ملزما بتسليم المواشى والأدوات الزراعية التى توجد فى الأراضى الا اذا كان الايجار يشملها."}, {"number": "611", "chapter": "الفصل الأول", "text": "اذا تسلم المستأجر مواشى وأدوات زراعية مملوكة للمؤجر ، وجب عليه أن يرعاها ويتعهدها بالصيانة بحسب المألوف فى استغلالها."}, {"number": "612", "chapter": "الفصل الأول", "text": "اذا ذكر فى عقد ايجار الأرض الزراعية أن الايجار قد عقد لسنة أو لعدة سنوات ، كان المقصود من ذلك أنه قد عقد لدورة زراعية سنوية أو لعدة دورات."}, {"number": "613", "chapter": "الفصل الأول", "text": "------- 1- يجب أن يكون استغلال المستأجر للأرض الزراعية موافقا لمتقضيات الاستغلا ل المألوف ، وعلى المستأجر بوجه خاص أن يعمل على أن تبقى الأرض صالحة للانتاج. 2- ولايجوز له دون رضاء المؤجر أن يدخل على الطريقة المتبعة فى استغلالها أى تغيير جوهرى يمتد أثره الى ما بعد انقضاء الايجار."}, {"number": "614", "chapter": "الفصل الأول", "text": "1- على المستأجر أن يقوم باجراء الاصلاحات التى يقضيها الانتفاع المألوف بالأرض المؤجرة ، ويلتزم بوجه خاص بتطهير وصيانة الترع والمساقى والمراوى والمصارف ، وكذلك القيام بأعمال الصيانة المعتاجة للطرق والجسور والقناطر والأسوار والآبار والمبانى المعدة للسكنى أو للاستغلال ، كل هذا مالم يقض الاتفاق أو العرف بغيره. 2- أما اقامة المبانى والاصلاحات الكبرى للمبانى القائمة وغيرها من ملحقات العين ، فيلتزم بها المؤجر ما يقض الاتفاق أو العرف بغير ذلك وكذلك يكون الحكم فى الاصلاحات اللازمة للأبار والترع ومجارى المياه والخزانات."}, {"number": "615", "chapter": "الفصل الأول", "text": "------- اذا منع المستأجر من تهيئة الارض للزراعة او من بذرها وهلك البذر كله او اكثره وكان بسبب قوة قاهرة برئت ذمة المستأجر من الأجرة كلها او بعضها بحسب الأحوال كل هذا ما لم يوجد انفاق يقضى بغيره ."}, {"number": "616", "chapter": "الفصل الأول", "text": "1- اذا بذر المستأجر الأرض ثم هلك الزرع كله قبل حصاده بسبب قوة قاهرة ، جاز للمستأجر أن يطلب اسقاط الاجرة . 2- أما اذا لم يهلك الا بعض الزرع ولكن ترتب على الهلاك نقص كبير فى ريع الأرض ، كان للمستأجر أن يطلب انقاص الأجرة. 3- وليس لمستأجر أن يطلب اسقاط الأجرة أو انقاصها اذا كان قد عوض عما أصابه من ضرر بما عاد عليه من أرباح فى مدة الاجارة كلها أو بما حصل عليه من طريق التأمين أو من أى طريق آخر."}, {"number": "617", "chapter": "الفصل الأول", "text": "يجوز للمستأجر اذا لم تنضج غلة الأرض عند انتهاء الايجار بسبب لايد له فيه أن يبقى بالعين المؤجرة حتى تنضج الغلة على أن يؤدى الأجرة المناسبة."}, {"number": "618", "chapter": "الفصل الأول", "text": "لايجوز للمستآجر أن يأتى عملا يكون من شأنه أن ينقص أو يؤجر انتفاع من يخلفه . ويجب عليه بوجه خاص قبيل اخلاء الأرض أن يسمح لهذا الخلف بتهيئة الأرض وبذرها اذا ام يصبه ضرر من ذلك. المزارعة"}, {"number": "619", "chapter": "الفصل الأول", "text": "- يجوز أن تعطى الأرض الزراعية والارض المغروسة بالأشجار مزارعة للمستأجر فى مقابل أخذ المؤجر جزء معينا من المحصول."}, {"number": "620", "chapter": "الفصل الأول", "text": "تسرى أحكام الايجار على المزارعة مع مراعاة الأحكام الآتية اذا لم يوجد اتفاق أو عرف يخالفها."}, {"number": "621", "chapter": "الفصل الأول", "text": "- اذا لم تعين مدة المزارعة ، كانت المدة دورة زراعية سنوية."}, {"number": "622", "chapter": "الفصل الأول", "text": "الايجار فى المزارعة تدخل فيه الأدوات الزراعية والمواشى التى توجد فى الأرض وقت التعاقد اذا كانت مملوكة للمؤجر."}, {"number": "623", "chapter": "الفصل الأول", "text": "- 1- يجب على المستأجر أن يبذل فى الزراعة وفى المحفاظة على الزرع من العناية مايبذله فى شئون نفسه. 2- وهو مسئول عما يصيب الأرض من التلف فى أثناء الانتفاع الا اذا أثبت أنه بذل فى المحافظة عليها وفى صيانتها ما يبذله الشخص المعتاد. 3- ولايلزم المستأجر أن يعوض مانفق من المواشى ولا ما يلى من الأدوات الزراعية بلا خطأ منه."}, {"number": "624", "chapter": "الفصل الأول", "text": "1- توزع الغلة بين الطرفين بالنسبة المتفق عليها أو بالنسبة التى يعينها العرف، فاذا لم يوجد اتفاق أو عرف كان لكل منها نصف الغلة. 2- فاذا هلكت الغلة كلها أو بعضها بسبب قوة قاهرة، تحمل الطرفان معا تبعة هذا الهلاك ولايرجع أحد منهما على الآخر."}, {"number": "625", "chapter": "الفصل الأول", "text": "لايجوز فى المزراعة أن ينزل المستأجر عن الايجار أو أن يؤجر الأرض من الباطن الا برضاء المؤجر."}, {"number": "626", "chapter": "الفصل الأول", "text": "------- لاتنقضى المزارعة بموت المؤجر، ولكنها تنقضى بموت المستأجر."}, {"number": "627", "chapter": "الفصل الأول", "text": "------- 1- اذا انتهت المزارعة قبل انقضاء مدتها، وجب أن يرد للمستأجر أو لورثته ما أنفقه المستأجر على المحصول الذى لم يتم نضجه مع تعويض عادل عما قام به المستأجر من العمل. 2- ومع ذلك اذا انتهت المزارعة بموت المستأجر، جاز لورثته عوضا عن استعمال حقهم فى استرداد النفقات المتقدم ذكرها أن يحلوا محل مورثهم حتى ينضج المحصول ما داموا يستطيعون القيام بذلك على الوجه المرضى. إيجار الوقف"}, {"number": "628", "chapter": "الفصل الأول", "text": "1- للناظر ولاية اجارة الوقف. 2- فلا يملكها الموقوف عليه ولو انحصر فيه الاستحقاق الا اذا كان متوليا من قبل الواقف أو مأذونا ممن له ولاية الاجارة من ناظر أو قاض."}, {"number": "629", "chapter": "الفصل الأول", "text": "ولاية قبض الأجرة للناظر لا للموقوف عليه الا أن أذن له الناظر فى قبضها."}, {"number": "630", "chapter": "الفصل الأول", "text": "1- لايجوز للناظر أن يستأجر الوقف ولو بأجر المثل. 2- ويجوز له أن يؤجر الوقف لأصوله وفروعه على أن يكون ذلك بأجر المثل."}, {"number": "631", "chapter": "الفصل الأول", "text": "------- لاتصح اجارة الوقف بالغبن الفاحش الا اذا كان المؤجر هو المستحق الوحيد الذى له ولاية التصرف فى الوقف ، فيجوز اجارته بالغبن الفاحش فى حق نفسه لا فى حق من يليه من المستحقين."}, {"number": "632", "chapter": "الفصل الأول", "text": "1- فى اجارة الوقف تكون العبرة فى تقدير أجر المثل بالوقت الذى أبرم فيه عقد الايجار ، ولايعتد بالتغيير الحاصل بعد ذلك. 2- واذا أجر الناظر الوقف بالغبن الفاحش ، وجب على المستأجر تكملة الأجرة الى أجر المثل والا فسخ العقد."}, {"number": "633", "chapter": "الفصل الأول", "text": "1- لايجوز للناظر بغير اذن القاضى أن يؤجر الوقف مدة تزيد على ثلاث سنين ولو كان ذلك بعقود مترادفة ، فاذا عقدت الاجارة لمدة أطول، أنقصت المدة الى ثلاث سنين. 2- ومع ذلك اذا كان الناظر هو الواقف أو المستحق الوحيد جاز له أن يؤجر الوقف مدة تزيد على ثلاث سنين بلا حاجة الى اذن القاضى، وهذا دون اخلال بحق الناظر الذى يخلفه فى طلب انقاص المدة الى ثلاث سنين."}, {"number": "634", "chapter": "الفصل الأول", "text": "تسرى أحكام عقد الايجار على اجارة الوقف الا اذا تعارضت مع النصوص السابقة."}, {"number": "635", "chapter": "الفصل الثانى", "text": "العارية عقد يلتزم به المعير أن يسلم المستعير شيئا غير قابل للاستهلاك ليستعمله بلا عوض لمدة معينة أو فى غرض معين على أن يرده بعد الاستعمال. 1- إلتزامات المعير"}, {"number": "636", "chapter": "الفصل الثانى", "text": "يلتزم المعير أن يسلم المستعير الشئ المعار بالحالة التى يكون عليها وقت انعقاد العارية، وأن يتركه للمستعير طول مدة العارية."}, {"number": "637", "chapter": "الفصل الثانى", "text": "1- اذا اضطر المستعير الى الانفاق للمحافظة على الشئ أثناء العارية، التزم المعير أن يرد اليه ما أنفقه من المصروفات. 2- أما المصروفات النافعة فتتبع فى شأنها الأحكام الخاصة بالمصروفات الى ينفقها من يجوز الشئ وهو سئ النية."}, {"number": "638", "chapter": "الفصل الثانى", "text": "1- لاضمان على المعير فى استحقاق الشئ المعار الا أن يكون هناك اتفاق على الضمان أو أن يكون المعير قد تعمد أخفاء سبب الاستحقاق. 2- ولاضمان عليه كذلك فى العيوب الخفية، غير أنه اذا تعمد اخفاء العيب أو اذا ضمن سلامة الشئ منه ، لزمه تعويض المستعير عن كل ضرر يسببه ذلك. 2- إلتزامات المستعير"}, {"number": "639", "chapter": "الفصل الثانى", "text": "- 1- ليس للمستعير أن يستعمل الشئ المعار الا على الوجه المعين وبالقدر المحدد ، وذلك طبقا لما يبينه العقد أو تقبله طبيعة الشئ أو يعينه العرف، ولايجوز له دون أذن المعير أن ينزل عن الاستعمال الغير ولو على سبيل التبرع. 2- ولايكون مسئولا عما يلحق الشئ من تغيير أو تلف يسببه الاستعمال الذى تبيحه العارية."}, {"number": "640", "chapter": "الفصل الثانى", "text": "------- 1- اذا اقتضى استعمال الشئ نفقة من المستعير فليس له استردادها، وهو مكلف بالنفقة اللازمة لصيانة الشئ صيانة معتادة. 2- وله أن ينزع من الشئ المعر كل ما يكون قد أضافه اليه ، على أن يعيد الشئ الى حالته الأصلية."}, {"number": "641", "chapter": "الفصل الثانى", "text": "على المستعير أن يبذل فى المحافظة على الشئ العناية التى يبذلها فى المحافظة على ماله دون أن ينزل فى ذلك عن عناية الرجل المعتاد. 2- وفى كل حال يكون ضامنا لهلاك الشئ اذا نشأ الهلاك عن حادث مفاجئ أو قوة قاهرة وكان فى وسعه أن يتحاشاه باستعمال شئ من ملكه الخاص، أو كان بين أن ينقذ شيئا مملوكا له أوالشئ المعار فاختار أن ينقذ ما يملكه."}, {"number": "642", "chapter": "الفصل الثانى", "text": "1- متى انتهت العارية وجب على المستعير أن يرد الشئ الذى تسلمه بالحالة التى يكون عليها ، وذلك دون اخلال بمسئوليته عن الهلاك أو التلف. 2- ويجب رد الشئ فى المكان الذى يكون المستعير قد تسلمه فيه ما لم يوجد اتفاق يقضى بغير ذلك. إنتهاء العارية"}, {"number": "643", "chapter": "الفصل الثانى", "text": "1- تنتهى العارية بانقضاء الأجل المتفق عليه فاذا لم يعين لها أجل انتهت باستعمال الشئ فيما أعير من أجله. 2- فاذا لم يكن هناك سبيل لتعيين مدة العارية ، جاز للمعير أن يطلب انهائها فى أى وقت. 3- وفى كل حال يجوز للمستعير أن يرد الشئ المعار قبل انتهاء العارية غير أنه اذا كان هذا الرد يضر المعير فلا يرغم على قبولة."}, {"number": "644", "chapter": "الفصل الثانى", "text": "يجوز للمعير أن يطلب فى اى وقت انهاء العارية فى الأحوال الآتية: (أ) اذا عرضت له حاجة عاجلة للشئ لم تكن متوقعة. (ب) اذا أساء المستعير استعمال الشئ أو قصر فى الاحتياط الواجب للمحافظة عليه. (جـ) اذا أعسر بعد انعقاد العارية أو كان معسرا قبل ذلك دون علم من المعير."}, {"number": "645", "chapter": "الفصل الثانى", "text": "- تنتهى العارية بموت المستعير مالم يوجد اتفاق يقضى بغيره."}, {"number": "646", "chapter": "الفصل الأول", "text": "المقاولة عقد يتعهد بمقتضاه أحد المتعاقدين أن يصنع شيئا أو أن يؤدى عملا لقاء أجر يتعهد به المتعاقدين الآخرين. إلتزامات المقاول"}, {"number": "647", "chapter": "الفصل الأول", "text": "1- يجوز أن يقتصر المقاول على التعهد بتقديم عمله على ان يقدم رب العمل المادة التى يستخدمها أو يستعين بها فى القيام بعمله. 2- كما يجوز أن يتعهد المقاول بتقديم العمل والمادة معا."}, {"number": "648", "chapter": "الفصل الأول", "text": "اذا تعهد المقاول بتقديم مادة العمل كلها او بعضها، كان مسئولا عن جودتها وعليه ضمانها لرب العمل."}, {"number": "649", "chapter": "الفصل الأول", "text": "1- اذا كان رب العمل هو الذى قدم المادة، فعلى المقاول أن يحرص عليها ويراعى أصول الفن فى استخدامه لها وأن يؤدى حسابا لرب العمل عما استعملها فيه ويرد اليه مابقى منها، فاذا صار شئ من هذه المادة غير صالح للاستعمال بسبب اهماله أو قصور كفايته الفنية، التزم برد قيمة هذا الشئ لرب العمل. 2- وعلى المقاول أن يأتى بما يحتاج اليه فى انجاز العمل من أدوات ومهمات اضافية ويكون ذلك على نفقته . هذا لم يقض الاتفاق أو عرف الحرفة بغيره."}, {"number": "650", "chapter": "الفصل الأول", "text": "1- اذا ثبت أثناء سير العمل أن المقاول يقوم به على وجه معيب أو مناف للعقد، جاز لرب العمل أن ينذره بأن يعدل من طريقة التنفيذ خلال أجل معقول يعينه له . فاذا انقضى الأجل دون أن يرجع المقاول الى الطريقة الصحيحة ، جاز لرب العمل أن يطلب أما فسخ العقد وأما أن يعهد الى مقاول آخر بانجاز العمل على نفقة المقاول الأول طبقا لأحكام المادة 209. 2- على أنه يجوز طلب فسخ العقد فى الحال دون حاجة الى تعيين آجل اذا كان اصلاح ما فى طريقة التنفيذ من عيب مستحيلا."}, {"number": "651", "chapter": "الفصل الأول", "text": "1- يضمن المهندس المعمارى والمقاول متضامنين ما يحدث خلال عشر سنوات من تهدم كلى أوجزئى فيما شيدوه من مبان أو أقاموه من منشأت ثابتة أخرى وذلك ولو كان التهدم ناشئا عن عيب فى الأرض ذاته ، أو كان رب العمل قد أجاز اقامة المنشأت المعيبة، مالم يكن المتعاقدان فى هذه الحالة قد أرادا أن تبقى هذه المنشأت مدة أقل من عشر سنوات. 2- ويشمل الضمان المنصوص عليه فى الفقرة السابقة ما يوجد فى المبانى والمنشآت من عيوب يترتب عليها تهديد متانة البناء وسلامته. 3- وتبدأ مدة السنوات العشر من وقت تسلم العمل. ولاتسرى هذه المادة على ما قد يكون للمقاول من حق الرجوع على المقاولين من الباطن"}, {"number": "652", "chapter": "الفصل الأول", "text": "اذا اقتصر المهندس المعمارى على وضع التصميم دون أن يكلف الرقابة على التنفيذ، لم يكن مسئولا الا عن العيوب التى أتت من التصميم."}, {"number": "653", "chapter": "الفصل الأول", "text": "- يكون باطلا كل شرط يقصد به اعفاء المهندس المعمارى والمقاول من الضمان أو الحد منه."}, {"number": "654", "chapter": "الفصل الأول", "text": "تسقط دعاوى الضمان المتقدمة بانقضاء ثلاث سنوات من وقت حصول التهدم أن انكشاف العيب. إلتزامات رب العمل"}, {"number": "655", "chapter": "الفصل الأول", "text": "- متى أتم المقاول العمل ووضعه تحت تصرف رب العمل ، وجب على هذا أن يبادر الى تسلمه فى أقرب وقت ممكن بحسب الجارى فى المعاملات ، فاذا امتنع دون سبب مشروع عن التسليم رغم دعوته الى ذلك بانذار رسمى ، اعتبر أن العمل قد سلم اليه."}, {"number": "656", "chapter": "الفصل الأول", "text": "------- يستحق دفع الأجر عند تسلم العمل ، الا اذا قضى العرف أو الاتفاق بغير ذلك."}, {"number": "657", "chapter": "الفصل الأول", "text": "- 1- اذا أبرم عقد بمقتضى مقايسة على أساس الوحدة وتبين فى أثناء العمل أن من الضرورى لتنفيذ التصميم المتفق عليه مجاوزة المقايسة المقدرة مجاوزة محسوسة، وجب على المقاول أن يخطر فى الحال رب العمل بذلك مبينا مقدار ما يتوقعه من زيادة فى الثمن، فان لم يفعل سقط حقه فى استرداد ماجاوز به قيمة المقايسة من نفقات. 2- فاذا كانت المجاوزة التى يقتضيها تنفيذ التصميم جسيمة جاز لرب العمل أن يتحلل من العقد ويقف التنفيذ على أن يكون ذلك دون ابطاء، مع ايفاء المقاول قيمة ما أنجزه من الأعمال ، مقدرة وفقا لشروط العقد، دون أن يعوضه عما كان يستطيع كسبه لو أنه أتم العمل."}, {"number": "658", "chapter": "الفصل الأول", "text": "- 1- اذا أبرم العقد بأجر اجمالى على أساس تصميم اتفق عليه مع رب العمل، فليس للمقاول أن يطالب بأية زيادة فى الاجر خطأ من رب العمل أو يكون مأذونا به منه واتفق مع المقاول على أجره ولوحدث فى هذا التصميم تعديل أو اضافة الا أن يكون ذلك راجعا الى . 2-ويجب أن يحصل هذا الاتفاق كتابة، الا اذا كان العقد الأصلى ذاته قد اتفق عليه مشافهة. 3- وليس للمقاول اذا ارتفعت أسعار المواد الأولية وأجور الأيدى العاملة أو غيرها من التكاليف أن يستند الى ذلك ليطلب زيادة الأجور ولو بلغ هذا الارتفاع حدا يجعل تنفيذا العقد عسيرا. 4- على أنه اذا انهار التوزان الاقتصادى بين التزمات كل من رب العمل والمقاول بسبب حوادث استثنائية عامة لم تكن فى الحسبان وقت التعاقد، وتداعى بذلك الأساس الذى قام عليه التقدير المالى لعقد المقاولة، جاز للقاضى أن يحكم بزيادة الأجر أو بفسخ العقد."}, {"number": "659", "chapter": "الفصل الأول", "text": "اذا لم يحدد الأجر سلفا وجب الرجوع فى تحديده الى قيمة العمل ونفقات المقاول."}, {"number": "660", "chapter": "الفصل الأول", "text": "1- يستحق المهندس المعمارى أجرا مستقلا عن وضع التصميم وعمل المقايسة وآخر عن ادارة الأعمال. 2- فان لم يحدد العقد هذه الأجور وجب تقديرها وفقا للعرف الجارى. 3- غير أنه اذا لم يتم العمل بمقتضى التصميم الذى وضعه المهندس ، وجب تقدير الأجر بحسب الزمن الذى استغرقه وضع التصميم مع مراعاة طبيعة هذا العمل. المقاولة من الباطن"}, {"number": "661", "chapter": "الفصل الأول", "text": "------- 1- يجوز للمقاول أن يكل تنفيذ العمل فى جملته أو فى جزء منه الى مقاول من الباطن اذا لم يمنعه من ذلك شرط فى العقد أو لم تكن طبيعة العمل تفترض الاعتماد على كفايته الشخصية. 2- ولكنه يبقى فى هذه الحالة مسئولا عن المقاول من الباطن قبل رب العمل."}, {"number": "662", "chapter": "الفصل الأول", "text": "------- 1- يكون للمقاولين من الباطن وللعمال الذين يشتغلون لحساب المقاول فى تنفيذ العمل، حق مطالبة رب العمل مباشرة بما لايجاوز القدر الذى يكون مدينا به للمقاول الأصلى وقت رفع الدعوى ، ويكون لعمال المقاولين من الباطن مثل هذا الحق قبل كل من المقاول الأصلى ورب العمل. 2- ولهم فى حالة توقيع الحجز من أحدهم تحت يد رب العمل أو المقاول الأصلى امتياز على المبالغ المستحقة للمقاول الأصلى أو للمقاول من الباطن وقت توقيع الحجز ، ويكون الامتياز لكل منهم بنسبة حقه. ويجوز أداء هذه المبالغ اليهم مباشرة. 3- وحقوق المقاولين من الباطن والعمال المقررة بمقتضى هذه المادة مقدمة على حقوق من ينزل له المقاول عن دينه قبل رب العمل. إنقضاء المقاولة"}, {"number": "663", "chapter": "الفصل الأول", "text": "1- لرب العمل أن يتحلل من العقد ويقف التنفيذ فى أى وقت قبل اتمامه، على أن يعوض المقاول عن جميع ما أنفقه من المصروفات، وما أنجزه من الأعمال، وما كان يستطيع كسبه لو أنه أتم العمل. 2- على أنه يجوز للمحكمة أن تخفض التعويض المستحق عما فات المقاول من كسب اذا كانت الظروف تجعل هذا التخفيض عادلا ، ويتعين عليه بوجه خاص أن تنقص منه ما يكون المقاول قد اقتصده من جراء تحلل رب العمل من العقد وما يكون قد كسبه باستخدام وقته فى أمر آخر."}, {"number": "664", "chapter": "الفصل الأول", "text": "ينقضى عقد المقاول باستحالة تنفيذ العمل المعقود عليه."}, {"number": "665", "chapter": "الفصل الأول", "text": "------- 1- اذا هلك الشئ بسبب حادث مفاجئ قبل تسليمه لرب العمل، فليس للمقاول أن يطالب لا بثمن عمله ولابرد نفقاته، ويكون هلاك المادة على من قام بتوريدها من الطرفين. 2-أما اذا كان المقاول قد أعذر أن يسلم الشئ أو كان هلاك الشئ أو تلفه قبل التسليم راجعا الى خطئه ، وجب عليه أن يعوض رب العمل عما يكون هذا قد ورده من مادة للعمل. 3- فاذا كان رب العمل هو الذى أعذر أن يتسلم الشئ، أو كان هلاك الشئ أو تلفه راجعا الى خطأ منه أو الى عيب فى المادة التى قام بتوريدها، كان هلاك المادة عليه وكان للمقاول الحق فى الأجر وفى التعويض عند الاقتضاء."}, {"number": "666", "chapter": "الفصل الأول", "text": "ينقضى عقد المقاولة بموت المقاول اذا كانت مؤهلاته الشخصية محل اعتبار فى التعاقد. فان لم تكن محل اعتبار فلا ينتهى العقد من تلقاء نفسه ولايجوز لرب العمل فسخه فى غير الحالات التى تطبق فيها المادة 663 الا اذا لم تتوافر فى ورثة المقاول الضمانات الكافية لحسن تنفيذ العمل."}, {"number": "667", "chapter": "الفصل الأول", "text": "1- اذا انقضى العقد بموت المقاول ، وجب على رب العمل أن يدفع للتركة قيمة ما تم من الأعمال وما أنفق لتنفيذ ما لم يتم ، ذلك بقدر النفع الذى يعود عليه من هذه الأعمال والنفقات. 2- ويجوز لرب العمل فى نظير ذلك أن يطالب بتسليم المواد التى تم اعدادها والرسوم التى بدء تنفيذها ، على أن يدفع عنها تعويضا. 3- وتسرى هذه الأحكام أيضا اذا بدأ المقاول فى تنفيذ العمل ثم أصبح عاجزا عن اتمامه لسبب لايد له فيه. 2- إلتزام المرافق العامة"}, {"number": "668", "chapter": "الفصل الأول", "text": "------- التزام المرافق العامة عقد الغرض منه ادارة مرفق عام ذى صفة اقتصادية ، ويكون هذا العقد بين جهة الادارة المختصة بتنظيم هذا المرفق وبين فرد أو شركة يعهد اليها باستغلال المرفق فترة معينة من الزمن."}, {"number": "669", "chapter": "الفصل الأول", "text": "ملتزم المرفق العام يتعهد بمقتضى العقد الذى يبرمه مع عميله بأن يؤدى لهذا العميل على الوجه المألوف، الخدمات المقابلة للأجر الذى يقبضه وفقا للشروط المنصوص عليها فى عقد الالتزام وملحقاته، وللشروط التى تقتضيها طبيعة العمل ويقتضيها ما ينظم هذا العمل من القوانين ."}, {"number": "670", "chapter": "الفصل الأول", "text": "1- اذا كان ملتزم المرفق محتكرا له احتكارا قانونيا أو فعليا، وجب عليه أن يحقق المساواة التامة بين عملائة سواء فى الخدمات العامة أو فى تقاضى الأجور. 2- ولاتحول المساواة دون أن تكون هناك معاملة خاصة تنطوى على تخفيض الأجور او الاعفاء منها ، على أن ينتفع بهذه المعاملة من يطلب ذلك ممن توافرت فيه شروط يعينها الملتزم بوجه عام . ولكن المساواة تحرم على الملتزم أن يمنح أحد عملائه ميزات يرفض منحها للأخرين. 3- وكل تمييز يمنح على خلاف ماتقضى به الفقرة السابقة ، يوجب على الملتزم أن يعوض الضرر الذى قد يصيب الغير من جراء ما يترتب على هذا التمييز من اخلال بالتوازن الطبيعى فى المنافسة المشروعة."}, {"number": "671", "chapter": "الفصل الأول", "text": "- 1- يكون لتعريفات الأسعار التى قررتها السلطلة العامة قوة القانون بالنسبة الى العقود التى يبرمها الملتزم مع عملائه فلا يجوز للمتعاقدين أن يتفقا على ما يخالفها. 2- يجوز اعادة النظر فى القوائم وتعديلها. فاذا عدلت الأسعار المعمول بها وصدق على التعديل ، سرت الأسعار الجديدة دون أثر رجعى من الوقت الذى عينه قرار التصديق لسريانها. وما يكون جاريا وقت التعديل من اشتراكات فى المرفق العام يسرى عليه هذا التعديل من زيادة أو نقص فى الأجور وذلك فيما بقى من المدة بعد التاريخ المعين لسريان الأسعار الجديدة."}, {"number": "672", "chapter": "الفصل الأول", "text": "1- كل انحراف أو غلط يقع عند تطبيق تعريفة الأسعار على العقود الفردية يكون قابلا للتصحيح. 2- فاذا وقع الانحراف أوالغلط ضد مصلحة العميل ، كان له الحق فى استرداد ما دفعه زيادة على الاسعار المقررة . واذا وقع ضد مصلحة الملتزم بالمرفق العام، كان له الحق فى استكمال مانقص من الأسعار المقررة. ويكون باطلا كل اتفاق يخالف ذلك. ويسقط الحق فى الحالتين بانقضاء سنة من وقت قبض الأجور التى لاتتفق مع الأسعار المقررة."}, {"number": "673", "chapter": "الفصل الأول", "text": "1- على عملاء المرافق المتعلقة بتوزيع المياه والغاز والكهرباء والقوى المحركة وما شابه ذلك ، أن يتحملوا ما يلازم أداوت المرافق عادة من عطل أو خلل لمدة قصيرة، كهذا الذى تقتضيه صيانة الأدوات التى يدار بها المرفق. 2- ولملتزمى هذه المرافق أن يدفعوا مسئوليتهم عما يصيب المرفق من عطل أو خلل يزيد على المألوف فى مدته أو فى جسامته، اذا أثبتوا أن ذلك يرجع الى قوة قاهرة خارجة عن ادارة المرفق ، أو الى حادث مفاجئ وقع فى هذه الادارة دون أن يكون فى وسع أية ادارة يقظة غير مقترة أن تتوقع حصوله أو أن تدرأ نتائجه. ويعتبر الاضراب حادثا مفاجئا اذا استطاع الملتزم اقامة الدليل على أن وقوع الاضراب كان دون خطأ منه ، وأنه لم يكن فى وسعه أن يستبدل بالعمال المضربين غيرهم أو أن يتلافى نتيجة اضرابهم بأية وسيلة أخرى."}, {"number": "674", "chapter": "الفصل الثانى", "text": "عقد العمل هو الذى يتعهد فيه أحد المتعاقدين بأن يعمل فى خدمة المتعاقد الأخر وتحت ادارته أو اشرافه مقابل أجر يتعهد به المتعاقد الآخر."}, {"number": "675", "chapter": "الفصل الثانى", "text": "1- لاتسرى الأحكام الواردة فى هذا الفصل الا بالقدر الذى لاتتعارض فيه صراحة أو ضمنا مع التشريعات الخاصة التى تتعلق بالعمل. 2- وتبين هذه التشريعات طوائف العمال الذين لاتسرى عليهم هذه الأحكام."}, {"number": "676", "chapter": "الفصل الثانى", "text": "- 1- تسرى أحكام عقد العمل على العلاقة ما بين أرباب الأعمال وبين الطوافين والممثلين التجاريين الجوابين ومندوبى التأمين وغيرهم من الوسطاء ،ولو كانوا مأجورين بطريقة العمالة أو كانوا يعملون لحساب جملة من أرباب الأعمال، ما دام هؤلاء الأشخاص تابعين لأرباب العمل وخاضعين لرقابتهم. 2- واذا انتهت خدمات الممثل التجارى أو المندوب الجواب ولو كان ذلك بانتهاء المدة المعينة فى عقد استخدامه، كان له الحق فى أن يتقاضى على سبيل الأجر العمالة أوالخصم المتفق عليه أو الذى يقضى به العرف عن التوصيات التى لم تبلغ رب العمل الا بعد خروج الممثل التجارى أوالمندوب الجواب من خدمته، متى كانت هذه التوصيات نتيجة مباشرة لما قام به هؤلاء المستخدمون من سعى لدى العملاء أثناء مدة خدمتهم على أنه لايجوز لهم المطالبة بهذا الحق الا خلال المدة المعتادة التى يقررها العرف بالنسبة الى كل مهنة. 1- أركان العقد"}, {"number": "677", "chapter": "الفصل الثانى", "text": "لايشترط فى عقد العمل أى شكل خاص ، مالم تنص القوانين واللوائح الادارية على خلاف ذلك."}, {"number": "678", "chapter": "الفصل الثانى", "text": "------- 1- يجوز أن يبرم عقد العمل لخدمة معينة أو لمدة معينة، كما يجوز أن يكون غير معين المدة. 2- فاذا كان عقد العمل لمدة حياة العامل أو رب العمل أو لأكثر من خمس سنوات ، جاز للعامل بعد انقضاء خمس سنوات أن يفسخ العقد دون تعويض على ان ينذر رب العمل الى ستة أشهر."}, {"number": "679", "chapter": "الفصل الثانى", "text": "1- اذا كان عقد العمل معين المدة انتهى من تلقاء نفسه بانقضاء مدته. 2- فاذا استمر طرفاه فى تنفيذ العقد بعد انقضاء مدته، اعتبر ذلك منهما تجديدا للعقد لمدة غير معينة."}, {"number": "680", "chapter": "الفصل الثانى", "text": "------- 1- اذا أبرم العقد لتنفيذ عمل معين انتهى بانقضاء العمل المتفق عليه. 2- فاذا كان العمل قابلا بطبيعته لأن يتجدد، واستمر تنفيذ العقد بعد انتهاء العمل المتفق عليه، اعتبر العقد قد تجدد ضمنيا المدة اللازمة للقيام بالعمل ذاته مرة أخرى."}, {"number": "681", "chapter": "الفصل الثانى", "text": "------- يفترض فى أداء الخدمة أن يكون بأجر اذا كان قوام هذه الخدمة عملا لم تجر العادة بالتبرع به أو عملا داخلا فى مهنة من أداه."}, {"number": "682", "chapter": "الفصل الثانى", "text": "1- اذا لم تنص العقود الفردية أو العقود الجماعية أو لوائح المصنع على الأجر الذى يلتزم به صاحب المصنع ، أخذ بالسعر المقدر لعمل من ذات النوع ان وجد، والا قدر الأجر طبقا لعرف المنهة وعرف الجهة التى يؤدى فيها العمل، فان لم يوجد عرف تولى القاضى تقدير الأجر وفقا لمقتضيات العدالة. 2-ويتبع ذلك أيضا فى تحديد نوع الخدمة الواجب على العامل أداؤها وفى تحديد مداها."}, {"number": "683", "chapter": "الفصل الثانى", "text": "------- تعتبر المبالغ الآتية جزاء لا يتجزأ من الأجر تحسب فى تعيين القدر الجائز الحجزعليه: 1- العمالة التى تعطى للطوافين والمندوبين الجوابين والممثلين التجاريين. 2- النس المئوية التى تدفع الى مستخدمى المحال التجارية عن ثمن ما يبيعونه والعلاوات التى تصرف لهم بسبب غلاء المعيشة. 3- كل منحة تعطى للعامل علاوة على المرتب وما يصرف له جزاء أمانته أو فى مقابل زيادة أعبائه العائلية وما شابه ذلك ، اذا كانت هذه المبالغ مقررة فى عقود العمل الفردية أو لوائح المصنع أو جرى العرف بمنحها حتى أصبح عمال المصنع يعتبرونها جزاء من الأجر لا تبرعا، على أن تكون هذه المبالغ معلومة المقدار قبل الحجز."}, {"number": "684", "chapter": "الفصل الثانى", "text": "1- لايلحق بالأجر ما يعطى على سبيل الوهبة الا فى الصناعة أو التجارة التى جرى فيها العرف بدفع وهبة وتكون لها قواعد تسمح بضبطها. 2- وتعتبر الوهبة جزاء من الأجر، اذا كان ما يدفعه منها العملاء الى مستخدمى المتجر الواحد يجمع فى صندوق مشترك ليقوم رب العمل بعد ذلك بتوزيعه على هؤلاء المستخدمين بنفسه أو تحت اشرافه. 3- ويجوز فى بعض الصناعات كصناعة الفنادق والمطاعم والمقاهى والمشارب ، الا يكون للعامل أجر سوى ما يحصل عليه من وهبة وما يتناول من طعام. أحكام العقد إلتزامات العامل"}, {"number": "685", "chapter": "الفصل الثانى", "text": "يجب على العامل: (أ) أن يؤدى العمل بنفسه وأن يبذل فى تأديته من العناية ما يبذله الشخص المعتاد. (ب) أن يأتمر بأوامر رب العمل الخاصة بتنفيذ العمل المتفق عليه أو العمل الذى يدخل فى وظيفة العامل، اذا لم يكن فى هذه الأوامر ما يخالف العقد أو القانون أو الآداب ، ولم يكن فى اطاعتها ما يعرض للخطر. (جـ) أن يحرص على حفظ الاشياء المسلمة اليه لتأدية عمله. (د) أن يحتفظ بأسرار العمل الصناعية والتجارية حتى بعد انقضاء العقد."}, {"number": "686", "chapter": "الفصل الثانى", "text": "- 1- اذا كان العمل الموكول الى العامل يسمح له بمعرفة عملاء رب العمل أو بالاطلاع على سر أعماله ، كان للطرفين أن يتفقا على ألا يجوز للعامل بعد انتهاء العقد أن ينافس رب العمل ، ولا أن يشترك فى أى مشروع يقوم بمنافسته. 2- غير أنه يشترط لصحة هذا الاتفاق أن يتوافر فيه ما يأتى: (أ) أن يكون العامل بالغا رشده وقت ابرام العقد. (ب) أن يكون القيد مقصورا من حيث الزمان والمكان ونوع العمل ، على القدر الضرورى لحماية مصالح رب العمل المشروعة. 3- ولايجوز أن يتمسك رب العمل بهذا الاتفاق اذا فسخ العقد أو رفض تجديده دون أن يقع من العامل ما يبرر ذلك ، كما لا يجوز له التمسك بالأتفاق إذا وقع منه هو ما يبرر فسخ العامل للعقد."}, {"number": "687", "chapter": "الفصل الثانى", "text": "اذا اتفق على شرط جزائى فى حالة الاخلال بالامتناع عن المنافسة وكان فى الشرط مبالغة تجعله وسيلة لاجبار العامل على البقاء فى صناعة رب العمل مدة أطول من المدة المتفق عليها، كان هذا الشرط باطلا وينسحب بطلانه أيضا الى شرط عدم المنافسة فى جملته."}, {"number": "688", "chapter": "الفصل الثانى", "text": "اذا وفق العامل الى اختراع جديد فى أثناء خدمة رب العمل ، فلا يكون لهذا أى حق فى ذلك الاختراع ولو كان العامل قد استنبطه بمناسبة ما قام به من أعمال فى خدمة رب العمل. 2- على أن ما يستنبطه العامل من اختراعات فى أثناء عمله يكون من حق رب العمل ، اذا كانت طبيعة الأعمال التى تعهد بها العامل تقتضى منه افراغ جهده فى الابتداع، أو اذا كان رب العمل قد اشترط فى العقد صراحة أن يكون له الحق فيما يهتدى اليه من المخترعات. 3- واذا كان الاختراع ذا أهمية اقتصادية جدية، جاز للعامل فى الحالات المنصوص عليها فى الفقرة السابقة أن يطالب بمقابل خاص يقدر وفقا لمقتضيات العدالة . ويراعى فى تقدير هذا المقابل مقدار المعونة التى قدمها رب العمل وما استخدم فى هذا السبيل من منشأته."}, {"number": "689", "chapter": "الفصل الثانى", "text": "يجب على العامل الى جانب الالتزامات المبينة فى المواد السابقة، أن يقوم بالالتزامات التى تفرضها القوانين الخاصة. إلتزامات رب العمل"}, {"number": "690", "chapter": "الفصل الثانى", "text": "يلتزم رب العمل أن يدفع للعامل أجرته فى الزمان والمكان اللذين يحددهما العقد أو العرف مع مراعاة ماتقضى به القوانين الخاصة من ذلك."}, {"number": "691", "chapter": "الفصل الثانى", "text": "- 1- اذا نص العقد على أن يكون للعامل فوق الأجر المتفق عليه أو بدلا منه حق فى جزء من أرباح رب العمل ، أو فى نسبة مئوية من جملة الايراد أو من مقدار الانتاج أو من قيمة ما يتحقق من وفر أو ما شاكل ذلك ، وجب على رب العمل أن يقدم الى العامل بعد كل جرد بيانا بما يستحقه من ذلك. 2- ويجب على رب العمل فوق هذا أن يقدم الى العامل أو الى شخص موثوق به يعينه ذوو الشأن أو يعينه القاضى ، المعلومات الضرورية للتحقق من صحة هذا البيان، وأن يأذن له فى ذلك بالاطلاع على دفاتره."}, {"number": "692", "chapter": "الفصل الثانى", "text": "اذا حضر العامل أو المستخدم لمزاولة عمله فى الفترة اليومية التى يلزمه بها عقد العمل ، أو أعلن أنه مستعد لمزاولة عمله فى هذه الفترة ولم يمنعه من العمل الا سبب راجع الى رب العمل، كان له الحق فى أجر ذلك اليوم."}, {"number": "693", "chapter": "الفصل الثانى", "text": "يجب على رب العمل الى جانب التزاماته المبينة فى المواد السابقة أن يقوم بالالتزامات التى تفرضها القوانين الخاصة. إنتهاء عقد العمل"}, {"number": "694", "chapter": "الفصل الثانى", "text": "1- ينتهى عقد العمل بانقضاء مدته أو بانجاز العمل الذى أبرم من أجله ، وذلك مع عدم الاخلال بأحكام المادتين 678, 679. 2- فان لم تعين مدة العقد بالاتقاق أو بنوع العمل أو بالغرض منه ، جاز لكل من المتعاقدين أن يضع حدا لعلاقته مع المتعاقد الآخر. ويجب فى استعمال هذا الحق أن يسبقه اخطار . وطريقة الاخطار ومدته تبينهما القوانين الخاصة."}, {"number": "695", "chapter": "الفصل الثانى", "text": "1- اذا كان العقد قد أبرم لمدة غير معينة، ونقضه أحد المتعاقدين دون مراعاة لميعاد الاخطار ، أو قبل انقضاء هذا الميعاد لزمه أن يعوض المتعاقد الآخر عن مدة هذا الميعاد أو عن المدة الباقية منه. ويشمل التعويض فوق الأجر المحدد الذى كان يستحق خلال هذه المدة جميع ملحقات الأجر التى تكون ثابته ومعينة ، مع مراعاة ماتقضى به القوانين الخاصة. 2- واذا فسخ العقد بتعسف من أحد المتعاقدين كان للمتعاقد الآخر، الى جانب التعويض الذى يكون مستحقا له بسبب عدم مراعاة ميعاد الاخطار، الحق فى تعويض ما أصابه من ضرر بسبب فسخ العقد فسخا تعسفيا. ويعتبر الفصل تعسفيا اذا وقع بسبب حجوز أو وقعت تحت يد رب العمل ، أو وقع هذا الفصل بسبب ديون يكون العامل قد التزم بها للغير."}, {"number": "696", "chapter": "الفصل الثانى", "text": "1- يجوز الحكم بالتعويض عن الفصل ولو لم يصدر هذا الفصل من رب العمل ، اذا كان هذا الأخير قد دفع العامل بتصرفاته، وعلى الأخص بمعاملته الجائزة أو مخالفته شروط العقد، الى أن يكون هو فى الظاهر الذى أنهى العقد. 2- ونقل العامل الى مركز أقل ميزة أو ملاءمة من المركز الذى كان يشغله لغير ما ذنب جناه ، لايعد عملا تعسفيا بطريق غير مباشر اذا ما اقتضته مصلحة العمل، ولكنه يعد كذلك اذا كان الغرض منه اساءه العامل."}, {"number": "697", "chapter": "الفصل الثانى", "text": "1- لاينفسخ عقد العمل بوفاة رب العمل ، مالم يكن شخصيته قد روعيت فى ابرام العقد، ولكن ينفسخ العقد بوفاة العامل. 2- ويراعى فى فسخ العقد لوفاة العامل ولمرضه مرضا طويلا أو لسبب قاهر آخر من شأنه أن يمنع العامل من الاستمرار فى العمل للأحكام التى نصت عليها القوانين الخاصة."}, {"number": "698", "chapter": "الفصل الثانى", "text": "1- تسقط بالتقادم الدعاوى الناشئة عن عقد العمل بانقضاء سنة تبدأ من وقت انتهاء العقد ، الا فيما يتعلق بالعمالة والمشاركة فى الأرباح والنسب المئوية فى جملة الايراد ، فان المدة فيها لاتبدأ الا من الوقت الذى يسلم فيه رب العمل الى العامل بيانا بما يستحقه بحسب آخر جرد. 2- ولا يسرى هذا التقادم الخاص علىالدعاوى المتعلقة بانتهاك حرمة الأسرار التجارية أو بتنفيذ نصوص عقد العمل التى ترمى الى ضمان احترام هذه الأسرار."}, {"number": "699", "chapter": "الفصل الثالث الوكالة", "text": "الوكالة عقد بمقتضاه يلتزم الوكيل بأن يقوم بعمل قانوني لحساب الموكل."}, {"number": "700", "chapter": "الفصل الثالث الوكالة", "text": "يجب أن يتوافر فى الوكالة الشكل الواجب توافره فى العمل القانونى الذى يكون محل الوكالة ، مالم يوجد نص يقضى بغير ذلك."}, {"number": "701", "chapter": "الفصل الثالث الوكالة", "text": "1- الوكالة الواردة فى ألفاظ عامة لا تخصيص فيها حتى لنوع العمل القانونى الحاصل فيه التوكيل، لا تخول الوكيل صفة الا فى أعمال الادارة. 2- ويعد من أعمال الادارة الإيجار اذا لم تزد مدته على ثلاث سنوات وأعمال الحفظ والصيانة واستيفاء الحقوق ووفاء الديون . ويدخل فيها أيضا كل عمل من أعمال التصرف تقتضيه الادارة كبيع المحصول وبيع البضاعة والمنقول الذى يسرع اليه التلف وشراء ما يستلزم الشئ محل الوكالة من أداوت لحفظه ولاستغلاله."}, {"number": "702", "chapter": "الفصل الثالث الوكالة", "text": "1- لا بد من وكالة خاصة فى كل عمل ليس من أعمال الادارة ، وبوجه خاص فى البيع والرهن والتبرعات والصلح والاقرار والتحكيم وتوجيه اليمين والمرافعة أمام القضاء. 2- والوكالة الخاصة فى نوع معين من أنواع الاعمال القانونية تصح ولو لم يعين محل هذا العمل على وجه التخصيص ، الا اذا كان العمل من التبرعات. 3- والوكالة الخاصة لا تجعل للوكيل صفة الا فى مباشرة الأمور المحددة فيها , وما تقتضيه هذه الأمور من توابع ضرورية وفقا لطبيعة كل أمر وللعرف الجارى. 2-اثار الوكالة"}, {"number": "703", "chapter": "الفصل الثالث الوكالة", "text": "1- الوكيل ملزما بتنفيذ الوكالة دون أن يجاوز حدودها المرسومة. 2- على أن له أن يخرج عن هذه الحدود متى كان من المستحيل عليه اخطار الموكل سلفا وكانت الظروف يغلب معها الظن بأن الموكل ما كان الا ليوافق على هذا التصرف. وعلى الوكيل فى هذه الحالة أن يبادر بابلاغ الموكل خروجه عن حدود الوكالة."}, {"number": "704", "chapter": "الفصل الثالث الوكالة", "text": "- 1- اذا كانت الوكالة بلا أجر وجب على الوكيل أن يبذل فى تنفيذها العناية الت يبذلها فى أعماله الخاصة، دون أن يكلف فى ذلك أزيد من عناية الرجل المعتاد. 2- فان كانت بأجر وجب على الوكيل أن يبذل دائما فى تنفيذها عناية الرجل المعتاد."}, {"number": "705", "chapter": "الفصل الثالث الوكالة", "text": "على الوكيل أن يوافى الموكل بالمعلومات الضرورية عما وصل اليه فى تنفيذ الوكالة، وأن يقدم له حسابا عنها"}, {"number": "706", "chapter": "الفصل الثالث الوكالة", "text": "1- ليس للوكيل أن يستعمل مال الموكل لصالح نفسه. 2- وعليه فوائد المبالغ التى استخدمها لصالحه من وقت استخدامها، وعليه أيضا فوائد ما تبقى فى ذمته من حساب الوكالة من وقت أن يعذر."}, {"number": "707", "chapter": "الفصل الثالث الوكالة", "text": "1- اذا تعدد الوكلاء كانوا مسئولين بالتضامن متى كانت الوكالة غير قابلة للانقسام ، أو كان الضرر الذى أصاب الموكل نتيجة خطأ مشترك. على أن الوكلاء ولو كانوا متضامنين لا يسألون عما فعله أحدهم مجاوزا حدود الوكالة أو متعسفا فى تنفيذها. 2- واذا عين الوكلاء فى عقد واحد دون أن يرخص فى انفرادهم فى العمل ، كان عليهم أن يعملوا مجتمعين الا اذا كان العمل مما لايحتاج فيه الى تبادل الرأى كقبض الدين أو وفائه."}, {"number": "708", "chapter": "الفصل الثالث الوكالة", "text": "1- اذا أناب الوكيل عنه غيره فى تنفيذ الوكالة دون أن يكون مرخصا له فى ذلك ، كان مسئولا عن عمل النائب كما لو كان هذا العمل قد صدر منه هو، ويكون الوكيل ونائبه فى هذه الحالة متضامنين فى المسئولية. 2- أما اذا رخص للوكيل فى اقامة نائب عنه دون أن يعين شخص النائب ، فان الوكيل لايكون مسئولا الا عن خطئه فى اختيار نائبه، أو عن خطئه فيما أصدره له من تعليمات. 3- ويجوز فى الحالتين السابقتين للموكل ولنائب الوكيل أن يرجع كل منهما مباشرة على الآخر."}, {"number": "709", "chapter": "الفصل الثالث الوكالة", "text": "- 1- الوكالة تبرعية، ما لم يتفق على غير ذلك صراحة أو يستخلص ضمنا فى حالة الوكيل. 2- فاذا اتفق على أجر للوكالة كان هذا الأجر خاضعا لتقدير القاضى، الا اذا دفع طوعا بعد تنفيذ الوكالة."}, {"number": "710", "chapter": "الفصل الثالث الوكالة", "text": "على الموكل أن يرد للوكيل ما أنفقه فى تنفيذ الوكالة التنفيذ المعتاد مع الفوائد من وقت الاتفاق وذلك مهما كان حظ الوكيل من النجاح فى تنفيذ الوكالة . فاذا اقتضى تنفيذ الوكالة أن يقدم الموكل للوكيل مبالغ للانفاق منها فى شئون الوكالة، وجب على الموكل أن يقدم هذه المبالغ اذا طلب الوكيل ذلك."}, {"number": "711", "chapter": "الفصل الثالث الوكالة", "text": "يكون الموكل مسئولا عما أصاب الوكيل من ضرر دون خطأ منه بسبب تنفيذ الموكالة تنفيذا معتادا."}, {"number": "712", "chapter": "الفصل الثالث الوكالة", "text": "------- اذا وكل أشخاص متعددون وكيلا واحدا فى عمل مشترك كان جميع الموكلين متضامنين قبل الوكيل فى تنفيذ الوكالة مالم يتفق على غير ذلك."}, {"number": "713", "chapter": "الفصل الثالث الوكالة", "text": "تطبق المواد من 104 الى 107 الخاصة بالنيابة فى علاقة الموكل والوكيل بالغير الذى يتعامل مع الوكيل. 4- إنتهاء الوكالة"}, {"number": "714", "chapter": "الفصل الثالث الوكالة", "text": "تنتهى الوكالة باتمام العمل الموكل فيه أو بانتهاء الأجل المعين للوكالة وتنتهى أيضا بموت الموكل أو الوكيل."}, {"number": "715", "chapter": "الفصل الثالث الوكالة", "text": "1- يجوز للموكل فى أى وقت أن ينهى الوكالة أو يقيدها ولو وجد اتفاق يخالف ذلك . فاذا كانت الوكالة بأجر فان الموكل يكون ملزما بتعويض الوكيل عن الضرر الذى لحقه من جراء عزله فى وقت غير مناسب أو بغير عذر مقبول. 2- على أنه اذا كانت الوكالة صادرة لصالح الوكيل أو لصالح أجنبى فلا يجوز للموكل أن ينهى الوكالة أو يقيدها دون رضاء من صدرت الوكالة لصالحه."}, {"number": "716", "chapter": "الفصل الثالث الوكالة", "text": "------- 1- يجوز للوكيل أن ينزل فى أى وقت عن الوكالة ولو وجد اتفاق يخالف ذلك، ويتم التنازل باعلانه للموكل. فاذا كانت الوكالة بأجر فان الوكيل يكون ملزما بتعويض الموكل عن الضرر الذى لحقه من جراء التنازل فى وقت غير مناسب وبغير عذر مقبول. 2- غير أنه لايجوز للوكيل أن ينزل عن الوكالة متى كانت صادرة لصالح أجنبى الا اذا وجدت أسباب جدية تبرر ذلك على ان يخطر الأجنبى بهذا التنازل، وأن يمهله وقتا كافيا ليتخذ ما يلزم لصيانة مصالحه."}, {"number": "717", "chapter": "الفصل الثالث الوكالة", "text": "1- على أى وجه كان انتهاء الوكالة ، يجب على الوكيل أن يصل بالأعمال التى بدأها الى حالة لاتتعرض معها للتلف. 2- وفى حالة انتهاء الوكالة بموت الوكيل يجب على ورثته ، اذا توافرت فيهم الأهلية وكانوا على علم بالوكالة ، أن يبادروا الى اخطار الموكل بموت مورثهم وأن يتخذوا من التدبيرات ما تقتضيه الحال لصالح الموكل."}, {"number": "718", "chapter": "الفصل الرابع", "text": "الوديعة عقد يلتزم به شخص أن يتسلم شيئا من آخر على أن يتولى حفظ هذا الشئ وعلى أن يرده عينا. 1- إلتزامات المودع عنده"}, {"number": "719", "chapter": "الفصل الرابع", "text": "1- على المودع عنده أن يتسلم الوديعة . 2- وليس له أن يستعملها دون أن يأذن له المودع فى ذلك صراحة أو ضمنا ."}, {"number": "720", "chapter": "الفصل الرابع", "text": "1- اذا كانت الوديعة بغير أجر وجب على المودع عنده أن يبذل من العناية فى حفظ الشئ مايبذله فى حظ ماله ، دون أن يكلف فى ذلك أزيد من عناية الرجل المعتاد . 2- أما اذا كانت الوديعة بأجر فيجب أن يبذل فى حفظ الوديعة عناية الرجل المعتاد ."}, {"number": "721", "chapter": "الفصل الرابع", "text": "ليس للمودع عنده أن يحل غيره محله فى حفظ الوديعة دون اذن صريح من المودع الا أن يكون مضطرا الى ذلك بسبب ضرورة ملجئة عاجلة."}, {"number": "722", "chapter": "الفصل الرابع", "text": "يجب على المودع عنده أن يسلم الشئ الى المودع بمجرد طلبه الا اذا ظهر من العقد أن الأجل عين لمصلحة المودع عنده. وللمودع عنده أن يلزم المودع بتسليم الشئ فى أى وقت ، الا اذا ظهر من العقد أن الأجل عين لمصلحة المودع."}, {"number": "723", "chapter": "الفصل الرابع", "text": "اذا باع وارث المودع عنده الشئ المودع وهو حسن النية، فليس عليه لمالكه الا رد ما قبضه من الثمن ، أو التنازل له عن حقوقه على المشترى . وأما اذا تصرف فيه تبرعا فانه يلتزم بقيمته وقت التبرع. 2- إلتزامات المودع"}, {"number": "724", "chapter": "الفصل الرابع", "text": "الأصل فى الوديعة أن يكون بغير أجر ، فاذا اتفق عل أجر وجب على المودع أن يؤديه وقت انتهاء الوديعة ، ما لم يوجد اتفاق يقضى بغير ذلك."}, {"number": "725", "chapter": "الفصل الرابع", "text": "- على المودع أن يرد الى المودع عنده ما أنفقه فى حفظ الشئ ، وعليه أن يعوضه عن كل ما لحقه من خسارة بسبب الوديعة. إلتزامات المودع عنده"}, {"number": "726", "chapter": "الفصل الرابع", "text": "اذا كانت الوديعة مبلغا من النقود أو أى شئ آخر مما يهلك بالاستعمال ، وكان المودع عنده مأذونا له فى استعماله اعتبر العقد قرضا."}, {"number": "727", "chapter": "الفصل الرابع", "text": "1- يكون أصحاب الفنادق والخانات وما ماثلها فيما يجب عليهم من عناية بحفظ الأشياء التى يأتى بها المسافرين والنزلاء مسئولين حتى عن فعل المترددين على الفندق أو الخان. 2- غير أنهم لا يكونون مسئولين فيما يتعلق بالنقود والأوراق المالية والاشياء الثمينة عن تعويض يجاوز خمسين جنيها، ما لم يكونوا قد أخذوا على عاتقهم حفظ هذه الأشياء وهم يعرفون قيمتها ، أو يكونوا قد رفضوا دون مسوغ أن يتسلموها عهدة فى ذمتهم ، أو يكونوا قد تسببوا فى وقوع الضرر بخطأ جسيم منهم أو من أحد تابعيهم."}, {"number": "728", "chapter": "الفصل الرابع", "text": "1- على المسافر ان يخطر صاحب الفندق او الخان بسرقة الشئ او ضياعه او تلفه بمجرد علمه بوقوع شئ من ذلك فان أبطأ فى الاخطار دون مسوغ سقطت حقوقه . 2- وتسقط بالتقادم دعوى المسافر قبل صاحب الفندق او الخان بانقضاء سته أشهر من اليوم الذى يغادر فيه الفندق او الخان ."}, {"number": "729", "chapter": "الفصل الخامس الحراسة", "text": "الحراسة عقد يعهد الطرفان بمقتضاه الى شخص آخر بمنقول أو عقار أو مجموع من المال يقوم فى شأنه نزاع أو يكون الحق فيه غير ثابت، فيتكفل هذا الشخص بحفظه وبادارته وبرده مع غلته المقبوضة الى من يثبت له الحق فيه."}, {"number": "730", "chapter": "الفصل الخامس الحراسة", "text": "يجوز للقضاء أن يأمر بالحراسة: 1- فى الأحوال المشار اليها فى المادة السابقة اذا لم يتفق ذوو الشأن على الحراسة. 2- اذا كان صاحب المصلحة فى منقول أو عقار قد تجمع لديه من الأسباب المعقولة ما يخشى معه خطرا عاجلا من بقاء المال تحت يد حائزه. 3- فى الأحوال الأخرى المنصوص عليها فى القانون."}, {"number": "731", "chapter": "الفصل الخامس الحراسة", "text": "------- تجوز الحراسة القضائية على الاموال الموقوفة فى الاحوال الآتية: 1- اذا كان الوقف شاغرا أو قام نزاع بين نظارة أو نزاع من أشخاص يدعون حق النظر عليه أو كانت هناك دعوى مرفوعة بعزل الناظر، وكل هذه اذا تبين أن الحراسة اجراء لا بد منه للمحافظة عل ما قد يكون لذوى الشأن من الحقوق . وتنتهى الحراسة فى هذا الأحوال اذا عين ناظر على الوقف سواء أكان بصفة مؤقتة أم كان بصفة نهائية. 2- اذا كان الوقف مدينا. 3- اذا كان أحد المستحقين مدينا معسرا، وتكون الحراسة على حصته وحدها أن أمكن فرزها ولو بقسمة مؤقتة ، والا فعلى الوقف كله ويشترط أن تكون الحراسة فى الحالين هى الوسيلة الوحيدة لعدم ضياع حقوق الدائنين بسبب سوء ادارة الناظر أو سوء نيته."}, {"number": "732", "chapter": "الفصل الخامس الحراسة", "text": "يكون تعيين الحارس سواء أكانت الحراسة اتفاقية أم كانت قضائية باتفاق ذوى الشأن جميعا، فاذا لم يتفقوا تولى القاضى تعيينه."}, {"number": "733", "chapter": "الفصل الخامس الحراسة", "text": "يحدد الاتفاق أو الحكم القاضى بالحراسة ما على الحارس من التزامات وماله من حقوق وسلطة، والا فتطبق أحكام الوديعة وأحكام الوكالة بالقدر الذى لاتتعارض فيه مع الاحكام الآتية:"}, {"number": "734", "chapter": "الفصل الخامس الحراسة", "text": "1- يلتزم الحارس بالمحافظة على الأموال المعهودة اليه حراستها وبادارة هذه الاموال ، ويجب أن يبذل فى كل ذلك عناية الرجل المعتاد. 2- ولايجوز له بطريق مباشر أو غير مباشر أن يحل محله فى أداء مهمته كلها أو بعضها أحد ذوى الشأن دون رضاء الآخرين."}, {"number": "735", "chapter": "الفصل الخامس الحراسة", "text": "لايجوز للحارس فى غير أعمال الادارة أن يتصرف الا برضاء ذوى الشأن جميعا أو بترخيص من القضاء."}, {"number": "736", "chapter": "الفصل الخامس الحراسة", "text": "للحارس أن يتقاضى أجرا ما لم يكن قد نزل عنه."}, {"number": "737", "chapter": "الفصل الخامس الحراسة", "text": "1- يلتزم الحارس باتخاذ دفاتر حساب منظمة ويجوز للقاضى الزامه باتخاذ دفاتر موقع عليها من المحكمة. 2- ويلتزم أن يقدم لذوى الشأن كل سنة على الأكثر حسابا بما تسلمه وبما أنفقه ، معززا بما يثبت ذلك من مستندات. واذا كان الحارس قد عينته المحكمة وجب عليه فوق ذلك أن يودع صورة من هذا الحساب قلم كتابها."}, {"number": "738", "chapter": "الفصل الخامس الحراسة", "text": "------- 1- تنتهى الحراسة باتفاق ذوو الشأن جميعا أو بحكم القضاء. 2- وعلى الحارس حينئذ أن يبادر الى رد الشئ المعهود اليه حراسته الى من يختاره ذوو الشأن أو من يعينه القاضى."}, {"number": "739", "chapter": "الفصل الأول", "text": "1- يكون باطلا كل اتفاق خاص بمقامرة أو رهان. 2- ولمن خسر فى مقامرة أو رهان أن يسترد ما دفعه خلال ثلاث سنوات من الوقت الذى أدى فيه ما خسره ولو كان هناك اتفاق يقضى بغير ذلك وله أن يثبت ما أداه بجميع الطرق."}, {"number": "740", "chapter": "الفصل الأول", "text": "1- يستثنى من أحكام المادة السابقة الرهان الذى يعقده فيما بينهم المتبارون شخصيا فى الألعاب الرياضية.ولكن للقاضى أن يخفض قيمة هذا الرهان اذا كان مبالغا فيه. 2- ويستثنى أيضا ما رخص فيه قانون من أوراق النصيب."}, {"number": "741", "chapter": "الفصل الثانى", "text": "1- يجوز للشخص أن يلتزم بأن يؤدى الى شخص آخر مرتبا دوريا مدى الحياة بعوض أو بغير عوض. 2- ويكون هذا الالتزام بعقد أو بوصية."}, {"number": "742", "chapter": "الفصل الثانى", "text": "1- يجوز أن يكون المرتب مقررا مدى حياة الملتزم له أو مدى حياة الملتزم أو مدى حياة شخص آخر. 2- ويعتبر المرتب مقررا مدى حياة الملتزم له اذا لم يوجد اتفاق يقضى بغير ذلك."}, {"number": "743", "chapter": "الفصل الثانى", "text": "العقد الذى يقرر المرتب لا يكون صحيحا الا اذا كان مكتوبا ، وهذا دون اخلال بما يتطلبه القانون من شكل خاص لعقود التبرع."}, {"number": "744", "chapter": "الفصل الثانى", "text": "- لايصح أن يشترط عدم جواز الحجز على المرتب الا اذا كان قد قرر على سبيل التبرع."}, {"number": "745", "chapter": "الفصل الثانى", "text": "------- 1- لايكون للمستحق حق فى المرتب الا عن الأيام التى عاشها من قرر المرتب مدى حياته. 2- على أنه اذا اشترط الدفع مقدما كان للمستحق حق فى القسط الذى حل."}, {"number": "746", "chapter": "الفصل الثانى", "text": "اذا لم يقم المدين بالتزامه كان للمستحق أن يطلب تنفيذ العقد ، فان كان العقد بعوض جاز له أيضا أن يطلب فسخه مع التعويض ان كان له محل."}, {"number": "747", "chapter": "الفصل الثالث", "text": "------- التأمين عقد يلتزم المؤمن بمقتضاه أن يؤدى الى المؤمن له أو الى المستفيد الذى اشترط التأمين لصالحه مبلغا من المال أو ايرادا مرتبا أو أى عوض مالى آخر فى حالة وقوع الحادث أوتحقق الخطر المبين بالعقد وذلك فى نظير قسط أو أية دفعة مالية أخرى يؤديها المؤمن له للمؤمن."}, {"number": "748", "chapter": "الفصل الثالث", "text": "الأحكام المتعلقة بعقد التأمين التى لم يرد ذكرها فى هذ القانون تنظمها القوانين الخاصة."}, {"number": "749", "chapter": "الفصل الثالث", "text": "يكون محلا للتأمين كل مصلحة اقتصادية مشروعة تعود على الشخص من عدم وقوع خطر معين ."}, {"number": "750", "chapter": "الفصل الثالث", "text": "------- يقع باطلا مايرد فى وثيقة التأمين من الشروط الأتية: 1- الشرط الذى يقضى بسقوط الحق فى التأمين بسبب مخالفة القوانين واللوائح ، الا اذا انطوت هذه المخالفة على جناية أوجنجة عمدية. 2- الشرط الذى يقضى بسقوط حق المؤمن له بسبب تأخره فى اعلان الحادث المؤمن منه الى السلطات أو فى تقديم المستندات اذا تبين من الظروف أن التأخر كان لعذر مقبول. 3- كل شرط مطبوع لم يبرز بشكل ظاهر وكان متعلقا بحالة من الأحوال التى تؤدى الى البطلان أو السقوط. 4- شرط التحكيم اذا ورد فى الوثيقة بين شروطها العامة المطبوعة لا فى صورة اتفاق خاص منفصل عن الشروط العامة. 5- كل شرط تعسفى آخر يتبين أنه لم يكن لمخالفته أثر فى وقوع الحادث المؤمن منه.."}, {"number": "751", "chapter": "الفصل الثالث", "text": "لايلتزم المؤمن فى تعويض المؤمن له الا عن الضرر الناتج من وقوع الخطر المؤمن منه بشرط الايجاوز ذلك قيمة التأمين."}, {"number": "752", "chapter": "الفصل الثالث", "text": "1- تسقط بالتقادم الدعاوى الناشئة عن عقد التأمين بانقضاء ثلاث سنوات من وقت حدوث الواقعة التى تولدت عنها هذه الدعاوى. 2- ومع ذلك لاتسرى هذه المدة: (أ) فى حالة اخفاء بيانات متعلقة بالخطر المؤمن منه ، أو تقديم بيانات غير صحيحة أو غير دقيقة عن هذا الخطر الا من اليوم الذى علم فيه المؤمن بذلك. (ب) فى حالة وقوع الحادث المؤمن منه الا من اليوم الذى علم فيه ذوو الشأن بوقوعه.."}, {"number": "753", "chapter": "الفصل الثالث", "text": "يقع باطلا كل اتفاق يخالف أحكام النصوص الواردة فى هذا الفصل ، الا أن يكون ذلك لمصلحة المؤمن له او لمصلحة المستفيد.. 2-بعض أنواع التأمين التأمين على الحياه"}, {"number": "754", "chapter": "الفصل الثالث", "text": "المبالغ التى يلزم المؤمن فى التأمين على الحياة بدفعها الى المؤمن له أو الى المستفيد عند وقوع الحادث المؤمن منه أو حلول الأجل المنصوص عليه فى وثيقة التأمين ، تصبح مستحقة من وقت وقوع الحادث أو وقت حلول الأجل دون حاجة الى اثبات ضرر أصاب المؤمن له أو أصاب المستفيد"}, {"number": "755", "chapter": "الفصل الثالث", "text": "------- 1- يقع باطلا التأمين على حياة الغير ما لم يوافق الغير عليه كتابة قبل ابرام العقد . فاذا كان هذا الغير لا تتوافر فيه الأهلية فلا يكون العقد صحيحا الا بموافقة من يمثله قانونا. 2- وتكون هذه الموافقة لازمة لصحة حوالة الحق فى الاستفادة من التأمين أو لصحة رهن هذا الحق."}, {"number": "756", "chapter": "الفصل الثالث", "text": "1- تبرأ ذمة المؤمن من التزامه بدفع مبلغ التأمين اذا انتحر الشخص المؤمن على حياته. ومع ذلك يلتزم المؤمن أن يدفع لم يؤول اليهم الحق مبلغا يساوى قيمة احتياطى التأمين. 2- فاذ كان سبب الانتحار مرضا أفقد المريض ارادته ، بقى التزام المؤمن قائما بأكمله. وعلى المؤمن أن يثبت أن المؤمن على حياته مات منتحرا. وعلى المستفيد أن يثبت أن المؤمن على حياته كان وقت انتحاره فاقدا الارادة. 3- واذا اشتملت وثيقة التأمين على شرط يلزم المؤمن بدفع مبلغ التأمين ولو كان انتحار الشخص عن اختيار وادراك، فلا يكون هذا الشرط نافذا الا اذا وقع الانتحار بعد سنتين من تاريخ العقد."}, {"number": "757", "chapter": "الفصل الثالث", "text": "1- اذا كان التأمين على حياة شخص غير المؤمن له برئت ذمة المؤمن من التزاماته متى تسبب المومن له عمدا فى وفاة ذلك الشخص ، أو وقعت الوفاة بناء على تحريض منه. 2- واذا كان التامين على الحياة لصالح شخص غير المؤمن له فلا يستفيد هذا الشخص من التأمين اذا تسبب عمدا فى وفاة الشخص المؤمن على حياته، أو وقعت الوفاة بناء على تحريض منه . فاذا كان ما وقع من هذا الشخص مجرد شروع فى احداث الوفاة ، كان للمؤمن له الحق فى أن يستبدل بالمستفيد شخصا آخر ، ولو كان المستفيد قد قبل ما اشترط لمصلحته من تأمين"}, {"number": "758", "chapter": "الفصل الثالث", "text": "1- يجوز فى التأمين على الحياة الاتفاق على أن يدفع مبلغ التأمين ، أما الى أشخاص معينين، واما الى أشخاص يعينهم المؤمن له فيما بعد. 2- ويعتبر التأمين معقودا لمصلحة مستفيدين معينين اذا ذكر المؤمن له فى الوثيقة أن التأمين معقود لمصلحة زوجة أو أولاده أو فروعه من ولد منهم، ومن لم يولد ، أو لورثته دون ذكر أسمائهم. فاذا كان التأمين لصالح الورثة دون ذكر أسمائهم كان لهؤلاء الحق فى مبلغ التأمين كل بنسبة نصيبه فى الميراث. ويثبت لهم هذا الحق ولو نزلوا عن الارث. 3- ويقصد بالزوج الشخص الذى يثبت له هذه الصفة وقت وفاة المؤمن له ، ويقصد بالأولاد الفروع الذين يثبت لهم فى ذلك الوقت حق الأرث.."}, {"number": "759", "chapter": "الفصل الثالث", "text": "يجوز للمؤمن له الذى التزم بدفع اقساط دورية ، أن يتحلل فى أى وقت من العقد باخطار كتابى يرسله الى المؤمن قبل انتهاء الفترة الجارية ، وفى هذه الحالة تبرأ ذمته من الأقساط اللاحقة."}, {"number": "760", "chapter": "الفصل الثالث", "text": "- 1- فى العقود المبرمة مدى الحياة دون اشتراط بقاء المؤمن على حياته مدة معينة ، وفى جميع العقود المشترط فيها دفع مبلغ التأمين بعد عدد معين من السنين، يجوز للمؤمن له متى كان قد دفع ثلاثة أقساط سنوية على الأقل أن يستبدل بالوثيقة الاصلية وثيقة مدفوعة فى مقابل تخفيض فى قيمة مبلغ التأمين ولو اتفق على غير ذلك . كل هذا بشرط أن يكون الحادث المؤمن منه محقق الوقوع. 2- ولا يكون قابلا للتخفيض التأمين على الحياة اذا كان مؤقتا."}, {"number": "761", "chapter": "الفصل الثالث", "text": "- اذا خفض التأمين فلا يجوز أن ينزل عن الحدود الآتية: (أ) فى العقود المبرمة مدى الحياة لايجوز أن يقل مبلغ التأمين المخفض عن القيمة التى كان يستحقها المؤمن له لو كان قد دفع ما يعادل احتياطى التأمين فى تاريخ التخفيض مخصوما منه 1% من مبلغ التأمين الأصلى ، باعتبار أن هذا المبلغ من ذات النوع وطبقا لتعريفة التأمين التى كانت مرعية فى عقد التأمين الأصلى. (ب) فى العقود المتفق فيها على مبلغ التأمين بعد عدد معين من السنين، لايجوز أن يقل مبلغ التأمين المخفض عن جزء من مبلغ التأمين الأصلى بنسبة ما دفع من أقساط."}, {"number": "762", "chapter": "الفصل الثالث", "text": "------- 1- يجوز أيضا للمؤمن له، متى كان قد دفع ثلاثة أقساط سنوية على الأقل ، أن يصفى التأمين بشرط أن يكون الحادث المؤمن منه محقق الوقوع. 2- ولا يكون قابلا للتصفية ، التأمين على الحياة اذا كان مؤقتا."}, {"number": "763", "chapter": "الفصل الثالث", "text": "تعتبر شروط التخفيض والتصفية جزاء من الشروط العامة للتأمين ويجب أن تذكر فى وثيقة التأمين."}, {"number": "764", "chapter": "الفصل الثالث", "text": "-- 1- لايترتب على البيانات الخاطئة ولا على الغلط فى سن الشخص الذى عقد التأمين عل حياته بطلان التأمين ، الا اذا كانت السن الحقيقية للمؤمن عليه تجاوز الحد المعين الذى نصت علية تعريفة التأمين. 2- وفى غير ذلك من الأحوال ، اذا ترتب على البيانات الخاطئة أو الغلط، أن القسط المتفق عليه أقل من القسط الذى كان يجب أداؤه، وج تخفيض مبلغ التأمين بما يتعادل مع النسبة بين القسط المتفق عليه والقسط الواجب أداؤه على أساس السن الحقيقة. 3- أما اذا كان القسط المتفق على دفعه أكبر مما كان يجب دفعه على أساس السن الحقيقية للمؤمن على حياته، وجب على المؤمن أن يرد دون فوائد ، الزيادة التى حصل عليها ، وأن يخفض الأقساط التالية الى الحد الذى يتناسب مع السن الحقيقية للمؤمن عليه."}, {"number": "765", "chapter": "الفصل الثالث", "text": "------- فى التأمين على الحياة لايكون للمؤمن الذى دفع مبلغ التأمين حق فى الحلول محل المؤمن له أو المستفيد فى حقوقه قبل من تسبب فى الحادث المؤمن منه أو قبل المسئول عن هذا الحادث. التأمين من الحريق"}, {"number": "766", "chapter": "الفصل الثالث", "text": "1- فى التامين من الحريق يكون المؤمن مسئولا عن كافة الأضرار الناشئة عن حريق ، أو عن بداية حريق يمكن أن تصبح حريقا كاملا ، أو عن خطر حريق يمكن أن يتحقق. 2- ولا يقتصر التزامه على الأضرار الناشئة مباشرة عن الحريق، بل يتناول أيضا الأضرار التى تكون نتيجة حتمية لذلك ، وبالأخص مايلحق الأشياء المؤمن عليه من ضرر بسبب اتخاذ وسائل الانقاذ أو لمنع امتداد الحريق. 3- ويكون مسئولا عن ضياع الأشياء المؤمن عليها واختفائها أثناء الحريق مالم يثبت أن ذلك كان نتيجة سرقة، كل هذا ولو أتفق على غيره."}, {"number": "767", "chapter": "الفصل الثالث", "text": "يضمن المؤمن تعويض الاضرار الناجمة عن الحريق ولو نشأ هذا الحريق عن عيب فى الشئ المؤمن عليه."}, {"number": "768", "chapter": "الفصل الثالث", "text": "1- يكون المؤمن مسئولا عن الأضرار الناشئة عن خطأ المؤمن له غير المتعمد. وكذلك يكون مسئولا عن الأضرار الناجمة من حادث مفاجئ أو قوة قاهرة. 2- أما الخسائروالأضرار التى يحدثها المؤمن له عمدا أو غشا، فلا يكون المؤمن مسئولا عنها ولو اتفق على غير ذلك."}, {"number": "769", "chapter": "الفصل الثالث", "text": "يسأل المؤمن عن الأضرار التى تسبب فيها الأشخاص الذين يكون المؤمن له مسئولا عنهم ، مهما يكون نوع خطئهم ومداه."}, {"number": "770", "chapter": "الفصل الثالث", "text": "1- اذا كان الشئ المؤمن عليه مثقلا برهن حيازى أو رهن تأمينى أو غير ذلك من التامينات العينية ، انتقلت هذه الحقوق الى التعويض المستحق للمدين بمقتضى عقد التأمين. 2- فاذا شهرت هذه الحقوق أو أعلنت الى المؤمن ولو بكتاب موصى عليه ، فلا يجوز له ان يدفع ما فى ذمته للمؤمن له الا برضاء الدائنين. 3- فاذا حجز على الشئ المؤمن عليه أو وضع هذا الشئ تحت الحراسة ، فلا يجوز للمؤمن اذا أعلن بذلك على الوجه المبين فى الفقرة السابقة أن يدفع للمؤمن له شيئا مما فى ذمته."}, {"number": "771", "chapter": "الفصل الثالث", "text": "يحل المؤمن قانونا بما دفعه من تعويض عن الحريق فى الدعاوى التى تكون للمؤمن له قبل من تسبب بفعله فى الضرر الذى نجمت عنه مسئولية المؤمن ، مالم يكن من أحداث الضرر قريبا أو صهرا للمؤمن له ممن يكونون معه فى معيشة واحدة ، أو شخصا يكون المؤمن له مسئولا عن أفعاله. الكفالة"}, {"number": "772", "chapter": "الفصل الأول أركان الكفالة", "text": "الكفالة عقد بمقتضاه يكفل شخص تنفيذ التزام بأن يتعهد للدائن بأن يفى بهذا الالتزام اذا لم يف به المدين نفسه."}, {"number": "773", "chapter": "الفصل الأول أركان الكفالة", "text": "لاتثبت الكفالة الا بالكتابة ، ولو كان من الجائز اثبات الالتزام الأصلى بالبينة"}, {"number": "774", "chapter": "الفصل الأول أركان الكفالة", "text": "- اذا التزم المدين بتقديم كفيل ، وجب أن يقدم شخصا موسرا ومقيما فى مصر ،وله ان يقدم عوضا عن الكفيل ، تأمينا عينيا كافيا."}, {"number": "775", "chapter": "الفصل الأول أركان الكفالة", "text": "تجوز كفالة المدين بغير علمه، وتجوز أيضا رغم معارضته."}, {"number": "776", "chapter": "الفصل الأول أركان الكفالة", "text": "لاتكون الكفالة صحيحة الا اذا كان الالتزام المكفول صحيحا."}, {"number": "777", "chapter": "الفصل الأول أركان الكفالة", "text": "من كفل التزام ناقص الأهلية وكانت الكفالة بسبب نقص الأهلية ، كان ملزما بتنفيذ الالتزام اذا لم ينفذه المدين المكفول."}, {"number": "778", "chapter": "الفصل الأول أركان الكفالة", "text": "1- تجوز الكفالة فى الدين المستقبل اذا حدد مقدما المبلغ المكفول ، كما تجوز الكفالة فى الدين الشرطى. 2- على أنه اذا كان الكفيل فى الدين المستقبل لم يعن مدة للكفالة كان له فى أى وقت أن يرجع فيها ما دام الدين المكفول لم ينشأ."}, {"number": "779", "chapter": "الفصل الأول أركان الكفالة", "text": "------- 1- كفالة الدين التجارى تعتبر عملا مدنيا ولو كان الكفيل تاجرا. 2- على أن الكفالة الناشئة عن ضمان الأوراق التجارية ضمانا احتياطيا أو تظهير هذه الأوراق ، تعتبر دائما عملا تجاريا."}, {"number": "780", "chapter": "الفصل الأول أركان الكفالة", "text": "1- لا تجوز الكفالة فى مبلغ أكبر مما هو مستحق على المدين ، ولابشرط أشد من شروط الدين المكفول. 2- ولكن تجوز الكفالة فى مبلغ أقل وبشروط أهون ."}, {"number": "781", "chapter": "الفصل الأول أركان الكفالة", "text": "اذا لم يكن هناك اتفاق خاص ، فان الكفالة تشمل ملحقات الدين ، ومصروفات المطالبة الأولى، وما يستجد من المصروفات بعد اخطار الكفيل."}, {"number": "782", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- يبرأ الكفيل بمجرد براءة المدين ، وله أن يتمسك بجميع الأوجه التى يحتج بها المدين. 2- على أنه اذا كان الوجه الذى يحتج به المدين هونقص أهليته وكان الكفيل عالما بذلك وقت التعاقد ، فليس له ان يحتج بهذا الوجه."}, {"number": "783", "chapter": "الفصل الثانى أثار الكفالة", "text": "اذا قبل الدائن أن يستوفى فى مقابل الدين شيئا آخر برئت ذمة الكفيل ولو استحق هذا الشئ."}, {"number": "784", "chapter": "الفصل الثانى أثار الكفالة", "text": "- 1- تبرأ ذمة الكفيل بقدر ما أضاعه الدائن بخطئه من الضمانات. 2- ويقصد بالضمانات فى هذه المادة كل تأمين يخصص لضمان الدين ولو تقرر بعد الكفالة ، وكان تأمين مقرر بحكم القانون."}, {"number": "785", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- لاتبرأ ذمة الكفيل لمجرد أن الدائن تأخر فى اتخاذ الاجراءات أو لمجرد أنه لم يتخذها. 2- على أن ذمة الكفيل تبرأ اذا لم يقم الدائن باتخاذ ، مالم يقدم المدين للكفيل ضمانا كافيا."}, {"number": "786", "chapter": "الفصل الثانى أثار الكفالة", "text": "اذا أفلس المدين وجب عل الدائن أن يتقدم فى التفليسة بالدين، والا سقط حقه فى الرجوع على الكفيل بقدر ما أصاب هذا الاخير من ضرر بسبب اهمال الدائن."}, {"number": "787", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- يلتزم الدائن بأن يسلم الكفيل وقت وفائه الدين المستندات اللازمة لاستعمال حقه فى الرجوع. 2- فاذا كان الدين مضمونا بمنقول مرهون أو محبوس ، وجب على الدائن أن يتخلى عنه للكفيل. 3- أما اذا كان الدين مضمونا بتأمين عقارى ، فان الدائن يلتزم أن يقوم بالاجراءات اللازمة لنقل التأمين ، ويتحمل الكفيل مصروفات النقل على أن يرجع بها على المدين."}, {"number": "788", "chapter": "الفصل الثانى أثار الكفالة", "text": "1-لايجوز للدائن أن يرجع على الكفيل وحده الابعد رجوعه على المدين. 2- ولايجوز له أن ينفذ على أموال الكفيل الا بعد تجريده المدين من أمواله، ويجب على الكفيل فى هذه الحالة أن يتمسك بهذا الحق."}, {"number": "789", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- اذا طلب الكفيل التجريد ، وجب عليه ان يقوم على نفقته بارشاد الدائن الى أموال للمدين تفى بالدين كله. 2- ولاعبرة بالأموال التى يدل عليها الكفيل ، اذا كانت هذه الأموال تقع خارج الأراضى المصرية ، أو كانت أموالا متنازعا فيها."}, {"number": "790", "chapter": "الفصل الثانى أثار الكفالة", "text": "فى كل الأحوال التى يدل فيها الكفيل على أموال المدين ، يكون الدائن مسئولا قبل الكفيل عن اعسار المدين الذى يترتب على عدم اتخاذة الاجراءات اللازمة فى الوقت المناسب."}, {"number": "791", "chapter": "الفصل الثانى أثار الكفالة", "text": "اذا كان هناك تأمين عينى خصص قانونا أو اتفاقا لضمان الدين وقدمت كفالة بعد التأمين أومعه ولم يكن الكفيل متضامنا مع المدين ، فلا يجوز التنفيذ على أموال الكفيل الابعد التنفيذ على الأموال التى خصصت لهذا التأمين."}, {"number": "792", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- اذا تعدد الكفلاء لدين واحد وبعقد واحد وكانوا غير متضامنين فيما بينهم ، قسم الدين عليهم ، ولايجوز للدائن أن يطالب كل كفيل الابقدر نصيبه فى الكفالة. 2- أما اذا كان الكفلاء قد التزموا بعقود متوالية ، فان كل واحد منهم يكون مسئولا عن الدين كله ، الا اذا كان قد احتفظ لنفسه بحق التقسيم."}, {"number": "793", "chapter": "الفصل الثانى أثار الكفالة", "text": "لايجوز للكفيل المتضامن مع المدين أن يطلب التجريد."}, {"number": "794", "chapter": "الفصل الثانى أثار الكفالة", "text": "يجوز للكفيل المتضامن أن يتمسك بما يتمسك به الكفيل غير المتضامن من دفوع متعلقة بالدين."}, {"number": "795", "chapter": "الفصل الثانى أثار الكفالة", "text": "فى الكفالة القضائية أو القانوينة يكون الكفلاء دائما متضامنين."}, {"number": "796", "chapter": "الفصل الثانى أثار الكفالة", "text": "اذا كان الكفلاء متضامنين فيما بينهم ووفى أحدهم الدين عند حلوله، كان له أن يرجع على كل من الباقين بحصته فى الدين وبنصيبه فى حصة المعسر منهم."}, {"number": "797", "chapter": "الفصل الثانى أثار الكفالة", "text": "تجوز كفالة الكفيل ، وفى هذه الحالة لايجوز للدائن أن يرجع على كفيل الكفيل قبل رجوعه على الكفيل الا اذا كان كفيل الكفيل متضامنا مع الكفيل. 2-العلاقة مابين الكفيل والمدين"}, {"number": "798", "chapter": "الفصل الثانى أثار الكفالة", "text": "- 1- يجب على الكفيل أن يخطر المدين قبل أن يقوم بوفائه الدين ، والا سقط حقه فى الرجوع على المدين اذا كان هذا قد وفى الدين أو كانت عنده وقت الاستحقاق أسباب تقضى ببطلان الدين أو بانقاضائه. 2- فاذا لم يعارض المدين فى الوفاء بقى للكفيل حقه فى الرجوع عليه ولو كان المدين قد دفع الدين أو كانت لدية أسباب تقضى ببطلانه أو بانقضائه."}, {"number": "799", "chapter": "الفصل الثانى أثار الكفالة", "text": "- اذا وفى الكفيل الدين ، كان له أن يحل محل الدائن فى جميع ماله من حقوق قبل المدين . ولكن اذا لم يوف الا بعض الدين فلا يرجع بما وفاه الا بعد أن يستوفى الدائن كل حقه من المدين."}, {"number": "800", "chapter": "الفصل الثانى أثار الكفالة", "text": "1- للكفيل الذى وفى الدين أن يرجع على المدين سواء كانت الكفالة قد عقدت بعلمه أو بغير علمه. 2- ويرجع بأصل الدين وبالفوائد والمصروفات ، على أنه فى المصروفات لا يرجع الا بالذى دفعه من وقت اخباره المدين الأصلى بالاجراءات التى اتخذت ضده. 3-ويكون للكفيل الحق فى الفوائد القانونية عن كل ما قام بدفعه ابتداء من يوم الدفع."}, {"number": "801", "chapter": "الفصل الثانى أثار الكفالة", "text": "-- اذا تعدد المدينون فى دين واحد وكانوا متضامنين . فللكفيل الذى ضمنهم جميعا أن يرجع على أى منهم بجميع ماوفاه من الدين."}, {"number": "802", "chapter": "الفصل الأول", "text": "لمالك الشئ وحده فى حدود القانون حق استعماله واستغلاله والتصرف فيه."}, {"number": "803", "chapter": "الفصل الأول", "text": "( 1 ) مالك الشئ يملك كل ما يعد من عناصره الجوهرية بحيث لا يمكن فصله عنه دون أن يهلك أو يتلف أو يتغير. ( 2 ) وملكية الأرض تشمل ما فوقها وما تحتها إلى الحد المفيد فى التمتع بها. علوا أو عمقا. ( 3 ) ويجوز بمقتضى القانون أو الاتفاق أو تكون ملكية سطح الأرض منفصلة عن ملكية ما فوقها أو ما تحتها ."}, {"number": "804", "chapter": "الفصل الأول", "text": "لمالك الشئ الحق فى كل ثماره ومنتجاته وملحقاته ما لم يوجد نص أو اتفاق يخالف ذلك."}, {"number": "805", "chapter": "الفصل الأول", "text": "لا يجوز أن يحرم أحد ملكه الا فى الأحوال التى يقررها القانون. وبالطريقة التى يرسمها ، ويكون ذلك فى مقابل تعويض عادل. 2 - القيود التى ترد على حق الملكية"}, {"number": "806", "chapter": "الفصل الأول", "text": "على المالك أن يراعى فى استعمال حقه ما تقضى به القوانين والمراسيم واللوائح المتعلقة بالمصلحة العامة أو المصلحة الخاصة. وعليه أيضا مراعاة الأحكام الآتية :"}, {"number": "807", "chapter": "الفصل الأول", "text": "( 1 ) على المالك الا يغلو فى استعمال حقه إلى حد يضر بملك الجار. ( 2 ) وليس للجار أن يرجع على جاره فى مضار الجوار المألوفة التى لا يمكن تجنبها. وإنما له أن يطلب إزالة مادة المضار إذا جاوزت الحد المألوف. على أن يراعى فى ذلك العرف ، وطبيعة العقارات وموقع كل منها بالنسبة إلى الآخر والغرض أول فى خصصت له. ولا يحول الترخيص الصادر من الجهات المختصة دون استعمال هذا الحق."}, {"number": "808", "chapter": "الفصل الأول", "text": "( 1 ) من أنشأ مسقاة أو مصرفا خصوصيا طبقا للوائح الخاصة بذلك كان له وحده حق استعمالها. ( 2 ) ومع ذلك يجوز للملاك المجاورين أن يستعملوا المسقاة أو المصرف فيما تحتاجه أراضيهم من رى أو صرف ، بعد أن يكون مالك المسقاة أو المصرف قد استوفى حاجته منها. وعلى الملاك المجاورين فى هذه الحالة أن يشتركوا فى نفقات إنشاء المسقاة أو المصرف وصيانتهما بنسبة مساحة أراضيهم التى تنتفع منها."}, {"number": "809", "chapter": "الفصل الأول", "text": "يجب على مالك الأرض أن يسمح بأن تمر بأرضه المياه الكافية لرى الأراضى البعيدة عن مورد المياه ، وكذلك مياه الصرف الآتية من الأراضى المجاورة لتصب فى أقرب مصرف عمومى. بشرط أن يعوض عن ذلك تعويضا عادلا."}, {"number": "810", "chapter": "الفصل الأول", "text": "إذا أصاب ضرر من مسقاة أو مصرف يمر بها ، سواء أكان ذلك ناشئا عن عدم التطهير أم عن سوء حالة الجسور ، فإن لمالك الأرض أن يطلب تعويضا كافيا عما أصابه من ضرر."}, {"number": "811", "chapter": "الفصل الأول", "text": "إذا لم يتفق المنتفعون بمسقاة أو مصرف على القيام بالإصلاحات الضرورية ، جاز إلزامهم بالاشتراك فيها بناء على طلب أى واحد منهم."}, {"number": "812", "chapter": "الفصل الأول", "text": "( 1 ) مالك الأرض المحبوسة عن الطريق العام ، أو التى لا يصلها بهذا الطريق ممر كاف إذا كان لا يتيسر له الوصول إلى ذلك الطريق الا بنفقة باهظة أو مشقة كبيره له حق المرور فى الأراضى المجاورة بالقدر اللازم لاستغلال أرضه واستعمالها على الوجه المألوف مادامت هذه الأرض محبوسة عن الطريق العام. وذلك فى نظير تعويض عادل ، ولا يستعمل هذا الحق الا فى العقار الذى يكون المرور فيه أخف ضررا وفى موضع منه يتحقق فيه ذلك. ( 2 ) على انه اذا كان الحبس عن الطريق العام ناشئا عن تجزئة عقار تمت بناء على تصرف قانونى ، وكان من المستطاع إيجاد ممر كاف فى أجزاء هذا العقار ، فلا يجوز المطالبة بحق المرور الا فى هذه الأجزاء."}, {"number": "813", "chapter": "الفصل الأول", "text": "لكل مالك أن يجبر جاره على وضع حدود لأملاكها المتلاصقة ، وتكون نفقات التحديد شركة بينهما."}, {"number": "814", "chapter": "الفصل الأول", "text": "( 1 ) لمالك الحائط المشترك أن يستعمله بحسب الغرض الذى اعد له ، وان يضع فوقه عوارض ليسند عليها السقف دون أن يحمل الحائط فوق طاقته. ( 2 ) فإذا لم يعد الحائط المشترك صالحا للغرض الذى خصص له عاده فنفقة إصلاحه أو تجديده على الشركاء ، كل بنسبه حصته فيه."}, {"number": "815", "chapter": "الفصل الأول", "text": "( 1 ) للمالك إذا كانت له مصلحة جدية فى تعلية الحائط المشترك أن يعليه ، بشرط الا يلحق بشريكه ضررا بليغا. وعليه وحده أن ينفق على التعلية وصيانة الجزء المعلى ، وعمل ما يلزم لجعل الحائط يتحمل زيادة العبء الناشئ عن التعلية دون أن يفقد شيئا من متانته. ( 2 ) فإذا لم يكن الحائط المشترك صالحا لتحمل التعلية فعلى من يرغب فيها من الشركاء أن يعيد بناء الحائط كله على نفقته ، بحيث يقع ما زاد من سمكه فى ناحيته هو بقدر الاستطاعة ويظل الحائط المحدد فى غير الجزء المعلى مشتركا ، دون أن يكون للجار الذى احدث التعلية حق فى التعويض."}, {"number": "816", "chapter": "الفصل الأول", "text": "للجار الذى لم يساهم فى نفقات التعلية أن يصبح شريكا فى الجزء المعلى إذا هو دفع ما انفق عليه وقيمه نصف الأرض التى تقوم عليها زيادة السمك أن كانت هناك زيادة."}, {"number": "817", "chapter": "الفصل الأول", "text": "الحائط الذى يكون فى وقت إنشائه فاصلا بين بنائين يعد مشتركا حتى مفرقهما ، ما لم يقم دليل على العكس."}, {"number": "818", "chapter": "الفصل الأول", "text": "( 1 ) ليس لجار أن يجبر جاره على تحويط ملكه ولا على النزول عن جزء ، من حائط أو من الأرض التى عليها الحائط الا فى الحالة المذكورة فى المادة 816. ( 2 ) ومع ذلك فليس لمالك الحائط أن يهدمه مختارا دون عذر قوى أن كان هذا يضر الجار الذى يستتر ملكه بالحائط."}, {"number": "819", "chapter": "الفصل الأول", "text": "( 1 ) لا يجوز للجار أن يكون له على جاز مطل مواجه على مسافة تقل عن متر ، وتقاس المسافة من ظهر الحائط الذى فيه المطل ، أو من حافة المشربة أو الخارجة. ( 2 ) وإذا كسب أحد بالتقادم الحق فى مطل مواجه لملك الجار على مسافة تقل عن متر ، فلا يحق لهذا الجار أن يبنى على أقل من متر يقاس بالطريقة السابق بيانها ، وذلك على طول البناء الذى فتح فيه المطل :"}, {"number": "820", "chapter": "الفصل الأول", "text": "لا يجوز أن يكون للجار على جاره مطل منحرف على مسافة تقل عن خمسين سنتيمترا من حرف المطل ، ولكن يرتفع هذا الحظر إذا كان المطل المنحرف على العقار المجاور هو فى الوقت ذاته ماثل مواجه للطريق العام."}, {"number": "821", "chapter": "الفصل الأول", "text": "لا تشترط أية مسافة لفتح المناور. وهى التى تعلو قاعدتها عن قامة الانسان المعتادة ولا يقصد بها الا مرور الهواء ، ونفاذ النور ، دون أن يستطاع الإطلال منها على العقار المجاور."}, {"number": "822", "chapter": "الفصل الأول", "text": "المصانع والآبار والآلات البخارية وجميع المحال المضرة بالجيران يجب أن تنشأ على المسافات المبينة فى اللوائح وبالشروط التى تفرضها."}, {"number": "823", "chapter": "الفصل الأول", "text": "( 1 ) إذا تضمن العقد أو الوصية شرطا يقضى بمنع التصرف فى مال ، فلا يصح هذا الشرط ما لم يكن مبنيا على باعث مشروع ، ومقصورا على مدة معقولة. ( 2 ) ويكون الباعث مشروعا متى كان المواد بالمنع مع التصرف حماية مصلحة مشروعة للمتصرف أو للمتصرف إليه أو الغير. ( 3 ) والمدة المعقولة يجوز أن تستغرق مدى حياة المتصرف أو المتصرف إليه أو الغير."}, {"number": "824", "chapter": "الفصل الأول", "text": "إذا كان شرط المنع من التصرف الوارد فى العقد أو الوصية صحيحا طبقا لأحكام المادة السابقة ، فكل تصوت مخالف له يقع باطلا. الملكية الشائعة أحكام الشيوع :"}, {"number": "825", "chapter": "الفصل الأول", "text": "إذا ملك اثنان أو أكثر شيئا غير مفرزة حصة كل منهم فيه ، فهم شركاء على الشيوع ، وتحسب الحصص متساوية إذا لم يقم دليل على غير ذلك."}, {"number": "826", "chapter": "الفصل الأول", "text": "( 1 ) كل شريك فى الشيوع يملك حصته ملكا تاما وله أن يتصرف فيها وان يستولى على ثمارها وان يستعملها بحيث لا يلحق الضرر بحقوق سائر الشركاء. ( 2 ) وإذا كان التصرف منصبا على جزء مفرز من المال الشائع ولم يقع هذا الجزء عند القسمة فى نصيب المتصرف ، انتقل حق التصرف إليه من وقت التصرف إلى الجزء الذى آل إلى المتصرف بطريق القسمة وللمتصرف إليه ، إذا كان يجهل أن المتصرف لا يملك العين المتصرف فيها مفرزة الحق فى إبطال المتصرف."}, {"number": "827", "chapter": "الفصل الأول", "text": "تكون إدارة المال الشائع من حق الشركاء مجتمعين ما لم يوجد اتفاق يخالف ذلك."}, {"number": "828", "chapter": "الفصل الأول", "text": "( 1 ) ما يستقر عليه رأى أغلبية الشركاء فى أعمال الإدارة المعتادة يكون ملزما للجميع ، وتحسب الأغلبية على أساس قيمة الانصباء فإن لم يكن ثمة أغلبية فللمحكمة بناء على طلب أحد الشركاء أن تتخذ من التدابير ما تقتضيه الضرورة ، ولها أن تعيبن عند الحاجة من يدير المال الشائع. ( 2 ) وللأغلبية أيضا أن تختار مديرا. كما أن لها أن تضع للإدارة ولحسن الانتفاع بالمال الشائع نظاما يسرى حتى على خلفاء الشركاء جميعا سواء أكان الخلف عاما أم كان خاصا. ( 3 ) وإذا تولى أحد الشركاء الإدارة دون اعتراض من الباقين عد وكيلا عنهم."}, {"number": "829", "chapter": "الفصل الأول", "text": "( 1 ) للشركاء الذين يملكون على الأقل ثلاثة أرباع المال الشائع ، أن يقرروا فى سبيل تحسين الإنتفاع بهذا المال من التغييرات الأساسية والتعديل فى الغرض الذى اعد له ما يخرج عن حدود الإدارة المعتادة على أن يعلنوا قراراتهم إلى باقى الشركاء ولمن خالف من هؤلاء حق الرجوع إلى المحكمة خلال شهرين من وقت الإعلان. ( 2 ) وللمحكمة عند الرجوع إليها إذا وافقت على قرار تلك الأغلبية ، أن تقرر مع هذا ما تراه مناسبا من التدابير. ولها بوجه خاص أن تعطى المخالف من الشركاء كفالة تضمن الوفاء بما قد يستحق من التعويضات."}, {"number": "830", "chapter": "الفصل الأول", "text": "لكل شريك فى الشيوع الحق فى أن يتخذ من الوسائل ما يلزم لحفظ الشئ ، ولو كان ذلك بغير موافقة باقى الشركاء."}, {"number": "831", "chapter": "الفصل الأول", "text": "نفقات إدارة المال الشائع وحفظه والضرائب المفروضة عليه وسائر التكاليف الناتجة عن الشيوع أو المقررة على المال ، يتحملها جميع الشركاء ، كل بقدر حصته ، ما لم يوجد نص يقضى بغير ذلك."}, {"number": "832", "chapter": "الفصل الأول", "text": "للشركاء الدين يملكون على الأقل ثلاثة أرباع المال الشائع ، أن يقرروا التصرف فيه إذا استندوا فى ذلك إلى أسباب قوية على أن يعلنوا قراراتهم إلى باقى الشركاء. ولمن خالف من هؤلاء حق الرجوع إلى المحكمة خلال شهرين من وقت الإعلان. وللمحكمة عندما تكون قسمة المال الشائع ضارة بمصالح الشركاء أن تقدر تبعا للظروف ما إذا كان التصرف واجبا."}, {"number": "833", "chapter": "الفصل الأول", "text": "( 1 ) للشريك فى المنقول الشائع أو فى المجموع من المال أن يسترد قبل القسمة الحصة الشائعة التى باعها شريك غيره لأجنبى بطريق الممارسة ، وذلك خلال ثلاثين يوما من تاريخ علمه بالبيع أو من تاريخ إعلانه به ، ويتم الاسترداد بإعلان يوجه إلى كل من البائع والمشترى ويحل المسترد محل المشترى فى جميع حقوقه وإلتزاماته إذا هو عوضه عن كل ما انفقه. ( 2 ) وإذا تعدد المستردون فلكل منهم أن يسترد بنسبة حصته. انقضاء الشيوع بالقسمة :"}, {"number": "834", "chapter": "الفصل الأول", "text": "لكل شريك أن يطالب بقسمة المال الشائع ما لم يكن مجبرا على البقاء فى الشيوع بمقتضى نص أو اتفاق ، ولا يجوز بمقتضى الاتفاق أن تمنع القسمة إلى أجل يجاوز خمس سنين ، فإذا كان الأجل لا يجاوز هذه المدة نفد الاتفاق فى حق الشريك وفى حق من يخلفه."}, {"number": "835", "chapter": "الفصل الأول", "text": "للشركاء إذا أنعقد إجماعهم ، أن يقتسموا المال الشائع بالطريقة التى يرونها. فإذا كان بينهم من هو ناقص الأهلية وجبت مراعاة الإجراءات التى يفرضها القانون."}, {"number": "836", "chapter": "الفصل الأول", "text": "( 1 ) إذا اختلف الشركاء فى اقتسام المال الشائع فعلى من يريد الخروج من الشيوع أن يكلف باقى الشركاء الحضور أمام المحكمة الجزئية. ( 2 ) وتندب المحكمة أن رأت وجها لذلك خبيرا أو أكثر لتقويم المال الشائع وقسمته حصصا أن كان المال يقبل القسمة عينا دون أن يلحقه نقص كبير فى قسمته."}, {"number": "837", "chapter": "الفصل الأول", "text": "يكون الخبير الحصص على أساس أصغر نصيب حتى لو كانت القسمة جزئية ، فإن تعذرت القسمة على هذا الأساس جاز للخبير أن يجنب لكل شريك حصته. ( 2 ) وإذا تعذر أن يختص أحد الشركاء بكامل نصيبه عينا ، عوض بمعدل عما نقص من نصيبه."}, {"number": "838", "chapter": "الفصل الأول", "text": "( 1 ) تفصل المحكمة الجزئية فى المنازعات التى تتعلق بتكوين الحصص وفى كل المنازعات الأخرى التى تدخل فى اختصاصها. ( 2 ) فإذا قامت منازعة لا تدخل فى اختصاص تلك المحكمة كان عليها أن تحيل الخصوم إلى المحكمة الإبتدائية ، وان تعين لهم الجلسة التى يحضرون فيها ، وتقف دعوى القسمة إلى أن يفصل نهائيا فى تلك المنازعات."}, {"number": "839", "chapter": "الفصل الأول", "text": "متى انتهى الفصل فى المنازعات وكانت الحصص قد عينت بطريق التجنيب ، أصدرت المحكمة الجزئية حكما بإعطاء كل شريك النصيب المفرز الذى آل إليه. ( 2 ) فإن كانت الحصص لم تعين بطريق التجنيب ، تجرى القسمة بطريق الاقتراع ، وتثبت المحكمة ذلك فى محضرها وتصدر حكما بإعطاء كل شريك نصيبه المفرز."}, {"number": "840", "chapter": "الفصل الأول", "text": "إذا كان بين الشركاء غائب أو كان بينهم من لم تتوافر فيه الأهلية وجب تصديق المحكمة على حكم القسمة بعد أن يصبح نهائيا ، وذلك وفقا لما يقرره القانون."}, {"number": "841", "chapter": "الفصل الأول", "text": "إذا لم تمكن القسمة عينا ، أو كان من شأنها احداث نقص كبير فى قيمة المال المراد قسمته ، بيع هذا المال بالطرق المبينة فى قانون المرافعات ، وتقتصر المزايدة على الشركاء إذا طلبوا هذا بالإجماع."}, {"number": "842", "chapter": "الفصل الأول", "text": "( 1 ) لدائنى كل شريك أن يعارضوا فى أن تتم القسمة عينا أو أن يباع المال بالمزاد بغير تدخلهم ، وتوجه المعارضة إلى كل الشركاء ، ويترتب عليها إلزامهم أن يدخلوا من عارض من الدائنين فى جميع الإجراءات ، والا كانت القسمة غير نافذة فى حقهم ويجب على كل حال ادخال الدائنين المقيدة حقوقهم قبل رفع دعوى القسمة. ( 2 ) اما إذا تمت القسمة ، فليس للدائنين الذين لم يتدخلوا فيها أن يطعنوا عليها الا فى حالة الغش."}, {"number": "843", "chapter": "الفصل الأول", "text": "يعتبر المتقاسم مالكا للحصة التى آلت إليه منذ أن تملك فى الشيوع وانه لم يملك غيرها شيئا فى بقية الحصص."}, {"number": "844", "chapter": "الفصل الأول", "text": "( 1 ) يضمن المتقاسمون بعضهم لبعض ما قد يقع من تعرض أو استحقاق لسبب سابق على القسمة ، ويكون كل منهم ملزما بنسبة حصته أن يعوض مستحق الضمان ، على أن تكون العبرة فى تقدير الشئ بقيمته وقت القسمة فإذا كان أحد المتقاسمين معسرا ، وزع القدر الذى يلزمه على مستحق الضمان وجميع المتقاسمين غير المعسرين. ( 2 ) غير انه لا محل للضمان إذا كان هناك اتفاق صريح يقضى بالإعفاء منه فى الحالة الخاصة التى نشأ عنها. ويمتنع الضمان أيضا إذا كان الإستحقاق راجعا إلى خطأ المتقاسم نفسه."}, {"number": "845", "chapter": "الفصل الأول", "text": "( 1 ) يجوز نقض القسمة الحاصلة بالتراضى إذا اثبت أحد المتقاسمين انه قد لحقه منها غبن يزيد عن الخمس على أن تكون العبرة فى التقدير بقيمة الشئ وقت القسمة. ( 2 ) ويجب أن ترفع الدعوى خلال السنة التالية للقسمة وللمدعى عليه أن يقف سيرها ويمنع القسمة من جديد إذا اكمل للمدعى نقدا أو عينا ما نقص من حصته."}, {"number": "846", "chapter": "الفصل الأول", "text": "( 1 ) فى قسمة المهايأه يتفق الشركاء على أن يختص كل منهم بمنفعة جزء مفرز يوازى حصته فى المال الشائع ، متنازلا لشركائه فى مقابل ذلك عن الانتفاع بباقى الأجزاء. ولا يصح هذا الاتفاق لمدة تزيد على خمس سنين. فإذا لم تشترط لها مدة أو انتهت المدة المتفق عليها ولم يحصل اتفاق جديد ، كانت مدتها سنة واحدة تتجدد إذا لم يعلن الشريك إلى شركائه قبل انتهاء السنة الجارية بثلاثة اشهر انه لا يرغب فى التجديد. ( 2 ) وإذا دامت هذه القسمة خمس عشرة سنة. انقلبت قسمة نهائية ، ما لم يتفق الشركاء على غير ذلك. وإذا حاز الشريك على الشيوع جزها مفرزا من المال الشائع مدة خمس عشرة سنة ، أفترض أن حيازته لهذا الجزء تستند إلى قسمة مهايأة."}, {"number": "847", "chapter": "الفصل الأول", "text": "تكون قسمة المهاياة أيضا بأن يتفق الشركاء على أن يتناوبوا الانتفاع بجميع المال المشترك. كل منهم لمدة تتناسب مع حصته."}, {"number": "848", "chapter": "الفصل الأول", "text": "تخضع قسمة المهاياة من حيث جواز الاحتجاج بها على الغير ومن حيث أهلية المتقاسمين وحقوقهم والتزاماتهم وطرق الإثبات لأحكام عقد الإيجار. مادامت هذه الأحكام لا تتعارض مع طبيعة هذه القسمة."}, {"number": "849", "chapter": "الفصل الأول", "text": "( 1 ) للشركاء أن يتفقوا اثناء إجراءات القسمة النهائية على أن يقسم المال الشائع مهايأة بينهم ، وتظل هذه القسمة نافذة حتى تتم القسمة النهائية. ( 2 ) فإذا تعذر اتفاق الشركاء على قسمة المهايأه جاز للقاضى الجزئى إذا طلب منه ذلك أحد الشركاء أن يأمر بها ، بعد الاستعانة بخبير إذا اقتضى الأمر ذلك. الشيوع الإجبارى :"}, {"number": "850", "chapter": "الفصل الأول", "text": "ليس للشركاء فى مال شائع أن يطلبوا قسمته إذا تبين من الغرض الذى اعد له هذا المال ، انه بجب أن يبقى دائما على الشيوع. ملكية الأسرة"}, {"number": "851", "chapter": "الفصل الأول", "text": "لأعضاء الأسرة الواحدة الذين تجمعهم وحدة العمل أو المصلحة ، أن يتفقوا كتابة على إنشاء ملكية للأسرة وتتكون هذه الملكية اما من تركة ورثوها واتفقوا على جعلها كلها أو بعضها ملكا للأسرة واما من أى مال آخر مملوك لهم اتفقوا على إدخاله فى هذه الملكية."}, {"number": "852", "chapter": "الفصل الأول", "text": "( 1 ) يجوز الاتفاق على إنشاء ملكية الأسرة لمدة لا تزيد على خمس عشرة سنة ، على انه يجوز لكل شريك أن يطلب من المحكمة الاذن له فى إخراج نصيبه من هذه الملكية قبل انقضاء الأجل المتفق عليه إذا وجد مبرر قوى لذلك. ( 2 ) وإذا لم يكن للملكية المذكورة أجل معين كان لكل شريك أن يخرج نصيبه منها بعد ستة اشهر من يوم أن يعلن إلى الشركاء رغبته فى إخراج نصيبه."}, {"number": "853", "chapter": "الفصل الأول", "text": "( 1 ) ليس للشركاء أن يطلبوا القسمة مادامت ملكية الأسرة قائمة ، ولا يجوز لأى شريك أن يتصرف فى نصيبه لأجنبى عن الأسرة الا بموافقة الشركاء جميعا. ( 2 ) وإذا تملك أجنبى عن الأسرة حصة أحد الشركاء برضاء هذا الشريك أو جبرا عليه ، فلا يكون الأجنبى شريكا فى ملكية الأسرة الا برضائه ورضاء باقى الشركاء."}, {"number": "854", "chapter": "الفصل الأول", "text": "( 1 ) للشركاء أصحاب القدر الأكبر من قيمة الحصص أن يعينوا من بينهم للادارة واحدا أو أكثر ، وللمدير أن يدخل على ملكية الأسرة من التغيير فى الغرض أول فى اعد له المال المشترك ما يحسن به طرق الانتفاع بهذا المال ، ما لم يكن هناك اتفاق على غير ذلك. ( 2 ) ويجوز عزل المدير بالطريقة التى عين بها ولو اتفق على غير ذلك ، كما يجوز للمحكمة أن تعزله بناء على طلب أى شريك إذا وجد سبب قوى يبرر هذا العزل."}, {"number": "855", "chapter": "الفصل الأول", "text": "فيما عد الأحكام كسابقة تنطبق قواعد الملكية الشائعة وقواعد الوكالة على ملكية الأسرة ملكية الطبقات"}, {"number": "856", "chapter": "الفصل الأول", "text": "( 1 ) إذا تعدد ، طبقات الدار أو شققها المختلفة ، فانهم يعدون شركاء فى ملكية الأرض وملكية أجزاء البناء المعدة للاستعمال المشترك بين الجميع ، وبوجه خاص الأساسيات والجدران الرئيسية والمداخل والأفنية والأسطح والمصاعد والممرات والدهاليز وقواعد الأرضيات وكل أنواع الأنابيب الا ما كان منها داخل الطبقة أو الشقة ، كل هذا ما لم يوجد فى سندات اسق ما يخالفه. ( 2 ) وهذه الأجزاء المشتركة من الدار لا تقبل القسمة. ويكون نصيب كل مالك فيها بنسبة قيمة الجزء الذى له فى الدار ، وليس لمالك أن يتصرف فى نصيبه هذا مستقلا عن الجزء الذى يملكه. ( 3 ) والحواجز الفاصلة بين شقتين تكون ملكيتها مشتركة جما أصحاب هاتين الشقتين."}, {"number": "857", "chapter": "الفصل الأول", "text": "( 1 ) كل مالك فى سبيل الانتفاع بالجز. الذى يملكه فى الدار حر فى أن يستعمل الأجزاء المشتركة فيما أعدت له ، على الا يحول دون استعمال باقى الشركاء لحقوقهم. ( 2 ) ولا يجوز احداث أى تعديل فى الأجزاء المشتركة بغير مرافقة جميع الملاك حتى عند تجديد البناء ، الا إذا كان التعديل الذى يقوم به أحد الملاك على نفقته الخاصة ، من شأنه أن يسهل استعمال تلك الأجزاء ، دون أن يغير من تخصيصها أو يلحق الضرر بالملاك الآخرين."}, {"number": "858", "chapter": "الفصل الأول", "text": "( 1 ) على كل مالك أن يشترك فى تكاليف حفظ الأجزاء المشتركة وصيانتها وإدارتها وتجديدها ، ويكون نصيبه فى هذه التكاليف بنسبة قيمة الجزء الذى له فى الدار ما لم يوجد اتفاق على غير ذلك. ( 2 ) ولا يحق لمالك أن يتخلى عن نصيبه فى الأجزاء المشتركة للتخلص من الاشتراك فى التكاليف المتقدمة الذكر."}, {"number": "859", "chapter": "الفصل الأول", "text": "( 1 ) على صاحب السفل أن يقوم بالأعمال والترميمات اللازمة لمنع سقوط العلو. ( 2 ) فإذا امتنع عن القيام بهذه الترميمات ، جاز للقاضى أن يأمر ببيع السفل. ويجوز فى كل حال لقاضى الأمور المستعجلة أن يأمر بإجراء الترميمات العاجلة."}, {"number": "860", "chapter": "الفصل الأول", "text": "( 1 ) إذا انهدم البناء وجب على صاحب السفل أن يعيد بناء سفله ، فإذا امتنع جاز للقاضى أن يأمر ببيع السفل الا إذا طلب صاحب العلو أن يعيد هو بناء السفل على نفقة صاحبه. ( 2 ) وفى الحالة الأخيرة يجوز لصاحب العلو أن يمنع صاحب السفل من السكنى والانتفاع حتى يؤدى ما فى ذمته. ويجوز له أيضا أن يحصل على اذن فى إيجار السفل أو سكنا استيفاء لحقه."}, {"number": "861", "chapter": "الفصل الأول", "text": "لا يجوز لصاحب العلو أن يزيد فى ارتفاع بنائه بحيث يضر بالسفل. اتحاد ملاك طبقات البناء الواحد :"}, {"number": "862", "chapter": "الفصل الأول", "text": "( 1 ) حيثما وجدت ملكية مشتركة لعقار مقسم إلى طبقات أو شقق جاز للملاك أن يكونوا اتحادا فيما بينهم. ( 2 ) ويجوز أن يكون الغرض من تكوين الأتحاد بناء العقارات أو مشتراها لتوزيع ملكية أجزائها على أعضائها."}, {"number": "863", "chapter": "الفصل الأول", "text": "للاتحاد أن يضع بموافقة جميع الأعضاء نظاما لضمان حسن الانتفاع بالعقار المشترك وحسن إدارته."}, {"number": "864", "chapter": "الفصل الأول", "text": "إذا لم يوجد نظام للإدارة أو إذا خلا النظام من النص على بعض الأمور ، تكون إدارة الأجزاء المشتركة من حق الأتحاد وتكون قراراته فى ذلك ملزمة ، بشرط أن يدعى جميع ذوى الشأن بكتاب موصى عليه إلى الاجتماع ، وان تصدر القرارات من أغلبية الملاك محسوبة على أساس قيمة الانصباء."}, {"number": "865", "chapter": "الفصل الأول", "text": "للاتحاد بأغلبية الأصوات المنصوص عليها فى المادة السابقة ، أن يفرض أى تأمين مشترك من الأخطار التى تهدد العقار أو الشركاء فى جملتهم وله أن بإذن فى أجراء أية أعمال أو تركيبات مما يترتب عليها زيادة فى قيمة العقار كله أو بعضه ، وذلك على نفقة من يطلبه من الملاك وبما يضعه الاتحاد من شروط وما يفرضه من تعويضات وإلتزامات اخرى."}, {"number": "866", "chapter": "الفصل الأول", "text": "( 1 ) يكون للاتحاد مأمور يتولى تنفيذ قراراته ، وشين بالأغلبية المشار إليها فى المادة 864 ، فإن لم تتحقق الأغلبية عين بأمر يصدر من رئيس المحكمة الابتدائية الكائن فى دائرتها العقار بناء على طلب أحد الشركاء بعد إعلان الملاك الآخرين لسماع أقوالهم. وعلى المأمور إذا اقتضى الحال أن يقوم من تلقاء نفسه بما يلزم لحفظ جميع الأجزاء المشتركة وحراستها وصيانتها ، وله أن يطالب كل ذى شأن بتنفيذ ولا ، الإلتزامات. كل هذا ما لم يوجد نص فى نظام الاتحاد يخالفه. ( 2 ) ويمثل المأمور الاتحاد أمام القضاء حتى فى مخاصمة الملاك إذا اقتضى الأمر."}, {"number": "867", "chapter": "الفصل الأول", "text": "( 1 ) أجر المأمور يحدده القرار أو الأمر الصادر بتعيينه. ( 2 ) ويجوز عزله بقرار تتوافر فيه الأغلبية المشار إليها فى المادة 864 أو بأمر بصدر من رئيس المحكمة الابتدائية الكائن فى دائرتها العقار بعد اعلان الشركاء لسماح أقوالهم فى هذا العزل"}, {"number": "868", "chapter": "الفصل الأول", "text": "( 1 ) إذا هلك البناء بحريق أو بسبب آخر ، فعلى الشركاء أن يلتزموا من حيث تجديده ما يقرر الاتحاد بالأغلبية المنصوص عليها فى المادة 864 ما لم يوجد اتفاق يخالف ذلك. ( 2 ) فإذا قرر الاتحاد بجديد البناء خصص ما قد يستحق من تعويض بسبب هلاك العقار لأعمال التجديد ، دون أخذ بحقوق أصحاب الديون المقيدة."}, {"number": "869", "chapter": "الفصل الأول", "text": "( 1 ) كل قرض يمنحه الاتحاد أحد الشركاء لتمكينه من القيام بإلتزاماته يكون مضمونا بامتياز على الجزء المفرز الذى يملكه وعلى حصته الشائعة فى الأجزاء المشتركة من العقار. ( 2 ) وتحسب مرتبه هذا الامتياز من يوم قيده."}, {"number": "870", "chapter": "الفصل الثانى", "text": "من وضع يده على منقول لا مالك له بنية تملكه ، ملكه."}, {"number": "871", "chapter": "الفصل الثانى", "text": "يصبح المنقول لا مالك له إذا تخلى عنه مالكه بقصد النزول عن ملكيته. ( 2 ) وتعتبر الحيوانات غير الأليفة لا مالك لها ما دامت طليقة. وإذا اعتقل حيوان منها ثم أطلق عاد لا مالك له إذا لم يتبعه المالك فورا وإذا كف عن تتبعه وما روض من الحيوانات والف الرجوع إلى المكان المخصص له ثم فقد هذه العادة يرجع لا مالك له."}, {"number": "872", "chapter": "الفصل الثانى", "text": "( 1 ) الكنز المدفون أو المخبوء الذى لا يستطيع أحد أن يثبت ملكيته له. يكون لمالك العقار الذى وجد فيه الكنز أو لمالك رقبته. ( 2 ) والكنز الذى يعثر عليه فى عين موقوفة يكون ملكا خاصا للواقف ولورثته."}, {"number": "873", "chapter": "الفصل الثانى", "text": "الحق فى صيد البحر والبر واللقطة والأشياء الأثرية تنظمه لوائح خاصة. الاستيلاء على عقار ليس له مالك :"}, {"number": "874", "chapter": "الفصل الثانى", "text": "( 1 ) الأراضى غير المزروعة التى لا مالك لها تكون ملكا للدولة. ( 2 ) ولا يجوز تملك هذه الأراضى أو وضع اليد عليها الا بترخيص من الدولة وفقا للوائح. ( 3 ) الا انه إذا زرع مصرى أرضا غير مزروعة أو غرسها أو بنى عليها ، تملك فى الحال الجزء المزروع أو المغروس أو المبنى ولو بغير ترخيص من الدولة. ولكنه يفقد ملكيته بعدم الاستعمال مدة خمس سنوات متتابعة خلال الخمس العشرة السنة التالية للتمليك. 2 - الميراث وتصفية التركة"}, {"number": "875", "chapter": "الفصل الثانى", "text": "( 1 ) تعيين الورثة وتحديد أنصبائهم فى الإرث وانتقال أموال التركة إليهم تسرى فى شأنها أحكام الشريعة الإسلامية والقوانين الصادرة فى شأنها. ( 2 ) وتتبع فى تصفية التركة الأحكام الآتية : تعيين مصف للتركة :"}, {"number": "876", "chapter": "الفصل الثانى", "text": "إذا لم يعين المورث وصيا لتركته وطلب أحد ذوى الشأن تعيين مصف لها ، عينت المحكمة ، إذا رأت موجبا لذلك ، من تجمع الورثة على اختياره فإن لم تجمع الورثة على أحد تولى القاضى اختيار المصفى على أن يكون بقدر المستطاع من بين الورثة ، وذلك بعد سماع أقوال هؤلاء."}, {"number": "877", "chapter": "الفصل الثانى", "text": "( 1 ) لمن عين مصفيا أن يرفض تولى هذه المهمة أو أن يتنحى عنها بعد توليها وذلك طبقا لأحكام الوكالة. ( 2 ) وللقاضى أيضا ، إذا طلب إليه أحد ذرى الشأن أو النيابة العامة أو دون طلب ، عزل المصفى واستبدال غيره به ، متى وجدت أسباب تبرر ذلك."}, {"number": "878", "chapter": "الفصل الثانى", "text": "( 1 ) إذا عين المورث وصيا للتركة وجب أن يقر القاضى هذا التعيين. ( 2 ) ويسرى على وصى التركة ما يسرى على المصفى من أحكام."}, {"number": "879", "chapter": "الفصل الثانى", "text": "( 1 ) على كاتب المحكمة أن يقيد يوما فيوما الأوامر الصادرة بتعيين المصفيين وبتثبيت أوصياء التركة ، فى سجل عام تدون فيه أسماء المورثين بحسب الأوضاع المقررة للفهارس الأبجدية ويجب أن يؤشر فى هامش السجل بكل أمريصدر بالعزل وبكل ما يقع من تنازل. ( 2 ) ويكون لقيد الأمر الصادر بتعيين المصفى من الأثر فى حق الغير الذى يتعامل مع الورثة فى شأن عقارات التركة ما للتأشير المنصوص عليه فى المادة 914."}, {"number": "880", "chapter": "الفصل الثانى", "text": "يتسلم المصفى أموال التركة بمجرد تعيينه ، ويتولى تصفيتها برقابة المحكمة. وله أن يطلب منها أجرا عادلا على قيامه بمهمته. ( 2 ) ونفقات التصفية تتحملها التركة ، ويكون لهذه النفقات حق امتياز فى مرتبة امتياز المصروفات القضائية."}, {"number": "881", "chapter": "الفصل الثانى", "text": "على المحكمة أن تتخذ عند الاقتضاء جميع ما يجب من الاحتياطات المستعجلة للمحافظة على التركة ، وذلك بناء على طلب أحد ذوى الشأن أو بناء على طلب النيابة العامة أو دون طلب ما. ولها بوجه خاص أن تأمر بوضع الأختام وإيداع النقود والأوراق المالية والأشياء ذات القيمة."}, {"number": "882", "chapter": "الفصل الثانى", "text": "( 1 ) على المصفى أن يقوم فى الحال بالصرف من مال التركة لتسديد نفقات تجهيز الميت ونفقات مأتمه بما يناسب حالته ، وعليه أيضا أن يستصدر أمرا من قاضى الأمور الوقتية بصرف نفقة كافية بالقدر المقبول من هذا المال إلى من كان المورث يعولهم من ورثته حتى تنتهى التصفية ، على أن تخصم النفقة التى يستولى عليها كل وارث من نصيبه فى الإرث. ( 2 ) وكل منازعة تتعلق بهده النفقة يفصل فيها قاضى الأمور الوقتية. جرد التركة :"}, {"number": "883", "chapter": "الفصل الثانى", "text": "( 1 ) لا يجوز من وقت قيد الأمر الصادر بتعيين المصفى أن يتخذ الدائنون أى أجراء على التركة ، كما لا يجوز لهم أن يستمروا فى أى أجراء اتخذوه الا فى مواجهة المصفى. ( 2 ) وكل توزيع فتح ضد المورث ولم تقفل قائمته النهائية ، يجب وقفه حتى تتم تسوية جميع ديون التركة متى طلب ذلك أحد ذوى الشأن."}, {"number": "884", "chapter": "الفصل الثانى", "text": "لا يجوز للوارث قبل أن تسلم إليه شهادة التوريث المنصوص عليها فى المادة 901 أن يتصرق فى مال التركة ، كما لا يجوز له أن يستوفى فى ما للتركة من ديون أو أن يجعل دينا عليه قصاصا بدين التركة."}, {"number": "885", "chapter": "الفصل الثانى", "text": "على المصفى فى اثناء التصفية أن يتغذ ما تتطلبه أموال التركة من الوسائل التحفظية ، وان يقوم بما يلزم من أعمال الادارة وعليه أيضا أن ينوب عن التركة فى الدعاوى وان يستوفى ما لها من ديون قد حلت. ( 2 ) ويكون المصفى ، ولو لم يكن مأجورا ، مسئولا مسئولية الوكيل المأجور. وللقاضى أن يطالبه بتقديم حساب عن إدارته فى مواعيد دورية."}, {"number": "886", "chapter": "الفصل الثانى", "text": "( 1 ) على المصفى أن يوجه تكليفا علنيا لدائنى التركة ومدينيها يدعوهم فيه لأن يقدموا بيانا بما لهم من حقوق وما عليهم من ديون ، وذلك خلال ثلاثة اشهر من التاريخ الذى ينشر فيه التكليف لآخر مرة. ( 2 ) ويجب أن يلصق التكليف على الباب الرئيس لمقر العمدة فى المدينة أو القرية التى توجد بها أعيان التركة ، أو على الباب الرئيس لمركز البوليس فى المدن التى تقع فى دائرتها مادة الأعيان وفى لوحة المحكمة الجزئية التى يقع فى دائرتها آخر موطن للمورث ، وفى صحيفة من الصحف اليومية الواسعة الانتشار."}, {"number": "887", "chapter": "الفصل الثانى", "text": "( 1 ) على المصفى أن يودع قلم كتاب المحكمة كتاب المحكمة خلال أربعة اشهر من يوم تعيينه ، قائمة تبين ما للتركة وما عليها. وتشمل على تقدير لقيمة هذه الأموال ، وعليه أيضا أن يخطر بكتاب موص عليه فى الميعاد المتقدم كل ذى شأن بحصول هذا الإيداع. ( 2 ) ويجوز أن يطلب إلى القاضى مد هنا الميعاد إذ وجدت ظروف تبرر ذلك."}, {"number": "888", "chapter": "الفصل الثانى", "text": "( 1 ) للمصفى أن يستعين فى الجرد وفى تقدير قيمة أموال التركة بخبير أو بمن يكون له فى ذلك دواية خاصة. ( 2 ) ويجب على المصفى أن يثبت ما تكشف عنه أوراق المورث وما هو ثابت فى السجلات العامة من حقوق وديون وما يصل إلى علمه عنها من أى طريق كان وعلى الورثة أن يبلغوا المصفى عما يعلمونه من ديون على التركة وحقوق لها."}, {"number": "889", "chapter": "الفصل الثانى", "text": "يعاقب بعقوبة التبديد كل من استولى غشا على شئ من مال التركة ولو كان وارثا."}, {"number": "890", "chapter": "الفصل الثانى", "text": "( 1 ) كل منازعة فى صحة الجرد ، وبخاصة ما كان متعلقة بإغفال أعيان أو حقوق للتركة أو عليها أو بإثباتها. ترفع بعريضة للمحكمة بناء على طلب كل ذى شأن خلال الثلاثين يوما التالية للأخطر بإيداع قائمة الجرد. ( 2 ) وتجرى المحكمة تحقيقا ، فإذا رأت أن الشكوى جدية أصدرت أمرا بقبولها ويصح التظلم من هذا الأمر وفقا لأحكام قانون المرافعات. ( 3 ) وان لم يكن النزاع قد سبق رفعه إلى القضاء عينت المحكمة اجلا يرفع فيه ذوى الشأن دعواه أمام المحكمة المختصة ، وتقضى فيها هذه المحكمة على وجه الاستعجال. تسوية ديون التركة :"}, {"number": "891", "chapter": "الفصل الثانى", "text": "بعد انقضاء الميعاد المعين لرفع المنازعات المتعلقة بالجرد يقوم المصفى بعد استئذان المحكمة بوفاء ديون التركة التى لم يقم فى شأنها نزاع. اما الديون التى توزع فيها فتسوى بعد الفصل فى النزاع نهائيا."}, {"number": "892", "chapter": "الفصل الثانى", "text": "على المصفى فى حالة إعسار التركة أو فى حالة إحتمال إعسارها ، أن يقف تسوية أى دين ، ولو لم يقم فى شأنه نزاع حتى يفصل نهائيا فى جميع المنازعات المتعلقة بديون التركة."}, {"number": "893", "chapter": "الفصل الثانى", "text": "( 1 ) يقوم المصفى بوفاء ديون التركة مما يحصله من حقوقها ، ومما تشتمل عليه من نقود ومن ثمن ما يكون قد باعه بسعر السوق من أوراق مالية ومن ثمن ما فى التركة من منقول فإن لم يكن ذلك كافيا فمن ثمن ما فى التركة من عقار. ( 2 ) وتباع منقولات التركة وعقاراتها بالمزاد العلنى وفقا للأوضاع وفى المواعيد المنصوص عليها فى البيوع الجارية ، الا إذا اتفق جميع الورثة على أن يتم البيع بطريقة اخرى أو على أن يتم ممارسة. فإذا كانت التركة معسرة لزمت أيضا موافقة جميع الدائنين. وللورثة فى جميع الأحوال الحق فى أن يدخلوا فى المزاد."}, {"number": "894", "chapter": "الفصل الثانى", "text": "ت للمحكمة بناء على طلب جميع الورثة أن تحكم بحلول الدين المؤجل وبتعيين المبلغ الذى يستحقه الدائن مراعية فى ذلك حكم المادة 544."}, {"number": "895", "chapter": "الفصل الثانى", "text": "( 1 ) إذا لم يجمع الورثة على طلب حلول الدين المؤجل ، تولت المحكمة توقيع الديون المؤجلة وتوزيع أموال التركة بحيث يختص كل وارث من جملة ديون التركة ومن جملة أموالها بما يكون نتيجته معادلا لصافى حصته فى الإرث. ( 2 ) وترتب المحكمة لكل دائن من دائنى التركة تأمينا كافيا على عقار أو منقول ، على أن يحتفظ لمن كان له تأمين خاص بنفس هذا التأمين. فإن استحال تحقيق ذلك ، ولو بإضافة ضمان تكميلى ، يقدمه الورثة من مالهم الخاص أو بالاتفاق على أية تسوية اخرى ، رتبت المحكمة التأمين على أموال التركة جميعها. ( 3 ) وفى جميع هذه الأحوال إذا ورد تأمين على عقار ولم يكن قد سبق شهره ، وجب أن يشهر هذا التأمين وفقا للأحكام المقررة فى شهر حق الاختصاص."}, {"number": "896", "chapter": "الفصل الثانى", "text": "يجوز لكل وارث بعد توزيع الديون المؤجلة أن يدفع القدر الذى اختص به قبل أن يحل الأجل طبقا للمادة 894."}, {"number": "897", "chapter": "الفصل الثانى", "text": "دائنو التركة الذين لم يستوفوا حقوقهم لعدم ظهورها فى قائمة الجرد ولم تكن لهم تأمينات على أموال التركة ، لا يجوز لهم أن يرجعوا على من كسب بحسن نية حقا عينيا على تلك الأموال وإنما لهم الرجوع على الورثة بسبب أثرائهم."}, {"number": "898", "chapter": "الفصل الثانى", "text": "يتولى المصفى بعد تسوية ديون التركة تنفيذ الوصايا وغيرها من التكاليف. تسليم أموال التركة وقسمة هذه الأموال :"}, {"number": "899", "chapter": "الفصل الثانى", "text": "بعد تنفيذ إلتزامات التركة يؤول ما بقى من أموالها إلى الورثة كل بحسب نصيبه الشرعى."}, {"number": "900", "chapter": "الفصل الثانى", "text": "( 1 ) يسلم المصفى إلى الورثة مال المهم من أموال التركة. ( 2 ) ويجوز للورثة ، بمجرد انقضاء الميعاد المقرر للمنازعات المتعلقة بالجرد ، المطالبة بأن يتسلموا ، بصفة مؤقتة الأشياء أو النقود التى لا يحتاج لها فى تصفية التركة ، أو أن يتسلموا بعضا منها وذلك مقابل تقديم كفالة أو بدون تقديمها."}, {"number": "901", "chapter": "الفصل الثانى", "text": "تسلم المحكمة إلى كل وارث يقدم إعلاما شرعيا بالوراثة أو ما يقوم مقام هذا الإعلام ، شهادة تقرر حقه فى الإرث وتبين مقدار نصيبه منه وتعين ما آل إليه من أموال التركة."}, {"number": "902", "chapter": "الفصل الثانى", "text": "لكل وارث أن يطلب من المصفى أن يسلمه نصيبه فى الإرث مفرزا ، الا إذا كان هذا الوارث ملزما بالبقاء فى الشيوع ثناء على اتفاق أو نص فى القانون."}, {"number": "903", "chapter": "الفصل الثانى", "text": "( 1 ) إذا كان طلب القسمة واجب القبول. تولى المصفى أجراء القسمة بطريقة ودية على الا تصبح هذه القسمة نهائية الا بعد أن يقرها الورثة بالإجماع. ( 2 ) فإذا لم ينعقد إجماعهم على ذلك ، فعلى المصفى أن يرفع على نفقة التركة دعوى بالقسمة ونقا لأحكام القانون ، وتستنزل نفقات الدعوى من أنصباء المتقاسمين."}, {"number": "904", "chapter": "الفصل الثانى", "text": "تسرى على قسمة التركة القواعد المقررة فى القسمة ، وبوجه خاص ما يتعلق منها بضمان التعرض والاستحقاق وبالغبن وبامتياز المتقاسم ، وتسرى عليها أيضا الأحكام الآتية :"}, {"number": "905", "chapter": "الفصل الثانى", "text": "إذا لم يتفق الورثة على قسمة الأوراق العائلية أو الأشياء التى تتصل بعاطفة الورثة نحو المورث ، أمرت المحكمة اما ببيع هذه الأشياء أو بإعطائها لأحد الورثة مع استنزال قيمتها من نصيبه فى الميراث أو دون استنزال. ويراعى فى ذلك ما جرى عليه العرف وما يحيط بالورثة من ظروف شخصية."}, {"number": "906", "chapter": "الفصل الثانى", "text": "إذا كان بين أموال التركة مستغل زراعى أو صناعى أو تجارى مما يعتبر وحدة اقتصادية قائمة لملاكها ، وجب تخصيصه برمته لمن يطلبه من الورثة إذا كان أقدرهم على الاضطلاع به. وثمن هذا المستغل يقوم بحسب قيمته ويستنزل من نصيب الوارث فى التركة. فإذا تساوت قدرة الورثة على الاضطلاع بالمستغل خصص لمن يعطى من بينهم أعلى قيمة بحيث لا تقل عن ثمن المثل."}, {"number": "907", "chapter": "الفصل الثانى", "text": "إذا اختص أحد الورثة عند القسمة بدين للتركة ، فإن باقى الورثة لا يضمنون له المدين إذا هو اعسر بعد القسمة ما لم يوجد اتفاق يقضى بغير ذلك."}, {"number": "908", "chapter": "الفصل الثانى", "text": "تصح الوصية بقسمة أعيان التركة على ورثة الموصى ، بحيث يعين لكل وارث أو لبعض الورثة قدر نصيبه ، فإن زادت قيمة ما عين لاحدهم على استحقاقه فى التركة كانت الزيادة بوصية."}, {"number": "909", "chapter": "الفصل الثانى", "text": "القسمة المضافة إلى ما بعد الموت يجوز الرجوع فيها دائما. وتصبح لازمة بوفاة الموصى."}, {"number": "910", "chapter": "الفصل الثانى", "text": "إذا لم تشمل القسمة جميع أموال المورث وقت وفاته ، فإن الأموال التى لم تدخل فى القسمة تؤول شائعة إلى الورثة طبقا لقواعد الميراث."}, {"number": "911", "chapter": "الفصل الثانى", "text": "إذا مات قبل وفاة المورث واحد أو أكثر من الورثة المحتملين الذين دخلوا فى القسمة ، فإن الحصة المفرزة التى وقعت فى نصيب من مات تؤول شائعة إلى باقى الورثة طبقا لقواعد الميراث."}, {"number": "912", "chapter": "الفصل الثانى", "text": "تسرى فى القسمة المضافة إلى ما بعد الموت أحكام القسمة عامة عدا أحكام الغبن."}, {"number": "913", "chapter": "الفصل الثانى", "text": "إذا لم تشمل القسمة ديون التركة أو شملتها ولكن لم يوافق الدائنون على هذه القسمة ، جاز عند عدم تسوية الديون بالاتفاق مع الدائنين أن يطلب أى وارث قسمة التركة طبقا للمادة 895 ، على أن تراعى بقدر الإمكان القسمة التى أوصى بها المورث والإعتبارات التى بنيت عليها. أحكام التركات التى لم تصف :"}, {"number": "914", "chapter": "الفصل الثانى", "text": "إذا لم تكن التركة قد صفيت وفقا لأحكام النصوص السابقة ، جاز لدائنى التركة العاديين أن ينفذوا بحقوقهم أو بما أوصى به لهم على عقارات التركة التى لا التصرف فيها ، أو التى رتبت عليها حقوق عينيه لصالح الغير إذا اشروا بديونهم وفقا لأحكام القانون. 3 - الوصية"}, {"number": "915", "chapter": "الفصل الثانى", "text": "تسرى على الوصية أحكام الشريعة الإسلامية والقوانين الصادرة فى شأنها."}, {"number": "916", "chapter": "الفصل الثانى", "text": "( 1 ) كل عمل قانونى يصدر من شخص فى مرض الموت ويكون مقصودا به التبرع ، يعتبر تصرفا مضافا إلى ما بعد الموت ، وتسرى عليه أحكام الوصية أيا كانت التسمية التى تعطى لهذا التصرف. ( 2 ) وعلى ورثة من تصرف أن يثبتوا أن العمل القانونى قد صدر من مورثهم وهو فى مرض الموت ، ولهم إثبات ذلك بجميع الطرق ، ولا يحتج على الورثة بتاريخ السند إذا لم يكن هذا التاريخ ثابتا. ( 3 ) وإذا اثبت الورثة أن التصرف صدر من مورثهم فى مرض الموت ، اعتبر التصرف صادرا على سبيل التبرع ، ما لم يثبت من صدر له التصرف عكس ذلك ، كل هذا ما لم توجد أحكام خاصة تخالفه."}, {"number": "917", "chapter": "الفصل الثانى", "text": "إذا تصرف شخص لأحد لرثته واحتفظ بأية طريقة كانت بحيازة العين التى تصرف فيها ، وشقه فى الانتفاع بها مدى حياته ، اعتبر التصرف مضافا إلى ما بعد الموت وتسرى عليه أحكام الوصية ما لم يقم دليل يخالف ذلك. 4 - الالتصاق الالتصاق بالعقار :"}, {"number": "918", "chapter": "الفصل الثانى", "text": "الأرض التى تتكون من طمى بجلبه النهر بطريقة تدريجية غير محسوسة تكون ملكا للملاك المجاورين."}, {"number": "919", "chapter": "الفصل الثانى", "text": "( 1 ) الأرض التى ينكشف عنها البحر تكون ملكا للدولة. ( 2 ) ولا يجوز التعدى على أرض البحر الا إذا كان ذلك لاعادة حدود الملك الذى طغى عليه البحر."}, {"number": "920", "chapter": "الفصل الثانى", "text": "ملاك الأراضى الملاصقة للمياه الراكدة كمياه البحيرات والبرك ، لا يملكون ما تنكشف عنه هذه المياه من أراضى ولا تزول عنهم ملكية ما تطغى عليه هذه المياه."}, {"number": "921", "chapter": "الفصل الثانى", "text": "الأراضى التى يحولها النهر من مكانها أو ينكشف عنها ، والجزائر التى تتكون فى مجراه ، تكون ملكيتها خاضعة لأحكام القوانين الخاصة بها."}, {"number": "922", "chapter": "الفصل الثانى", "text": "( 1 ) كل ما على الأرض أو تحتها من بناه أو غراس أو منشآت اخرى ، يعتبر من عمل صاحب الأرض أقامه على نفقته ويكون مملوكا له. ( 2 ) ويجوز مع ذلك أن يقام الدليل على أن أجنبيا قد أقام هذه المنشآت على نفقته. كما يجوز أن يقام الدليل على أن مالك الأرض قد خول أجنبيا ملكية منشآت كانت قائمة من قبل أو حوله الحق فى أقامة هذه المنشآت وتملكها."}, {"number": "923", "chapter": "الفصل الثانى", "text": "( 1 ) يكون ملكا خالصا لصاحب الأرض ما يحدثه فيها من بناه أو غرامى أو منشآت اخرى يقيمها بمواد مملوكة لغيره ، إذا لم يكن ممكنا نزع مادة المواد دون أن يلحق هذه المنشآت ضرر جسيم. أو كان ممكنا نزعها ولكن ترفع الدعوى باستردادها خلال سنة من اليوم الذى يعلم فيه مالك المواد انها اندمجت فى هذه المنشآت. ( 2 ) فإذا تملك صاب الأرض المواد ، كان عليه أن يدفع قيمتها مع التعويض أن كان له وجه. اما إذا استرد المواد صاحبها فإن نزعها يكون على نفقة صاحب الأرض."}, {"number": "924", "chapter": "الفصل الثانى", "text": "( 1 ) إذا أقام شخص بمواد من عنده منشآت على أرض يعلم انها مملوكة لغيره دون رضاء صاحب الأرض ، كان لهذا أن يطلب إزالة المنشآت على نفقة من أقامها مع التعويض أن كان له وجه ، وذلك فى ميعاد سنة من اليوم الذى يعلم فيه بإقامة المنشآت أو أن يطلب استيفاء المنشآت مقابل دفع قيمتها مستحقة الازالة ، أو دفع مبلغ يساوى ما زاد فى ثمن الأرض بسبب هذه المنشآت. ( 2 ) ويجوز لمن أقام المنشآت أن يطلب نزعها أن كان ذلك لا يلحق بالأرض ضررا ، الا إذا اختار صاحب الأرض أن يستبقى المنشآت طبقا لأحكام الفترة السابقة."}, {"number": "925", "chapter": "الفصل الثانى", "text": "( 1 ) إذا كان من أقام المنشآت المشار إليها فى المادة السابقة يعتقد بحسن نية أن له الحق فى أقامتها ، فلا يكون لصاحب الأرض أن يطلب الازالة ، وإنما يخير بين أن يدفع قيمة المواد وأجرة العمل أو أن يدفع مبلغا يساوى ما زاد فى ثمن الأرض بسبب مادة المنشآت ، هنا ما لم يطلب صاحب المنشآت نزعها. ( 2 ) الا انه إذا كانت المنشآت قد بلغت حلا من الجسامة يرهق صاحب الأرض أن يؤدى ما هو مستحق عنها ، كان له أن يطلب تمليك الأرض لمن أقام المنشآت نظير تعويض عادل"}, {"number": "926", "chapter": "الفصل الثانى", "text": "إذا أقام أجنبى منشآت بمواد من عنده بعد الحصول على ترخيص من مالك الأرض فلا يجوز لهذا المالك إذا لم يوجد اتفاق فى شأن هذه المنشآت أن يطلب ازالتها ، ويجب عليه اذا لم يطلب صاحب المنشآت نزعها أن يؤدى إليه احدى القيمتين المنصوص عليهما فى الفقرة الأولى من المادة السابقة."}, {"number": "927", "chapter": "الفصل الثانى", "text": "تسرى أحكام المادة 982 فى أداء التعويض المنصوص عليه فى المواد الثلاث السابقة."}, {"number": "928", "chapter": "الفصل الثانى", "text": "إذا كان مالك الأرض وهو يقيم عليها بناء قد جار بحسن نية على جزء من الأرض الملاصقة ، جاز للمحكمة إذا رأت محلا لذلك أن تجبر صاحب مادة الأرض على أن ينزل لجاره عن ملكية الجزء المشغول بالبناء ، وذلك فى نظير تعويض عادل."}, {"number": "929", "chapter": "الفصل الثانى", "text": "المنشآت الصغيرة كالأكشاك والحوانيت والمأوى التى تقام على أرض الغير دون أن يكون مقصودا بقاؤها على الدوام ، تكون ملكا لمن أقامها."}, {"number": "930", "chapter": "الفصل الثانى", "text": "إذا أقام أجنبى منشآت بمواد مملوكة لغيره ، فليس لمالك المواد أن يطلب استردادها ، وإنما يكون له أن يرجع بالتعويض على هذا الأجنبى كما له أن يرجع على مالك الأرض بما لا يريد على ما هو باق فى ذمته من قيمة تلك المنشآت. الالتصاق بالمنقول :"}, {"number": "931", "chapter": "الفصل الثانى", "text": "إذا التصق منقولان لمالكين مختلفين بحيث لا يمكن فصلهما دون تلف ولم يكن هناك اتفاق بين المالكين ، قضت المحكمة فى الأمر مسترشدة بقواعد العدالة ومراعية فى ذلك الضرر الذى حدث وحالة الطرفين وحسن نية كل منهما. 5 - العقد"}, {"number": "932", "chapter": "الفصل الثانى", "text": "تنتقل الملكية وغيرها من الحقوق العينية فى المنقول والعقار بالعقد ، متى ورد على محل مملوك للمتصرف طبقا للمادة 204 وذلك مع مراعاة النصوص الآتية :"}, {"number": "933", "chapter": "الفصل الثانى", "text": "المنقول الذى لم يعين الا بنوعه لا تنتقل ملكيته الا بإفرازه طبقا للمادة 205."}, {"number": "934", "chapter": "الفصل الثانى", "text": "( 1 ) فى المواد العقارية لا تنتقل الملكية ولا الحدود العينية الأخرى سواء أكان ذلك فيما بين المتعاقدين أن كان فى حق الغير ، الا إذا روعيت الأحكام المبينة فى قانون تنظيم الشهر العقارى. ( 2 ) ويبين قانون الشهر المتقدم الذكر التصرفات والأحكام والسندات التى يجب شهرها سواء أكانت ناقلة للملكية أو غير ناقلة ، ويقرر الأحكام المتعلقة بهذا الشهر. 6 - الشفعة شروط الأخذ بالشفعة :"}, {"number": "935", "chapter": "الفصل الثانى", "text": "الشفعة رخصة تجيز فى بيع العقار الحلول محل المشترى فى الأحوال وبالشروط المنصوص عليها فى المواد التالية."}, {"number": "936", "chapter": "الفصل الثانى", "text": "يثبت الحق فى الشفعة : ( أ ) لمالك الرقبة إذا بيع كل حق الانتفاع الملابس لها أو بعضه. ( ب ) للشريك فى الشيوع إذا بيع شئ من العقار الشائع إلى أجنبى. ( جـ ) لصاحب حق الانتفاع إذا بيعت كل الرقبة الملابسة لهذا الحق أو بعضها. ( د ) لمالك الرقبة فى الحكر إذا بيع حق الحكر ، وللمستحكر إذا بيعت الرقبة. ( هـ ) للجار المالك فى الأحوال الآتية : 1 – إذا كانت العقارات من المبانى أو من الأراضى المعدة للبناء سواء أكانت فى المدن أم فى القرى. 2 - إذا كان للأرض المبيعة حق ارتفاق على أرض الجار ، أو كان حق الارتفاق لأرض الجار على الأرض المبيعة. 3 - إذا كانت أرض الجار ملاصقة للأرض المبيعة من جهتين وتساوى من القيمة نصف ثمن الأرض المبيعة على الأقل."}, {"number": "937", "chapter": "الفصل الثانى", "text": "( 1 ) إذا تزاحم الشفعاء يكون استعمال حق الشفعة على حسب الترتيب المنصوص عليه فى المادة السابقة. ( 2 ) وإذا تزاحم الشفعاء من طبقة واحدة ، فاستحقاق كل منهم للشفعة يكون على قدر نصيبه. ( 3 ) فإذا كان المشترى قد توافرت فيه الشروط التى كانت بجعله شفيعا بمقتضى نص المادة - السابقة ، فانه يفضل على الشفعاء الذين هم من طبقته أو من طبقة ادنى ، ولكن يتقدمه الذين هم من طبقة أعلى."}, {"number": "938", "chapter": "الفصل الثانى", "text": "إذا اشترى شخص عينا تجوز الشفعة فيها ثم باعها قبل أن تعلن أية رغبة فى الأخذ بالشفعة أو قبل أن يتم تسجيل هذه الرغبة طبقا للمادة 942 ، فلا يجوز الأخذ بالشفعة الا من المشترى الثانى وبالشروط التى اشترى بها."}, {"number": "939", "chapter": "الفصل الثانى", "text": "( 1 ) لا يجوز الأخذ بالشفعة : ( أ ) اذا حصل البيع بالمزاد العلنى وفقا لإجراءات رسمها القانون. ( ب ) إذا وقع البيع بين الأصول والفروع أو بين الزوجين أو بين الأقارب لغاية الدرجة الرابعة أو بين الأصهار لغاية الدرجة الثانية. ( جـ ) إذا كان العقار قد بيع ليجعل محل عبادة أو ليلحق بمحل عبادة ( 2 ) ولا يجوز للوقف أن يأخذ بالشفعة. إجراءات الشفعة"}, {"number": "940", "chapter": "الفصل الثانى", "text": "على من يريد الأخذ بالشفعة أن يعلن - رغبته فيها إلى كل من البائع والمشترى خلال خمسة عشر يوما من تاريخ الإنذار الرسمى الذى يوجهه إليه البائع أو المشترى والا سقط حقه. ويزاد على تلك المدة ميعاد المسافة إذا اقتضى الأمر ذلك."}, {"number": "941", "chapter": "الفصل الثانى", "text": "يشتمل الإنذار الرسمى المنصوص عليه فى المادة السابقة على البيانات الآتية والا كان باطلا. ( أ ) بيان العقار الجائز أخذه بالشفعة بيانا كافيا. ( ب ) كيان الثمن والمصروفات الرسمية وشروط البيع واسم كل من البائع والمشترى ولقبه وصناعته وموطنه."}, {"number": "942", "chapter": "الفصل الثانى", "text": "( 1 ) إعلان الرغبة بالأخذ بالشفعة يجب أن يكون رسمها والا كان باطلا. ولا يكون هذا الإعلان حجة على الغير الا إذا سجل. ( 2 ) وخلال ثلاثين يوما على أثر من تاريخ هذا الإعلان يجب أن يودع خزانة المحكمة الكائن فى دائرتها العقار كل الثمن الحقيقى الذى من به البيع ، مع مراعاة أن يكون هذا الإيداع قبل رفع الدعوى بالشفعة ، فإن لم يتم الإيداع فى هذا الميعاد على الوجه المتقدم سقط حق الأخذ بالشفعة."}, {"number": "943", "chapter": "الفصل الثانى", "text": "ترفع دعوى الشفعة على البائع والمشترى أمام المحكمة الكائن فى دائرتها العقار وتقيد بالجدول. ويكون كل ذلك فى ميعاد ثلاثين يوما من تاريخ الإعلان المنصوص عليه فى المادة السابقة والا سقط الحق فيها ويحكم فى الدعوى على وجه السرعة."}, {"number": "944", "chapter": "الفصل الثانى", "text": "الحكم الذى يصدر نهائيا بثبوت الشفعة يعتبر سندا لملكية الشفيع ، وذلك دون إخلال بالقواعد المتعلقة بالتسجيل. آثار الشفعة :"}, {"number": "945", "chapter": "الفصل الثانى", "text": "( 1 ) يحل الشفيع قبل البائع محل المشترى فى جميع حقوقه وإلتزاماته. ( 2 ) وإنما لا يحق له الانتفاع بالاجل الممنوح للمشترى فى دفع الثمن الا برضاء البائع. ( 3 ) وإذا استحق العقار للغير بعد أخذه ، بالشفعة ، فليس للشفيع أن يرجع الا على البائع."}, {"number": "946", "chapter": "الفصل الثانى", "text": "( 1 ) إذا ثنى المشترى فى العقار المشفوع أو غرس فيه اشجارا قبل إعلان الرغبة فى الشفعة ، كان الشفيع / ملزما تبعا لما يختار المشترى أن يدفع له اما المبلغ الذى انفقه أو مقدار ما زاد فى قيمة العقار بسبب البناء أو الغراس. ( 2 ) واما إذا حصل البناء أو الغراس بعد إعلان الرغبة فى الشفعة ، كان للشفيع أن يطلب الازالة. فإذا اختار أن يستبقى البناء أو الغراس فلا يلتزم الا بدفع قيمة أدوات البناء وأجرة العمل أو نفقات الغراس."}, {"number": "947", "chapter": "الفصل الثانى", "text": "لا يسرى فى حق الشفيع أى ومن رسمى أو أى حق اختصاص أخذ ضد المشترى ولا أى بيع يصدر من المشترى ولا أى حق عينى رتبه أو ترتب ضده إذا كان كل ذلك قد تم بعد التاريخ الذى سجل فيه إعلان الرغبة فى الشفعة. ويبقى مع ذلك للدائنين المقيدين ما كان لهم من حقوق الأولوية فيما آل للمشترى من ثمن العقار. سقوط الشفعة :"}, {"number": "948", "chapter": "الفصل الثانى", "text": "يسقط الحق فى الأخذ بالشفعة فى الأحوال الآتية : ( أ ) إذ نزل الشفيع عن حقه فى الأخذ بالشفعة ولو قبل البيع. ( ب ) إذا انقضت أربعة اشهر من يوم تسجيل عقد البيع. ( جـ ) فى الأحوال الأخرى التى نص عليها القانون. 7 - الحيازة كسب الحيازة وانتقالها وزوالها :"}, {"number": "949", "chapter": "الفصل الثانى", "text": "( 1 ) لا تقوم الحيازة على عمل يأتيه شخص على انه مجرد رخصة من المباحات أو عمل يتحمله الغير على سبيل التسامح. ( 2 ) وإذا اقترنت بإكراه أو حصلت خفية أو كان فيها لبس فلا يكون لها أثر قبل من وقع عليه الإكراه أو أخفيت عنه الحيازة أو التبس عليه أمرها. الا من الوقت الذى تزول فيه مادة العيوب."}, {"number": "950", "chapter": "الفصل الثانى", "text": "يجوز لغير المميز أن يكسب الحيازة عن طريق من ينوب عنه نيابة قانونية."}, {"number": "951", "chapter": "الفصل الثانى", "text": "( 1 ) تصح الحيازة بالوساطة متى كان الوسيط يباشرها باسم الحائز وكان متصلا به اتصالا يلزمه الائتمار بأوامره فيما يتعلق بهده الحيازة ( 2 ) وعند الشك يفترض أن مباشرة الحيازة انما يحوز لنفسه ، فإن كانت استمرارا لحيازة سابقة أفترض أن هذا الاستمرار هو لحساب البادئ بها."}, {"number": "952", "chapter": "الفصل الثانى", "text": "تنتقل الحيازة من الحائز إلى غيره إذا اتفقا على ذلك وكان فى استطاعة من انتقلت إليه الحيازة أن يسيطر على الحق الواردة عليه الحيازة ولو لم يكن هناك تسلم مادى للشئ موضوع هذا الحق."}, {"number": "953", "chapter": "الفصل الثانى", "text": "يجوز أن يتم نقل الحيازة دون تسليم مادى إذا استمر الحائز واضعا يده لحساب من يخلفه فى الحيازة أو استمر الخلف واضعا يده ولكن لحساب نفسه."}, {"number": "954", "chapter": "الفصل الثانى", "text": "( 1 ) تسليم السندات المعطاه عن البضائع المعهود بها إلى أمين النقل أو المودعة فى المخازن يقوم مقام تسليم البضائع ذاتها. ( 2 ) على انه إذا تسلم شخص عدم المستندات وتسلم آخر البضاعة ذاتها وكان كلاهما حسن النية فإن الأفضلية تكون لمن تسلم البضاعة."}, {"number": "955", "chapter": "الفصل الثانى", "text": "( 1 ) تنتقل الحيازة للخلف العام بصفاتها على انه إذا كان السلف سيئ النية واثبت الخلف انه كان فى حيازته حسن النية جاز له أن يتمسك بحسن نيته. ( 2 ) ويجوز للخلف أن من أن يضم إلى حيازته حيازة سلفه فى كل ما يرتبه القانون على الهباؤقن أثر."}, {"number": "956", "chapter": "الفصل الثانى", "text": "تزول الحيازة إذا تخلى الحائز عن سيطرته الفعلية على الحق أو إذا فقد هذه السيطرة بأية طريقة اخرى"}, {"number": "957", "chapter": "الفصل الثانى", "text": "( 1 ) لا تنقضى الحيازة إذا حال دولا مباشرة السيطرة الفعلية على الحق مانع وقتى. ( 2 ) ولكن الحيازة تنقضى إذا استمر هذا المانع سنة كاملة ، وكان ناشئا من حيازة جديدة وقعت رغم إرادة الحائز أو دون علمه. وتحسب السنة ابتلاء من الوقت الذى بدأت فيه الحيازة الجديدة ، إذا بدأت علنا ، أو من وقت علم الهائز الأول بها إذا بدأت خفية. حماية الحيازة ( دعاوى الحيازة الثلاث )"}, {"number": "958", "chapter": "الفصل الثانى", "text": "( 1 ) لحائز العقار إذا فقد الحيازة أن يطلب خلال السنة التالية لفقدها ودها إليه. فإذا كان فقد الحيازة خفية بدا سريان السنة من وقت أن ينكشف ذلك. ( 2 ) ويجوز أيضا أن يسترد الحيازة من كان حائزا بالنيابة عن غيره."}, {"number": "959", "chapter": "الفصل الثانى", "text": "( 1 ) إذا لم يكن من فقد الحيازة قد انقضت على حيازته سنة وقت فقدها فلا يجوز أن يسترد الحيازة الا من شخص لا يستند إلى حيازة أحق بالتفضيل. والحيازة الأحق بالتفضيل هى الحيازة التى تقوم على سند قانونى فإذا لم يكن لدى أى من الحائزين سند أو تعادلت سنداتهم كانت الحيازة الأحق هى الأسبق فى التاريخ. ( 2 ) اما إذا كان فقد الحيازة بالقوة فللحائز فى جميع الأحوال أن يسترد خلال السنة التالية حيازته من المعتدى."}, {"number": "960", "chapter": "الفصل الثانى", "text": "للحائز أن يرفع فى الميعاد القانونى دعوى استرداد الحيازة على من انتقلت إليه حيازة الشئ المغتصب منه ولو كان هذا الأخير حسن النية."}, {"number": "961", "chapter": "الفصل الثانى", "text": "من حاز عقارا واستمر حائزا له سنة كاملة ثم وقع له تعرض فى حيازته جاز أن يرفع خلال السنة التالية دعوى بمنع هذا التعرض."}, {"number": "962", "chapter": "الفصل الثانى", "text": "( 1 ) من حاز عقارا واستمر حائزا له سنة كاملة وخشى لأسباب معقولة التعرض له من جراء أعمال جديدة تهدد حيازته ، كان له أن يرفع الأمر إلى القاضى طالبا وقف هذه الأعمال ، بشرط الا تكون قد تمت ولم ينقض عام على البدء فى العمل الذى يكون من شأنه أن يحدث الضرر. ( 2 ) والقاضى أن يمنع استمرار الأعمال أو أن يأذن فى استمرارها. وفى كلتا الهالتين يجوز للقاضى أن يأمر بتقديم كفالة مناسبة تكونحالة الحكم بوقف الأعمال ضمانا لإصلاح الضرر الناشئ من هذا الوقف ، متى تبين بحكم نهائى أن الاعتراض على استمرارها كان على غير أساس ، وتكون فى حالة الحكم باستمرار الأعمال ضمانا لإزالة هذه الأعمال كلها أو بعضها إصلاحا للضرر الذى يصيب الحائز إذا حصل على حكم نهائى فى مصلحته."}, {"number": "963", "chapter": "الفصل الثانى", "text": "إذا تنازع أشخاص متعددون على حيازة حق واصد اعتبر بصفة مؤقتة أن حائزه هو من له الحيازة المادية ، الا إذا ظهر انه قد حصل على هذه الحيازة بطريقة معيبة."}, {"number": "964", "chapter": "الفصل الثانى", "text": "من كان حائزا للحق اعتبر صاحبه حتى يقوم الدليل على العكس."}, {"number": "965", "chapter": "الفصل الثانى", "text": "(1 ) يعد حسن النية من يحوز الحق وهو يجهل انه يعتدى على حق الغير ، الا إذا كان هذا الحق ناشئا عن خطأ جسيم. ( 2 ) فإذا كان الحائز شخصا معنويا فالعبرة بنية من يمثله. ( 3 ) وحسن النية يفترض دائما ما لم يقم الدليل على العكس."}, {"number": "966", "chapter": "الفصل الثانى", "text": "(1 ) لا تزول صفة مسن النية لدى الحائز الا من الوقت الذى يصبح فيه عالما أن حيازته اعتداء على حق الغير. ( 2 ) ويزول حسن النية من وقت إعلان الحائز بعيوب حيازته فى صحيفة الدعوى ، رب سيئ النية من اغتصب باراه الحيازة من غيره."}, {"number": "967", "chapter": "الفصل الثانى", "text": "تبقى الحيازة محتفظة بالصفة التى بدأت بها وقت كسبها ، ما لم يقم الدليل على عكس ذلك. أثار الحيازة التقادم المكسب"}, {"number": "968", "chapter": "الفصل الثانى", "text": "من حاز منقولا أو عقارا دون أن يكون مالكا له ، أو حاز حقا عينيا على منقول أو عقار دون أن يكون هذا الحق خاصة به ، كان له أن يكسب ملكية الشئ أو الحق العينى إذا استمرت حيازته دون انقطاع خمس عشرة سنة."}, {"number": "969", "chapter": "الفصل الثانى", "text": "(1 ) إذا وقعت الحيازة على عقار أو على حق عينى عقارى وكانت مقترنة بحسن النية ومستندة فى الوقت ذاته إلى سبب صحيح ، فإن مدة التقادم المكسب تكون خمس سنوات. ( 2 ) ولا يشترط توافر حسن النية الا وقت تلقى الحق. ( 3 ) والسبب الصحيح سند يصدر من شخص لا يكون مالكا للشئ أو صاحبا للحق الذى يراد كسبه بالتقادم ، ويجب أن يكون مسجلا طبقا للقانون."}, {"number": "970", "chapter": "الفصل الثانى", "text": "فى جميع الأحوال لا تكتسب حقوق الإرث بالتقادم الا إذا دامت الحيازة مدة ثلاث وثلاثين سنة. ولا يجوز تملك الأموال الخاصة المملوكة للدولة أو للأشخاص الإعتبارية العامة وكذلك أموال الوحدات الاقتصادية التابعة للمؤسسات العامة أو للهيئات العامة وشركات القطاع العام غير التابعة لأيهما والأوقاف الخيرية أو كسب أى حق عينى على هذه الأموال بالتقادم. ولا يجوز التعدى على الأموال المشار إليها بالفقرة السابقة وفى حالة حصول التعدى يكون للوزير المختص حق أزالته إداريا."}, {"number": "971", "chapter": "الفصل الثانى", "text": "إذا ثبت قيام الحيازة فى وقت سابق معين وكانت قائمة حالا ، فإن ذلك يكون قرينة على قيامها فى المدة ما بين الزمنين ، ما لم يقم الدليل على العكس. مادة972 (1 ) ليس لأحد أن يكسب بالتقادم على خلاف سنده. فلا يستطيع أحد أن يغير بنفسه لنفسه سبب حيازته ولا الأصل الذى تقوم عليه هذه الحيازة. ( 2 ) ولكن يستطيع أن يكسب بالتقادم إذا تغيرت صفة حيازته اما بفعل الغير واما بفعل منه يعتبر معارضة لحق المالك. ولكن فى هذه الحالة لا يبدأ سريان التقادم الا من تاريخ هذا التغيير. مادة973 تسرى قواعد التقادم المسقط على التقادم المكسب فيما يتعلق بحساب المدة ووقف التقادم وانقطاعه والتمسك به أمام القضاء والتنازل عنه والاتفاق على تعديل المدة ، وذلك بالقدر الذى لا تتعارض فيه هذه القواعد مع طبيعة التقادم المكسب ، ومع مراعاة الأحكام الآتية : مادة974 أيا كانت مدة التقادم المكسب فانه يقف متى وجد سبب لوقفه. أيا كانت مدة التقادم المكسب فانه يقف متى وجد سبب لوقفه. مادة975 (1 ) ينقطع التقادم المكسب إذا تخلى الحائز عن الحيازة أو فقدها ولو بفعل الغير. ( 2 ) غير أن التقادم لا ينقطع بفقد الحيازة إذا استردها الحائز خلال سنة أو رفع دعوى باستردادها فى هذا الميعاد. تملك المنقول بالحيازة"}, {"number": "976", "chapter": "الفصل الثانى", "text": "(1 ) من حاز بسبب صحيح منقولا أو حقا عينيا على منقول أو سندا لحامله فانه يصبح مالكا له إذا كان حسن النية وقت حيازته. ( 2 ) فإذا كان حسن النية والسبب الصحيح قد توافر لدى الحائز فى إعتبار الشئ خاليا من التكاليف والقيود العينية ، فانه يكسب الملكية خالصة منها. ( 3 ) الحيازة فى ذاتها قرينة على وجود السبب الصحيح وحسن النية ما لم يقم الدليل على عكس ذلك. مادة977 (1 ) يجوز لمالك المنقول أو السند لحامله إذا فقده أو سرق منه أن يسترده ممن يكون حائزا له كحسن نية وذلك خلال ثلاث سنوات من وقت الضياع أو السرقة. ( 2 ) فإذا كان من يوجد الشئ المسروق أو الضائع فى حيازته قد اشتراه بحسن نية فى سوق أو مزاد علنى أو اشتراه ممن يتجر فى مثله ، فإن له أن يطلب ممن يسترد هذا الشئ أن يعجل له الثمن الذى دفعه. تملك الثمار بالحيازة مادة978 (1 ) يكسب الحائز ما يقبضه من ثمار مادام حسن النية ( 2 ) والثمار الطبيعية أو المستحدثة تعتبر مقبوضة من يوم فصلها. اما الثمار المدنية فتعتبر مقبوضة يوما فيوما."}, {"number": "979", "chapter": "الفصل الثانى", "text": "يكون الحائز سئ النية مسئولا من وقت أن يصبح سيئ النية عن جميع الثمار التى يقبضها والتى قصر فى قبضها غير انه يجوز أن يسترد ما انفقه فى إنتاج مادة الثمار. إسترداد المصروفات"}, {"number": "980", "chapter": "الفصل الثانى", "text": "(1 ) على المالك الذى يرد إليه ملكه أن يؤدى إلى الحائز جميع ما انفقه من المصروفات الضرورية. ( 2 ) اما المصروفات النافعة فيسرى فى شأنها أحكام المادتين ( 3 ) فإذا كانت المصروفات كمالية فليس للحائز أن يطالب بشىء منها ، ومع ذلك يجوز له أن ينزع ما استحدثه من منشآت على أن يعيد الشئ إلى حالته الأولى الا إذا اختار المالك أن يستبقيها مقابل دفع قيمتها مستحقة الازالة."}, {"number": "981", "chapter": "الفصل الثانى", "text": "إذا تلقى شخص الحيازة من مالك أو حائز سابق واثبت انه أدى إلى سلفة ما انفق من مصروفات فإن له أن يطالب بها المسترد."}, {"number": "982", "chapter": "الفصل الثانى", "text": "يجوز للقاضى بناء على طلب المالك أن يقرر ما يراه مناسبا للوفاء بالمصروفات المنصوص عليها فى المادتين السابقتين ، وله أن يقضى بأن يكون الوفاء على أقساط دورية بشرط تقديم الضمانات اللازمة. وللمالك أن يتحلل من هذا الإلتزام إذا هو عجل مبلغا يوازى قيمة هذه الأقساط مخصومة منها فوائدها بالسعر القانونى لغاية مواعيد استحقاقها. المسئولية عن الهلاك"}, {"number": "983", "chapter": "الفصل الثانى", "text": "(1 ) إذا كان الحائز حسن النية وانتفع بالشئ وفقا لما يحسبه من حقه ، فلا يكون مسئولا قبل من هو ملزم برد الشئ إليه عن أى تعويض بسبب هذا الانتفاع. ( 2 ) ولا يكون الحائز مسئولا عما يصيب الشئ من ، أو تلف الا بقدر ما عاد عليه من فانده ترتبت على هذا الهلاك أو التلف."}, {"number": "984", "chapter": "الفصل الثانى", "text": "إذا كان الحائز سيئ النية فانه يكون مسئولا عن هلاك الشئ أو تلفه ولو كان ذلك ناشئا عن حادث مفاجئ ، الا إذا ثبت أن الشئ كان يملك أو يتلف ولو كان باقيا فى يد من يستحقه."}]};